const PRICE_HISTORY_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
const PRICE_HISTORY_MAX_RECORDS = 1000;
const PRICE_HISTORY_KEYS = GOLD_RULES.flatMap((rule) => [`price_buy_${rule.code}`, `price_sell_${rule.code}`, `spread_${rule.code}`]);
function priceSnapshotValues(source) {
  const input = source && typeof source === 'object' ? source : {};
  const snapshot = {};
  for (const key of PRICE_HISTORY_KEYS) snapshot[key] = Math.max(0, Math.round(number(input[key])));
  return snapshot;
}
function pricesEqual(left, right) {
  return PRICE_HISTORY_KEYS.every((key) => Math.round(number(left && left[key])) === Math.round(number(right && right[key])));
}
function prunePriceHistory(records = priceHistory) {
  const threshold = Date.now() - PRICE_HISTORY_WINDOW_MS;
  return (Array.isArray(records) ? records : [])
    .filter((entry) => entry && Date.parse(String(entry.at || '')) >= threshold && entry.prices && typeof entry.prices === 'object')
    .sort((a, b) => Date.parse(a.at) - Date.parse(b.at))
    .slice(-PRICE_HISTORY_MAX_RECORDS);
}
function persistPriceHistory() {
  priceHistory = prunePriceHistory(priceHistory);
  writeJson(PRICE_HISTORY_FILE, priceHistory);
  return priceHistory;
}
function appendPriceHistory(snapshot, source = 'web', at = new Date().toISOString(), force = false) {
  const normalized = priceSnapshotValues(snapshot);
  const last = priceHistory.length ? priceHistory[priceHistory.length - 1] : null;
  if (!force && last && pricesEqual(last.prices, normalized)) return last;
  const entry = { at: new Date(at).toISOString(), source: cleanLabelText(source, 60) || 'web', prices: normalized };
  priceHistory.push(entry);
  persistPriceHistory();
  return entry;
}
