      writeJsonAsyncQueued(KBL_AI_V5_PENDING_FILE, kblAiV5PendingRows.slice(0,KBL_AI_V5_MAX_PENDING)),
      writeJsonAsyncQueued(KBL_AI_V5_CACHE_FILE, kblAiV5WebCache)
