  const sources = Array.isArray(reference.sources) ? reference.sources.filter((x)=>x&&x.url).slice(0,5).map((x)=>({title:cleanLabelText(x.title,180),url:String(x.url).slice(0,900)})) : [];
  if (!sources.length) return; // chỉ học khi có grounding source cụ thể
