      trackingNumber:cleanLabelText(t&&(t.tracking_number||t.trackingNumber),160),
      slug:cleanLabelText(t&&t.slug,80),
      status:cleanLabelText(t&&(t.tag||t.delivery_status||t.subtag),120),
      expectedDelivery:cleanLabelText(t&&(t.expected_delivery||t.expected_delivery_date),80),
