  const cutoff=Date.now()-90*86400000, visitorDetailCutoff=Date.now()-8*86400000;
  const entries=Object.entries(kblTraffic.days||{}).filter(([day])=>{const t=Date.parse(day+'T00:00:00Z');return Number.isFinite(t)&&t>=cutoff;}).sort((a,b)=>a[0].localeCompare(b[0]));
