function applyPosLoyaltySale(input, req = null) {
  const invoiceId = cleanLabelText(input && input.invoiceId, 100);
  const phone = phoneKey(input && input.phone);
  if (!invoiceId || !/^0[0-9]{8,11}$/.test(phone)) return { success:false, status:400, message:'Thiếu mã hóa đơn POS hoặc số điện thoại khách hợp lệ.' };
  const duplicate = loyaltyLedger.find((row) => String(row.invoiceId || '') === invoiceId);
  if (duplicate) {
    const customer = customers.find((c)=>String(c.id)===String(duplicate.customerId)) || customers.find((c)=>phoneKey(c.phone)===phone) || null;
    return { success:true, duplicate:true, row:duplicate, customer, loyalty:loyaltyAdminSummary(customer, n10Year(duplicate.soldAt)) };
  }
  if (!input || !Object.prototype.hasOwnProperty.call(input, 'realizedProfit')) return { success:false, status:400, message:'POS phải gửi trường realizedProfit để hệ thống ghi nhận hóa đơn và tính điểm.' };
  const realizedProfit = Math.max(-1000000000000, Math.min(1000000000000, Math.round(number(input.realizedProfit))));
  const saleTotal = Math.max(-1000000000000, Math.min(1000000000000, Math.round(number(input.saleTotal))));
  const eventType = ['sale','return','adjustment'].includes(String(input.eventType||'').toLowerCase()) ? String(input.eventType).toLowerCase() : (realizedProfit < 0 ? 'return' : 'sale');
  const soldAtRaw = String(input.soldAt || '').trim();
  const soldAtDate = soldAtRaw ? new Date(soldAtRaw) : new Date();
  const soldAt = Number.isFinite(soldAtDate.getTime()) ? soldAtDate.toISOString() : new Date().toISOString();
  const customer = upsertCustomerProfile({ phone, name:cleanLabelText(input.customerName,100) }, null, null);
  if (!customer) return { success:false, status:400, message:'Không tạo được hồ sơ khách từ dữ liệu POS.' };
  const beforePoints = Math.max(0, Math.floor(number(customer.loyaltyPoints)));
  const beforeRemainder = Math.max(0, Math.round(number(customer.loyaltyProfitRemainder)));
  const beforeProfitNet = beforePoints * LOYALTY_POINT_PROFIT_VND + beforeRemainder;
  const afterProfitNet = Math.max(0, beforeProfitNet + realizedProfit);
  const afterPoints = Math.floor(afterProfitNet / LOYALTY_POINT_PROFIT_VND);
  const afterRemainder = afterProfitNet % LOYALTY_POINT_PROFIT_VND;
  const pointsAdded = afterPoints - beforePoints;
  customer.loyaltyPoints = afterPoints;
  customer.loyaltyProfitRemainder = afterRemainder;
  customer.customerTier = afterPoints >= LOYALTY_VIP_POINTS ? 'VIP' : (number(customer.completedOrders) > 0 ? 'Cũ' : (afterPoints > 0 ? 'Cũ' : 'Mới'));
  if (beforePoints < LOYALTY_VIP_POINTS && afterPoints >= LOYALTY_VIP_POINTS) customer.vipSince = soldAt;
  if (beforePoints >= LOYALTY_VIP_POINTS && afterPoints < LOYALTY_VIP_POINTS) customer.vipSince = '';
  customer.lastLoyaltyAt = soldAt;
  const row = {
    id:'LY-'+crypto.randomBytes(9).toString('hex').toUpperCase(), invoiceId, customerId:customer.id, phoneHash:shortHash(phone),
    saleTotal, realizedProfit, eventType, pointsAdded, pointsBefore:beforePoints, pointsAfter:afterPoints,
    remainderBefore:beforeRemainder, remainderAfter:afterRemainder, soldAt, createdAt:new Date().toISOString(), source:'pos-sync',
    publicNote:cleanLabelText(input.publicNote || (eventType==='return'?'POS đã xác nhận giao dịch trả hàng/điều chỉnh':'Hóa đơn đã được POS xác nhận'),160)
  };
  loyaltyLedger.unshift(row);
  loyaltyLedger = loyaltyLedger.slice(0, 50000);
  writeJson(LOYALTY_LEDGER_FILE, loyaltyLedger);
  writeJson(CUSTOMERS_FILE, customers);
  if (req) auditEvent(req,'loyalty.pos-sale','ok',{invoiceIdHash:shortHash(invoiceId),customerId:customer.id,pointsAdded,pointsAfter:afterPoints,vipReached:beforePoints<LOYALTY_VIP_POINTS&&afterPoints>=LOYALTY_VIP_POINTS});
  return { success:true, duplicate:false, row, customer, loyalty:loyaltyAdminSummary(customer, n10Year(soldAt)), vipReached:beforePoints < LOYALTY_VIP_POINTS && afterPoints >= LOYALTY_VIP_POINTS, vipRevoked:beforePoints >= LOYALTY_VIP_POINTS && afterPoints < LOYALTY_VIP_POINTS };
}
function reversePosLoyaltyInvoice(invoiceId, req = null, reason = 'POS đã hủy hóa đơn sai') {
  const originalId = cleanLabelText(invoiceId, 100);
  if (!originalId) return { success:false, status:400, message:'Thiếu mã hóa đơn cần hoàn tác điểm.' };
  const original = loyaltyLedger.find((row) => row && String(row.invoiceId || '') === originalId && String(row.source || '').startsWith('pos-sync'));
  if (!original) return { success:true, skipped:true, message:'Hóa đơn này chưa từng cộng/trừ điểm trên website.', originalInvoiceId:originalId };
  if (original.reversedBy) {
    const existing = loyaltyLedger.find((row) => row && String(row.id || '') === String(original.reversedBy));
    return { success:true, duplicate:true, row:existing || null, originalInvoiceId:originalId };
  }
  const existingReverse = loyaltyLedger.find((row) => row && String(row.originalInvoiceId || '') === originalId && String(row.eventType || '') === 'void');
  if (existingReverse) {
    original.reversedBy = existingReverse.id;
    original.reversedAt = original.reversedAt || existingReverse.createdAt || new Date().toISOString();
    writeJson(LOYALTY_LEDGER_FILE, loyaltyLedger);
    return { success:true, duplicate:true, row:existingReverse, originalInvoiceId:originalId };
  }
  const customer = customers.find((c) => String(c.id || '') === String(original.customerId || '')) || null;
  if (!customer) return { success:false, status:409, message:'Không tìm thấy CRM gốc của giao dịch để hoàn tác điểm an toàn.' };
  const beforePoints = Math.max(0, Math.floor(number(customer.loyaltyPoints)));
  const beforeRemainder = Math.max(0, Math.round(number(customer.loyaltyProfitRemainder)));
  const beforeProfitNet = beforePoints * LOYALTY_POINT_PROFIT_VND + beforeRemainder;
  const reversalProfit = -Math.round(number(original.realizedProfit));
  const reversalSale = -Math.round(number(original.saleTotal));
  const afterProfitNet = Math.max(0, beforeProfitNet + reversalProfit);
  const afterPoints = Math.floor(afterProfitNet / LOYALTY_POINT_PROFIT_VND);
  const afterRemainder = afterProfitNet % LOYALTY_POINT_PROFIT_VND;
  const pointsAdded = afterPoints - beforePoints;
  const now = new Date().toISOString();
  customer.loyaltyPoints = afterPoints;
  customer.loyaltyProfitRemainder = afterRemainder;
  customer.customerTier = afterPoints >= LOYALTY_VIP_POINTS ? 'VIP' : (number(customer.completedOrders) > 0 || afterPoints > 0 ? 'Cũ' : 'Mới');
  if (beforePoints >= LOYALTY_VIP_POINTS && afterPoints < LOYALTY_VIP_POINTS) customer.vipSince = '';
  customer.lastLoyaltyAt = now;
  const reverseId = 'LY-' + crypto.randomBytes(9).toString('hex').toUpperCase();
  const row = {
    id:reverseId,
    invoiceId:cleanLabelText(`VOID-${originalId}`,100),
    originalInvoiceId:originalId,
    customerId:customer.id,
    phoneHash:original.phoneHash || '',
    saleTotal:reversalSale,
    realizedProfit:reversalProfit,
    eventType:'void',
    pointsAdded,
    pointsBefore:beforePoints,
    pointsAfter:afterPoints,
    remainderBefore:beforeRemainder,
    remainderAfter:afterRemainder,
    soldAt:now,
    createdAt:now,
    source:'pos-sync-reversal',
    publicNote:cleanLabelText(reason,160)
  };
  original.reversedBy = reverseId;
  original.reversedAt = now;
  loyaltyLedger.unshift(row);
  loyaltyLedger = loyaltyLedger.slice(0,50000);
  writeJson(LOYALTY_LEDGER_FILE, loyaltyLedger);
  writeJson(CUSTOMERS_FILE, customers);
  if (req) auditEvent(req,'loyalty.pos-void','ok',{invoiceIdHash:shortHash(originalId),customerId:customer.id,pointsAdded,pointsAfter:afterPoints});
  return { success:true, duplicate:false, row, original, customer, loyalty:loyaltyAdminSummary(customer,n10Year(original.soldAt)), vipRevoked:beforePoints>=LOYALTY_VIP_POINTS&&afterPoints<LOYALTY_VIP_POINTS };
}

function sharePolicy() { return { rewardTryOn:Math.min(20,Math.max(1,Math.floor(number(n10Settings.shareRewardTryOn,3)))), maxRewardsPerDay:Math.min(10,Math.max(1,Math.floor(number(n10Settings.shareRewardMaxPerDay,2)))) }; }
