  const hash=customerTokenHash(token), row=shareEvents.find((item)=>item&&item.tokenHash===hash);
  if(!row) return { rewarded:false, reason:'missing' };
  if(row.rewardedAt) return { rewarded:false, reason:'already', row };
  if(Date.parse(row.expiresAt||'')<Date.now()) return { rewarded:false, reason:'expired', row };
  const owner=users.find((u)=>u.id===row.ownerUserId); if(!owner) return { rewarded:false, reason:'owner-missing', row };
  const current=sessionUser(req); if(current&&current.id===owner.id) return { rewarded:false, reason:'self', row };
