  const ipHash=shortHash(`${req.ip||''}|${req.get('user-agent')||''}`);
  if(shareEvents.some((item)=>item&&item.ownerUserId===owner.id&&item.visitorHash===ipHash&&item.rewardedAt&&Date.now()-Date.parse(item.rewardedAt)<86400000)) return { rewarded:false, reason:'repeat-visitor', row };
  const add=Math.min(20,Math.max(1,Math.floor(number(row.rewardTryOn,policy.rewardTryOn))));
  owner.tryOnBonusRemaining=Math.min(500,Math.max(0,Math.floor(number(owner.tryOnBonusRemaining)))+add);
  row.rewardedAt=new Date().toISOString(); row.visitorHash=ipHash; row.rewardGranted=add; row.rewardMode='share-visitor-open';
  writeJson(USERS_FILE,users); writeJson(SHARE_EVENTS_FILE,shareEvents);
  const product=products.find((p)=>String(p.id)===String(row.productId)); if(product) recordProductMetric(product,'share');
  auditEvent(req,'share.reward','ok',{ownerUserId:owner.id,productId:row.productId,sku:row.sku,reward:add});
