function productPrivateCost(product) {
  if (!product) return 0;
  const direct = Math.max(0, number(product.totalCost));
  if (direct) return direct;
  return Math.max(0, number(product.goldCostTotal)) + Math.max(0, number(product.originalWage)) + Math.max(0, number(product.processCost));
}
function productPrivateProfit(product) {
  if (!product) return { cost: 0, sale: 0, profit: 0, marginPct: 0 };
  const sale = Math.max(0, priceForProduct(product)), cost = productPrivateCost(product);
  const profit = cost > 0 ? Math.max(0, sale - cost) : 0;
  return { cost, sale, profit, marginPct: sale > 0 && profit > 0 ? profit / sale * 100 : 0 };
}
