function kblPromptDayKey(ts=Date.now()){
  const d=new Date(ts);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function kblPromptSanitizePlatform(row){
  const src=row&&typeof row==='object'?row:{};
  const id=String(src.id||'').toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,40);
  const label=cleanLabelText(src.label||'',80);
  const url=safeHttpsUrl(src.url)||'';
  return id&&label&&url?{id,label,url,enabled:src.enabled!==false}:null;
}
function kblPromptDefaultState(){
  return {
    version:KBL_PROMPT_AI_VERSION,
    settings:{
      bankId:'',accountNo:'',accountName:'',
      packages:KBL_PROMPT_DEFAULT_PACKAGES.map(x=>({...x})),
      platforms:{image:KBL_PROMPT_DEFAULT_PLATFORMS.image.map(x=>({...x})),video:KBL_PROMPT_DEFAULT_PLATFORMS.video.map(x=>({...x}))}
    },
    accounts:{},orders:[],usage:[],updatedAt:''
  };
}
function kblPromptNormalizeState(raw){
  const base=kblPromptDefaultState(),src=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
  const settings=src.settings&&typeof src.settings==='object'&&!Array.isArray(src.settings)?src.settings:{};
  const packages=(Array.isArray(settings.packages)?settings.packages:base.settings.packages).map((p,i)=>{
    const id=String(p&&p.id||`p${i+1}`).toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,30)||`p${i+1}`;
    return {id,credits:Math.max(1,Math.min(100000,Math.round(number(p&&p.credits,base.settings.packages[i]?.credits||100)))),priceVnd:Math.max(1000,Math.min(100000000,Math.round(number(p&&p.priceVnd,base.settings.packages[i]?.priceVnd||10000)))),enabled:p&&p.enabled!==false};
  }).slice(0,10);
  const srcPlatforms=settings.platforms&&typeof settings.platforms==='object'?settings.platforms:{};
  const platforms={};
  for(const mode of ['image','video']){
    const rows=(Array.isArray(srcPlatforms[mode])?srcPlatforms[mode]:base.settings.platforms[mode]).map(kblPromptSanitizePlatform).filter(Boolean);
    platforms[mode]=rows.length?rows.slice(0,16):base.settings.platforms[mode].map(x=>({...x}));
  }
  const accounts={};
  for(const [uid,a] of Object.entries(src.accounts&&typeof src.accounts==='object'&&!Array.isArray(src.accounts)?src.accounts:{})){
    if(!/^u_[a-f0-9]{16,}$/i.test(uid))continue;
    const x=a&&typeof a==='object'?a:{};
    const totalFinalized=Math.max(0,Math.round(number(x.totalFinalized)));
    const totalCreditsBought=Math.max(0,Math.round(number(x.totalCreditsBought)));
    const hasWelcomeField=Object.prototype.hasOwnProperty.call(x,'welcomeFreeGranted');
    const migrateWelcome=!hasWelcomeField && totalFinalized===0 && totalCreditsBought===0;
    const welcomeFreeGranted=hasWelcomeField
      ? Math.max(0,Math.min(KBL_PROMPT_WELCOME_FREE,Math.round(number(x.welcomeFreeGranted))))
      : (migrateWelcome?KBL_PROMPT_WELCOME_FREE:0);
    const baseCredits=Math.max(0,Math.min(10000000,Math.round(number(x.credits))));
    accounts[uid]={
      credits:Math.max(0,Math.min(10000000,baseCredits+(migrateWelcome?KBL_PROMPT_WELCOME_FREE:0))),
      welcomeFreeGranted,
      profile:x.profile&&typeof x.profile==='object'&&!Array.isArray(x.profile)?x.profile:{},
      businessContext:x.businessContext&&typeof x.businessContext==='object'&&!Array.isArray(x.businessContext)?x.businessContext:{},
      consultDay:cleanLabelText(x.consultDay||'',20),
      consultCalls:Math.max(0,Math.min(1000,Math.round(number(x.consultCalls)))),
      totalFinalized,
      totalCreditsBought,
      createdAt:cleanLabelText(x.createdAt||'',80),
      updatedAt:cleanLabelText(x.updatedAt||'',80)
    };
  }
  const orders=(Array.isArray(src.orders)?src.orders:[]).filter(x=>x&&typeof x==='object').slice(-5000);
  const usage=(Array.isArray(src.usage)?src.usage:[]).filter(x=>x&&typeof x==='object').slice(-10000);
  return {version:KBL_PROMPT_AI_VERSION,settings:{bankId:cleanLabelText(settings.bankId||'',40),accountNo:cleanLabelText(settings.accountNo||'',50).replace(/\s+/g,''),accountName:cleanLabelText(settings.accountName||'',120),packages,platforms},accounts,orders,usage,updatedAt:cleanLabelText(src.updatedAt||'',80)};
}
let kblPromptState=kblPromptNormalizeState(readJson(PROMPT_AI_FILE,kblPromptDefaultState()));
function kblPromptSave(){
  kblPromptState=kblPromptNormalizeState(kblPromptState);
  kblPromptState.updatedAt=new Date().toISOString();
  writeJson(PROMPT_AI_FILE,kblPromptState);
  return kblPromptState;
}
function kblPromptAccount(user,create=true){
  if(!user)return null;
  let row=kblPromptState.accounts[user.id];
  if(!row&&create){
    row={credits:KBL_PROMPT_WELCOME_FREE,welcomeFreeGranted:KBL_PROMPT_WELCOME_FREE,profile:{},businessContext:{},consultDay:'',consultCalls:0,totalFinalized:0,totalCreditsBought:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
    kblPromptState.accounts[user.id]=row;kblPromptSave();
  }
  return row||null;
}
