function kblPromptMergeBusinessContext(current,update){
  const a=kblPromptBusinessContext(current),b=kblPromptBusinessContext(update),out={...a};
  for(const key of ['summary','currentGoal','challenges','priorities','channels','offers','stage','dataNotes'])if(b[key])out[key]=b[key];
  out.updatedAt=new Date().toISOString();return out;
}
function kblPromptImages(input){
  const rows=Array.isArray(input)?input:(input?[input]:[]),out=[];let total=0;
  for(const raw of rows.slice(0,10)){
    const img=parseDataImage(String(raw||''),3500000);if(!img)continue;
    const bytes=Math.floor((img.data.length*3)/4);total+=bytes;if(total>18*1024*1024)break;
    out.push(img);
  }
  return out;
}
function kblPromptBriefPromptCount(brief){
  const b=brief&&typeof brief==='object'&&!Array.isArray(brief)?brief:{};
  const mode=String(b.outputMode||'').toLowerCase();
  if(mode==='separate'||mode==='individual'||mode==='multiple')return Math.min(10,Math.max(1,Math.round(number(b.promptCount,1))));
  return 1;
}

