function kblPromptConsultAllowance(account){
  const day=kblPromptDayKey();
  if(account.consultDay!==day){account.consultDay=day;account.consultCalls=0;}
  return {day,used:account.consultCalls,max:KBL_PROMPT_CONSULT_DAILY_MAX,remaining:Math.max(0,KBL_PROMPT_CONSULT_DAILY_MAX-account.consultCalls)};
}
function kblPromptHistory(input){
  const rows=Array.isArray(input)?input:[];
  return rows.slice(-KBL_PROMPT_MAX_SESSION_TURNS*2).map(r=>({
    role:String(r&&r.role)==='assistant'?'assistant':'user',
    text:kblPromptText(r&&r.text,1600)
  })).filter(r=>r.text);
}
function kblPromptStrongModelRank(modelId){
  const id=kblGeminiModelId(modelId).toLowerCase();
  if(!/^gemini-/.test(id)||/(image|embedding|embed|tts|audio|live|veo|omni|transcribe|robot)/.test(id))return -1;
  const m=id.match(/^gemini-(\d+)(?:\.(\d+))?(?:\.(\d+))?-/);if(!m)return -1;
  const major=Number(m[1]||0),minor=Number(m[2]||0),patch=Number(m[3]||0);
  const family=id.includes('-pro')?3:id.includes('-flash')&&!id.includes('lite')?2:id.includes('-flash-lite')?1:0;
  if(!family)return -1;
  const preview=/(preview|experimental|\bexp\b)/.test(id);
  // Tự nâng đời model trước (vd Gemini 4 Flash > Gemini 3 Pro), rồi mới ưu tiên Pro > Flash trong cùng thế hệ.
  return major*1000000000000+family*1000000000+minor*1000000+patch*1000-(preview?25:0);
}
let kblPromptGeminiCache={at:0,candidates:[],selected:'',lastError:''};
async function kblPromptGeminiCandidates(){
  if(GEMINI_TEXT_API_KEY!==GEMINI_API_KEY)return [GEMINI_ECONOMY_TEXT_MODEL];
  const override=kblGeminiModelId(KBL_PROMPT_GEMINI_MODEL_OVERRIDE);
  if(override&&override!=='auto')return [...new Set([override,kblGeminiRuntimeTextModel(),'gemini-3.8-flash','gemini-3.7-flash'].filter(Boolean))];
  if(kblPromptGeminiCache.candidates.length&&Date.now()-kblPromptGeminiCache.at<KBL_PROMPT_GEMINI_REFRESH_MS)return kblPromptGeminiCache.candidates;
  try{
    const rows=await kblGeminiAutoListModels(),byId=new Map();
    for(const row of rows){
      const methods=Array.isArray(row&&row.supportedGenerationMethods)?row.supportedGenerationMethods:Array.isArray(row&&row.supportedActions)?row.supportedActions:[];
      if(!methods.some(x=>String(x||'').toLowerCase()==='generatecontent'))continue;
      const id=kblGeminiModelId(row&&row.baseModelId||row&&row.name),rank=kblPromptStrongModelRank(id);
      if(rank<0)continue;
      if(!byId.has(id)||rank>byId.get(id).rank)byId.set(id,{id,rank});
    }
    const dynamic=[...byId.values()].sort((a,b)=>b.rank-a.rank).map(x=>x.id);
    const fallback=[kblGeminiRuntimeTextModel(),'gemini-3.8-flash','gemini-3.7-flash','gemini-3.6-flash'];
    kblPromptGeminiCache={at:Date.now(),candidates:[...new Set([...dynamic,...fallback].filter(Boolean))].slice(0,8),selected:kblPromptGeminiCache.selected,lastError:''};
  }catch(error){
    kblPromptGeminiCache={at:Date.now(),candidates:[...new Set([kblGeminiRuntimeTextModel(),'gemini-3.8-flash','gemini-3.7-flash','gemini-3.6-flash'].filter(Boolean))],selected:kblPromptGeminiCache.selected,lastError:kblPromptText(error&&error.message,240)};
  }
  return kblPromptGeminiCache.candidates;
}
