// KBL PROMPT AI · DEEPSEEK AUTO MODEL DISCOVERY SAFE.
// Chỉ tự nâng trong dòng Flash text stable. Không tự nhảy sang Pro/vision/experimental để tránh thay đổi chi phí/hành vi ngoài ý muốn.
let kblPromptDeepSeekAutoTimer=null;
let kblPromptDeepSeekAutoRefreshPromise=null;
function kblPromptDeepSeekModelId(value){return String(value||'').trim().slice(0,100)}
function kblPromptDeepSeekBootstrapModel(){
  const m=kblPromptDeepSeekModelId(KBL_PROMPT_DEEPSEEK_BOOTSTRAP_MODEL);
  return /^[a-z0-9._:-]{1,100}$/i.test(m)&&m!=='auto'?m:'deepseek-v4-flash';
}
function kblPromptDeepSeekCandidateScore(id){
  const m=kblPromptDeepSeekModelId(id).toLowerCase();
  if(!m.startsWith('deepseek-')||!m.includes('flash'))return -1;
  if(/vision|image|audio|embed|rerank|ocr/.test(m))return -1;
  const isPreview=/preview|experimental|\bexp\b/.test(m);
  if(isPreview&&!KBL_PROMPT_DEEPSEEK_AUTO_ALLOW_PREVIEW)return -1;
  const v=m.match(/(?:^|-)v(\d+)(?:[._-](\d+))?/i);
  const major=v?Number(v[1]||0):0,minor=v?Number(v[2]||0):0;
  // Stable > preview trong cùng version; version cao hơn luôn ưu tiên.
  return major*1000000+minor*10000+(isPreview?0:5000)+(m==='deepseek-v4-flash'?100:0);
}
function kblPromptDeepSeekAutoDefaultState(){
  const primary=kblPromptDeepSeekBootstrapModel();
  return {version:'1.0.0',enabled:KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED,status:KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED?'waiting':'disabled',primary,fallbacks:[],lastCheckAt:'',lastVerifiedAt:'',nextCheckAt:'',lastError:'',origin:'bootstrap',discoveredCount:0,probeCount:0,checkedModels:[]};
}
function kblPromptDeepSeekAutoNormalize(raw){
  const base=kblPromptDeepSeekAutoDefaultState(),src=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
  const primary=/^[a-z0-9._:-]{1,100}$/i.test(kblPromptDeepSeekModelId(src.primary))?kblPromptDeepSeekModelId(src.primary):base.primary;
  const fallbacks=[...new Set((Array.isArray(src.fallbacks)?src.fallbacks:[]).map(kblPromptDeepSeekModelId).filter(x=>x&&x!==primary&&/^[a-z0-9._:-]{1,100}$/i.test(x)))].slice(0,KBL_PROMPT_DEEPSEEK_AUTO_MAX_FALLBACKS);
  return {...base,...src,version:'1.0.0',enabled:KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED,primary,fallbacks,checkedModels:Array.isArray(src.checkedModels)?src.checkedModels.slice(0,10):[]};
}
let kblPromptDeepSeekAutoState=kblPromptDeepSeekAutoNormalize(readJson(KBL_PROMPT_DEEPSEEK_AUTO_FILE,null));
function kblPromptDeepSeekAutoSave(){try{writeJson(KBL_PROMPT_DEEPSEEK_AUTO_FILE,kblPromptDeepSeekAutoState)}catch(_){}}
function kblPromptDeepSeekRuntimeModel(){
  if(KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED&&kblPromptDeepSeekAutoState&&kblPromptDeepSeekAutoState.primary)return kblPromptDeepSeekModelId(kblPromptDeepSeekAutoState.primary);
  return kblPromptDeepSeekBootstrapModel();
}
function kblPromptDeepSeekRuntimeModels(){
  return [...new Set([kblPromptDeepSeekRuntimeModel(),...(kblPromptDeepSeekAutoState&&Array.isArray(kblPromptDeepSeekAutoState.fallbacks)?kblPromptDeepSeekAutoState.fallbacks:[]),kblPromptDeepSeekBootstrapModel(),'deepseek-v4-flash'].map(kblPromptDeepSeekModelId).filter(x=>/^[a-z0-9._:-]{1,100}$/i.test(x)))].slice(0,1+KBL_PROMPT_DEEPSEEK_AUTO_MAX_FALLBACKS+1);
}
function kblPromptDeepSeekAutoPublicState(){
  const s=kblPromptDeepSeekAutoState||kblPromptDeepSeekAutoDefaultState();
  return {enabled:Boolean(s.enabled),status:s.status,primary:s.primary,fallbacks:s.fallbacks||[],lastCheckAt:s.lastCheckAt,lastVerifiedAt:s.lastVerifiedAt,nextCheckAt:s.nextCheckAt,lastError:s.lastError,origin:s.origin,discoveredCount:s.discoveredCount||0,probeCount:s.probeCount||0,checkedModels:s.checkedModels||[]};
}
async function kblPromptDeepSeekProbeModel(model){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),KBL_PROMPT_DEEPSEEK_AUTO_PROBE_TIMEOUT_MS);
  try{
    const response=await kblAiFetch(`${KBL_PROMPT_DEEPSEEK_BASE}/chat/completions`,{method:'POST',headers:{Authorization:`Bearer ${DEEPSEEK_API_KEY}`,'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({model,messages:[{role:'user',content:'Reply exactly KBL_OK'}],thinking:{type:'disabled'},max_tokens:12,temperature:0})}, "kblPromptDeepSeekProbeModel");
    const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(kblPromptText(data&&data.error&&data.error.message||`DeepSeek HTTP ${response.status}`,220));
    const raw=String(data&&data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content||'').trim();
    if(!raw)throw new Error('DeepSeek probe trả trống.');
    return true;
  }finally{clearTimeout(timer)}
}
async function kblPromptDeepSeekAutoRefresh(origin='scheduler',force=false){
  if(!KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED)return kblPromptDeepSeekAutoPublicState();
  if(!DEEPSEEK_API_KEY){
    kblPromptDeepSeekAutoState={...kblPromptDeepSeekAutoState,status:'missing-key',lastError:'Chưa có DEEPSEEK_API_KEY.',origin:String(origin||'runtime').slice(0,60)};kblPromptDeepSeekAutoSave();return kblPromptDeepSeekAutoPublicState();
  }
  const due=Date.parse(kblPromptDeepSeekAutoState.nextCheckAt||'')||0;
  if(!force&&kblPromptDeepSeekAutoState.lastVerifiedAt&&due&&Date.now()<due)return kblPromptDeepSeekAutoPublicState();
  if(kblPromptDeepSeekAutoRefreshPromise)return kblPromptDeepSeekAutoRefreshPromise;
  kblPromptDeepSeekAutoRefreshPromise=(async()=>{
    const checked=[];
    try{
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),KBL_PROMPT_DEEPSEEK_AUTO_PROBE_TIMEOUT_MS);
      let response,data;
      try{
        response=await kblAiFetch(`${KBL_PROMPT_DEEPSEEK_BASE}/models`,{headers:{Authorization:`Bearer ${DEEPSEEK_API_KEY}`},signal:controller.signal}, "kblPromptDeepSeekAutoRefresh");
        data=await response.json().catch(()=>({}));
      }finally{clearTimeout(timer)}
      if(!response||!response.ok)throw new Error(kblPromptText(data&&data.error&&data.error.message||`DeepSeek models HTTP ${response&&response.status}`,260));
      const discovered=(Array.isArray(data&&data.data)?data.data:[]).map(x=>kblPromptDeepSeekModelId(x&&x.id)).filter(Boolean);
      let candidates=discovered.filter(x=>kblPromptDeepSeekCandidateScore(x)>=0).sort((a,b)=>kblPromptDeepSeekCandidateScore(b)-kblPromptDeepSeekCandidateScore(a));
      candidates=[...new Set([...candidates,kblPromptDeepSeekRuntimeModel(),kblPromptDeepSeekBootstrapModel(),'deepseek-v4-flash'])].filter(x=>kblPromptDeepSeekCandidateScore(x)>=0);
      if(!candidates.length)throw new Error('DeepSeek /models không trả model Flash text phù hợp.');
      const current=kblPromptDeepSeekRuntimeModel(),top=candidates[0],now=new Date().toISOString(),next=new Date(Date.now()+KBL_PROMPT_DEEPSEEK_AUTO_REFRESH_MS).toISOString();
      // COST GUARD: /models dùng để dò miễn phí/metadata. Nếu model mạnh nhất không đổi thì KHÔNG gọi chat/completions probe tốn token.
      if(!force&&kblPromptDeepSeekAutoState.lastVerifiedAt&&top===current){
        kblPromptDeepSeekAutoState={...kblPromptDeepSeekAutoState,status:'ready',lastCheckAt:now,nextCheckAt:next,lastError:'',origin:String(origin||'runtime').slice(0,60),discoveredCount:discovered.length,probeCount:0,checkedModels:[]};kblPromptDeepSeekAutoSave();
        return kblPromptDeepSeekAutoPublicState();
      }
      // Chỉ khi có model Flash mới (hoặc chưa từng verify) mới bỏ chi phí cực nhỏ để probe trước khi promote.
      const verified=[];
      for(const model of candidates.slice(0,1+KBL_PROMPT_DEEPSEEK_AUTO_MAX_FALLBACKS+2)){
        try{await kblPromptDeepSeekProbeModel(model);checked.push({model,ok:true});verified.push(model)}
        catch(error){checked.push({model,ok:false,error:kblPromptText(error&&error.message,160)})}
      }
      if(!verified.length)throw new Error('Không model DeepSeek Flash nào qua probe chat/completions.');
      const chosen=verified[0],fallbacks=verified.filter(x=>x!==chosen).slice(0,KBL_PROMPT_DEEPSEEK_AUTO_MAX_FALLBACKS);
      kblPromptDeepSeekAutoState={...kblPromptDeepSeekAutoState,status:'ready',primary:chosen,fallbacks,lastCheckAt:now,lastVerifiedAt:now,nextCheckAt:next,lastError:'',origin:String(origin||'runtime').slice(0,60),discoveredCount:discovered.length,probeCount:checked.length,checkedModels:checked};kblPromptDeepSeekAutoSave();
      console.log(`KBL Prompt DeepSeek Auto: ${chosen} · ${fallbacks.length} fallback · next check ${next}`);
      return kblPromptDeepSeekAutoPublicState();
    }catch(error){
      const now=new Date().toISOString(),next=new Date(Date.now()+KBL_PROMPT_DEEPSEEK_AUTO_FAILURE_RETRY_MS).toISOString(),message=kblPromptText(error&&error.message||'DeepSeek auto discovery failed',300);
      kblPromptDeepSeekAutoState={...kblPromptDeepSeekAutoState,status:kblPromptDeepSeekAutoState.lastVerifiedAt?'degraded':'fallback',lastCheckAt:now,nextCheckAt:next,lastError:message,origin:String(origin||'runtime').slice(0,60),probeCount:checked.length,checkedModels:checked};kblPromptDeepSeekAutoSave();
      console.warn(`KBL Prompt DeepSeek Auto: ${message} · giữ ${kblPromptDeepSeekRuntimeModel()}`);
      return kblPromptDeepSeekAutoPublicState();
    }
  })().finally(()=>{kblPromptDeepSeekAutoRefreshPromise=null});
  return kblPromptDeepSeekAutoRefreshPromise;
}
async function kblPromptDeepSeekEnsureAutoModel(origin='runtime'){
  if(!KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED)return kblPromptDeepSeekAutoPublicState();
  const due=Date.parse(kblPromptDeepSeekAutoState.nextCheckAt||'')||0;
  if(!kblPromptDeepSeekAutoState.lastVerifiedAt||!due||Date.now()>=due)return kblPromptDeepSeekAutoRefresh(origin,false);
  return kblPromptDeepSeekAutoPublicState();
}
function kblPromptDeepSeekAutoStartScheduler(){
  if(kblPromptDeepSeekAutoTimer||!KBL_PROMPT_DEEPSEEK_AUTO_MODEL_ENABLED||!DEEPSEEK_API_KEY)return;
  kblPromptDeepSeekAutoTimer=setInterval(()=>{kblPromptDeepSeekEnsureAutoModel('scheduler').catch(()=>{})},30*60*1000);if(kblPromptDeepSeekAutoTimer.unref)kblPromptDeepSeekAutoTimer.unref();
  const boot=setTimeout(()=>{kblPromptDeepSeekEnsureAutoModel('boot').catch(()=>{})},12000);if(boot.unref)boot.unref();
}

function kblPromptDeepSeekSystem(mode,profile){
  const common=`Bạn là KBL FINAL PROMPT DIRECTOR. Bạn chỉ được gọi khi khách đã CHỐT phương án. Hãy dùng tối đa năng lực reasoning để tạo đầu ra chính xác, thực dụng và dùng được ngay.
Bạn nhận BUSINESS/CREATIVE BRIEF đã được Gemini Consultant làm rõ. Trước khi trả kết quả, hãy tự kiểm tra nội bộ: mục tiêu, ngành nghề, dữ kiện, ràng buộc, số ảnh, outputMode và số prompt; tự sửa mâu thuẫn nhưng KHÔNG bịa dữ kiện thiếu.
Ưu tiên tuyệt đối: Brand lock/điều cấm > ý định hiện tại đã chốt > dữ liệu ảnh & dữ kiện khách cung cấp > hồ sơ ngành nghề/business strategy > mặc định > tự bổ sung chuyên môn.
Nếu brief nói phải giữ ảnh/sản phẩm gốc, prompt phải nêu rõ uploaded/reference images là authoritative visual references và cấm đổi các đặc điểm nhận diện.
Nếu có quảng cáo, phải giữ CHÍNH XÁC tên/SĐT/địa chỉ/website và nội dung “Muốn khách làm gì sau khi xem?” được cung cấp; không tự sửa chữ/số. Không ép text/branding nếu brief không cần.
Nếu thiếu tên/giá/thông tin sản phẩm: dùng placeholder rõ ràng hoặc yêu cầu model giữ chỗ; tuyệt đối không tự tạo dữ kiện thương mại.
Ngôn ngữ prompt đầu ra: ${profile.language||'English'}.

BATCH / NHIỀU ẢNH:
- outputMode=combined: tạo đúng 1 prompt tổng hợp cho menu/catalog/bảng giá/poster/bộ thiết kế.
- outputMode=separate: tạo đúng promptCount prompt riêng, tương ứng logic với từng ảnh/sản phẩm/đầu ra mà brief mô tả; mỗi prompt phải độc lập, đủ dùng và giữ đúng reference tương ứng.
- Không gộp các prompt riêng thành một prompt mơ hồ.

Chỉ trả JSON: {"prompts":[{"title":"...","prompt":"..."}]} và số phần tử phải đúng promptCount.`;
  if(mode==='video')return common+`
VIDEO: mỗi prompt phải đủ đạo diễn hình ảnh + âm thanh: subject/person, casting/appearance, wardrobe, acting/expression/body movement, product handling, environment/art direction, lighting, shot composition, lens/focus/DOF, camera movement, timing/pacing, continuity, transitions khi cần, ambient sound, SFX, music direction, voice/dialogue khi cần, text/end-card/hành động mong muốn khi phù hợp, negative constraints. Yêu cầu đơn giản có thể one-shot; phức tạp mới chia scene.`;
  return common+`
HÌNH ẢNH: mỗi prompt phải đủ subject/product preservation, styling, composition, environment, lighting, camera angle/lens feel, depth of field, materials/textures/reflections, palette/mood, realism/stylization, platform framing/aspect ratio, typography/brand placement khi cần và negative constraints. Với menu/catalog/bảng giá nhiều ảnh, phải mô tả hierarchy, grid, nhóm sản phẩm, vùng tên/giá/brand/contact và tính đọc được.`;
}
async function kblPromptDeepSeekFinalize({mode,brief,profile}){
  if(!DEEPSEEK_API_KEY)throw new Error('DeepSeek API chưa được cấu hình trên server.');
  kblPromptDeepSeekEnsureAutoModel('finalize').catch(()=>{});
  const models=kblPromptDeepSeekRuntimeModels(),promptCount=kblPromptBriefPromptCount(brief);let lastError='';
  for(const model of models){
    const payload={
      model,
      messages:[
        {role:'system',content:kblPromptDeepSeekSystem(mode,profile)},
        {role:'user',content:`HỒ SƠ KHÁCH:\n${kblPromptProfileText(profile)}\n\nBUSINESS/CREATIVE BRIEF ĐÃ CHỐT:\n${JSON.stringify({...brief,promptCount},null,2)}`}
      ],
      thinking:{type:'enabled'},reasoning_effort:'max',
      response_format:{type:'json_object'},
      max_tokens:Math.min(24000,(mode==='video'?9000:7000)+(promptCount-1)*(mode==='video'?1800:1400))
    };
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),180000);
    try{
      const response=await kblAiFetch(`${KBL_PROMPT_DEEPSEEK_BASE}/chat/completions`,{method:'POST',headers:{Authorization:`Bearer ${DEEPSEEK_API_KEY}`,'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify(payload)}, "kblPromptDeepSeekFinalize");
      const data=await response.json().catch(()=>({}));
      if(!response.ok){lastError=kblPromptText(data&&data.error&&data.error.message||`DeepSeek HTTP ${response.status}`,320);continue}
      const raw=String(data&&data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content||'').trim();
      if(!raw){lastError='DeepSeek trả prompt trống.';continue}
      let parsed;try{parsed=JSON.parse(raw)}catch(_){parsed={prompts:[{title:'Prompt',prompt:raw}]}}
      let prompts=Array.isArray(parsed&&parsed.prompts)?parsed.prompts:parsed&&parsed.prompt?[{title:'Prompt',prompt:parsed.prompt}]:[];
      prompts=prompts.map((x,i)=>({title:kblPromptText(x&&x.title||`Prompt ${i+1}`,120)||`Prompt ${i+1}`,prompt:String(x&&x.prompt||'').trim()})).filter(x=>x.prompt).slice(0,promptCount);
      if(prompts.length!==promptCount){lastError=`DeepSeek trả ${prompts.length}/${promptCount} prompt. Hệ thống sẽ thử model dự phòng.`;continue}
      return {prompt:prompts.map((x,i)=>promptCount>1?`PROMPT ${i+1} — ${x.title}\n${x.prompt}`:x.prompt).join('\n\n──────────\n\n'),prompts,promptCount,model,usage:data.usage||{}};
    }catch(error){lastError=kblPromptText(error&&error.name==='AbortError'?'DeepSeek timeout.':error&&error.message,320)}
    finally{clearTimeout(timer)}
  }
  throw new Error(lastError||'DeepSeek chưa tạo được prompt cuối.');
}
async function kblPromptGeminiFinalizeFallback({mode,brief,profile}){
  if(!KBL_AI_V8_PROMPT_FALLBACK_ENABLED||!GEMINI_TEXT_API_KEY)throw new Error('Gemini Prompt fallback chưa sẵn sàng.');
  const promptCount=kblPromptBriefPromptCount(brief),models=await kblPromptGeminiCandidates();
  const schema={type:'object',additionalProperties:false,properties:{prompts:{type:'array',items:{type:'object',additionalProperties:false,properties:{title:{type:'string'},prompt:{type:'string'}},required:['title','prompt']}}},required:['prompts']};
  let lastError='';
  for(const model of models){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);
    try{
      const system=[kblPromptDeepSeekSystem(mode,profile),KBL_AI_MASTER_CONTRACT,'Bạn là KBL PROMPT FINAL DIRECTOR dự phòng. DeepSeek primary không phản hồi nên bạn phải tạo prompt cuối từ BRIEF ĐÃ CHỐT. Không hỏi lại khách. Không thêm dữ kiện kinh doanh/giá/chứng nhận/công dụng không có trong brief/profile. Giữ đúng promptCount và mọi mustPreserve/constraints.'].join('\n');
      const response=await kblAiFetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,{method:'POST',headers:{'x-goog-api-key':GEMINI_TEXT_API_KEY,'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({system_instruction:{parts:[{text:system}]},contents:[{role:'user',parts:[{text:`HỒ SƠ KHÁCH:\n${kblPromptProfileText(profile)}\n\nBUSINESS/CREATIVE BRIEF ĐÃ CHỐT:\n${JSON.stringify({...brief,promptCount},null,2)}`}]}],generationConfig:geminiTextGenerationConfig(model,{thinkingLevel:'high',temperature:.18,topP:.88,maxOutputTokens:Math.min(16000,5000+promptCount*1400),responseMimeType:'application/json',responseSchema:schema}),store:false})}, "kblPromptGeminiFinalizeFallback");
      const data=await response.json().catch(()=>({}));
      if(!response.ok){lastError=kblPromptText(data&&data.error&&data.error.message||`Gemini HTTP ${response.status}`,320);continue}
      const parsed=JSON.parse(geminiResponseText(data)||'{}');
      const prompts=(Array.isArray(parsed.prompts)?parsed.prompts:[]).map((x,i)=>({title:kblPromptText(x&&x.title||`Prompt ${i+1}`,120)||`Prompt ${i+1}`,prompt:String(x&&x.prompt||'').trim()})).filter(x=>x.prompt).slice(0,promptCount);
      if(prompts.length!==promptCount){lastError=`Gemini fallback trả ${prompts.length}/${promptCount} prompt.`;continue}
      return {prompt:prompts.map((x,i)=>promptCount>1?`PROMPT ${i+1} — ${x.title}\n${x.prompt}`:x.prompt).join('\n\n──────────\n\n'),prompts,promptCount,model:`gemini-fallback:${model}`,usage:data.usageMetadata||{},provider:'gemini-fallback'};
    }catch(error){lastError=kblPromptText(error&&error.name==='AbortError'?'Gemini Prompt fallback timeout.':error&&error.message,320)}finally{clearTimeout(timer)}
  }
  throw new Error(lastError||'Gemini Prompt fallback chưa tạo được prompt cuối.');
}
async function kblPromptFinalizeAgentV8(args){
  let primaryError='';
  try{return await kblPromptDeepSeekFinalize(args)}catch(error){primaryError=kblPromptText(error&&error.message,320)}
  if(KBL_AI_V8_PROMPT_FALLBACK_ENABLED&&GEMINI_API_KEY){
    try {
      const fallback=await kblPromptGeminiFinalizeFallback(args);
      fallback.primaryError=kblAiApi.redact(primaryError);
      return fallback;
    } catch (error) {
      throw new Error('DeepSeek: '+kblAiApi.redact(primaryError)+' | Gemini dự phòng: '+kblAiApi.redact(error&&error.message));
    }
  }
  throw new Error(primaryError||'Prompt Final Director chưa phản hồi.');
}

function kblPromptBuyer(input,user){
  const i=input&&typeof input==='object'?input:{};
  const buyerType=String(i.buyerType)==='business'?'business':'personal';
  const invoiceRequested=Boolean(i.invoiceRequested);
  const personalId=String(i.personalId||'').replace(/\D/g,'').slice(0,15);
  const taxId=String(i.taxId||'').replace(/[^0-9A-Za-z-]/g,'').slice(0,30);
  return {
    fullName:kblPromptText(i.fullName||user&&user.name,120),
    phone:phoneKey(i.phone||user&&user.phone),
    address:kblPromptText(i.address,400),
    buyerType,invoiceRequested,
    personalId:invoiceRequested&&buyerType==='personal'?personalId:'',
    businessName:invoiceRequested&&buyerType==='business'?kblPromptText(i.businessName,180):'',
    taxId:invoiceRequested&&buyerType==='business'?taxId:'',
    invoiceAddress:invoiceRequested?kblPromptText(i.invoiceAddress||i.address,400):'',
    email:invoiceRequested?kblPromptText(i.email,180):''
  };
}
function kblPromptMaskId(value){const s=String(value||'');return s.length>4?'*'.repeat(Math.max(4,s.length-4))+s.slice(-4):s}
function kblPromptPackage(id){return kblPromptState.settings.packages.find(x=>x.id===String(id||'')&&x.enabled!==false)||null}
function kblPromptPublicOrder(order,admin=false){
  if(!order)return null;
  const out={id:order.id,packageId:order.packageId,credits:order.credits,priceVnd:order.priceVnd,status:order.status,transferContent:KBL_PROMPT_TRANSFER_CONTENT,vietQrUrl:order.vietQrUrl||'',createdAt:order.createdAt||'',paidAt:order.paidAt||'',invoiceRequested:Boolean(order.buyer&&order.buyer.invoiceRequested),invoiceStatus:order.invoiceStatus||'none'};
  if(admin){
    out.userId=order.userId;out.buyer={...(order.buyer||{})};
    if(out.buyer.personalId){
      out.buyer.personalIdMasked=kblPromptMaskId(out.buyer.personalId);
      delete out.buyer.personalId; // mặc định không đẩy CCCD đầy đủ xuống browser Admin
    }
  }
  return out;
}
function kblPromptUsageSummary(){
  let deepInput=0,deepOutput=0,deepCached=0,geminiInput=0,geminiOutput=0;
  for(const r of kblPromptState.usage){
    if(r.kind==='final'){
      deepInput+=Math.max(0,number(r.promptTokens));deepOutput+=Math.max(0,number(r.completionTokens));deepCached+=Math.max(0,number(r.cachedTokens));
    }else if(r.kind==='consult'){
      geminiInput+=Math.max(0,number(r.promptTokens));geminiOutput+=Math.max(0,number(r.completionTokens));
    }
  }
  const paid=kblPromptState.orders.filter(o=>o.status==='paid');
  return {consultCalls:kblPromptState.usage.filter(x=>x.kind==='consult').length,finalPrompts:kblPromptState.usage.filter(x=>x.kind==='final').reduce((sum,x)=>sum+Math.max(1,number(x.promptCount,1)),0),deepseek:{inputTokens:deepInput,outputTokens:deepOutput,cachedTokens:deepCached},gemini:{inputTokens:geminiInput,outputTokens:geminiOutput},revenueVnd:paid.reduce((s,o)=>s+Math.max(0,number(o.priceVnd)),0),paidOrders:paid.length,pendingOrders:kblPromptState.orders.filter(o=>o.status==='pending').length};
}

function geminiInteractionImage(payload) {
  for (const step of payload && Array.isArray(payload.steps) ? payload.steps : []) {
    if (!step || step.type !== 'model_output') continue;
    for (const block of Array.isArray(step.content) ? step.content : []) {
      if (block && block.type === 'image' && typeof block.data === 'string' && block.data.length > 100) {
        const mimeType = ['image/png','image/jpeg','image/webp'].includes(String(block.mime_type || '').toLowerCase())
          ? String(block.mime_type).toLowerCase() : 'image/png';
        return { mimeType, data: block.data };
      }
    }
  }
  if (payload && payload.output_image && typeof payload.output_image.data === 'string') {
    return { mimeType: String(payload.output_image.mime_type || 'image/png'), data: payload.output_image.data };
  }
  return null;
}
function tryOnPrompt(mode, product) {
  const placement = {
    ring: 'place the exact reference ring naturally on the most visible ring finger',
    bracelet: 'place the exact reference bracelet naturally around the most visible wrist',
    necklace: 'place the exact reference necklace or pendant naturally around the neck and upper chest',
    earring: 'place the exact reference earring naturally on the most visible ear'
  }[mode] || 'place the exact reference jewelry item on the anatomically correct wearing position';
  return [
    'VIRTUAL JEWELRY TRY-ON — HIGH FIDELITY PRODUCT EDIT.',
    'INPUT IMAGE 1 is the customer photo. INPUT IMAGE 2 is the authoritative product reference from Kim Bao Lam inventory.',
    `Primary task: edit INPUT IMAGE 1 only and ${placement}.`,
    `Inventory identity: product name "${cleanLabelText(product.name,160)}", SKU "${cleanInventoryCode(product.sku)}", gold code "${normalizeGoldCode(product.goldCode) || 'unknown'}".`,
    'PRODUCT FIDELITY IS CRITICAL: reproduce the jewelry from INPUT IMAGE 2 as faithfully as possible. Preserve its silhouette, links, setting, stones, stone count, ornament pattern, clasp, thickness, proportions, gold color and all distinctive design details. Do not redesign, simplify, embellish, add stones, remove stones, change the metal color, or substitute a different item.',
    'CUSTOMER IDENTITY IS CRITICAL: preserve the customer face, body, hand anatomy, fingers, skin texture, nails, hair, clothing, pose, background, camera angle, focal length and scene lighting. Do not beautify, reshape, de-age, change identity, change skin tone, remove scars, alter clothing or replace the background.',
    'INTEGRATION: adjust only scale, perspective, orientation, occlusion, contact shadows, reflections and local color/lighting required for physically plausible wear. Jewelry must follow the body surface and must not float, clip through skin, duplicate, stretch, melt or appear fused to the body.',
    'For rings, respect finger anatomy and believable ring diameter. For bracelets, wrap around the wrist with realistic front/back occlusion. For necklaces, follow the neck/chest contour and gravity. For earrings, attach at the earlobe/piercing area and respect head perspective.',
    'Keep the full original image composition. Do not crop unless absolutely required by the requested output aspect ratio. Do not add text, logos, watermarks, price tags, extra accessories, extra people or decorative graphics.',
    'Output one photorealistic retail try-on image. The result is a visual preview only; prioritize faithful product appearance and natural placement over artistic interpretation.'
  ].join('\n');
}

function geminiGenerateContentImage(payload) {
  for (const candidate of payload && Array.isArray(payload.candidates) ? payload.candidates : []) {
    const parts = candidate && candidate.content && Array.isArray(candidate.content.parts) ? candidate.content.parts : [];
    for (const part of parts) {
      const inline = part && (part.inlineData || part.inline_data);
      if (!inline || typeof inline.data !== 'string' || inline.data.length < 100) continue;
      const mime = String(inline.mimeType || inline.mime_type || 'image/png').toLowerCase();
      const mimeType = ['image/png','image/jpeg','image/webp'].includes(mime) ? mime : 'image/png';
      return { mimeType, data: inline.data };
    }
  }
  return null;
}
function geminiApiErrorDetail(payload, fallbackText = '') {
  const message = cleanLabelText(payload && payload.error && payload.error.message || fallbackText || '', 280);
  return message.replace(/AIza[0-9A-Za-z_-]{20,}/g, '[API key đã ẩn]');
}
function geminiTryOnFriendlyError(errors) {
  const rows = Array.isArray(errors) ? errors : [];
  const statusRow = (code) => rows.find((item) => Number(item && item.status) === code);
  let row = statusRow(403);
  if (row) return { code:'GEMINI_403', message:'Gemini Image API trả HTTP 403. API key/project hiện chưa có quyền dùng model ảnh hoặc billing chưa gắn đúng project chứa API key.', detail:row.detail || '' };
  row = statusRow(429);
  if (row) return { code:'GEMINI_429', message:'Gemini Image API trả HTTP 429. Project đang hết quota hoặc billing/quota của model ảnh chưa hoạt động cho API key này.', detail:row.detail || '' };
  row = statusRow(400);
  if (row) return { code:'GEMINI_400', message:'Gemini Image API trả HTTP 400. Google từ chối request ảnh; R5 đã thử cả Interactions và GenerateContent.', detail:row.detail || '' };
  row = statusRow(404);
  if (row) return { code:'GEMINI_404', message:`Model ảnh ${GEMINI_IMAGE_MODEL} chưa khả dụng cho project/API key đang dùng (HTTP 404).`, detail:row.detail || '' };
  row = rows.find((item) => Number(item && item.status) >= 500);
  if (row) return { code:'GEMINI_5XX', message:`Dịch vụ Gemini Image đang lỗi phía Google (HTTP ${row.status}).`, detail:row.detail || '' };
  row = rows.find((item) => item && item.kind === 'timeout');
  if (row) return { code:'GEMINI_TIMEOUT', message:`Gemini Image xử lý quá ${Math.round(AI_TRYON_TIMEOUT_MS/1000)} giây nên server đã dừng request.`, detail:'' };
  row = rows.find((item) => item && item.kind === 'no-image');
  if (row) return { code:'GEMINI_NO_IMAGE', message:'Gemini trả request thành công nhưng không có image output trong response.', detail:row.detail || '' };
  return { code:'GEMINI_FAILED', message:'Gemini Image API chưa tạo được ảnh. R5 đã thử cả 2 API chính thức nhưng chưa nhận được image output.', detail:cleanLabelText(rows[0] && rows[0].detail || '', 220) };
}
async function readGeminiJsonResponse(response) {
  const text = await response.text();
  if (!text) return { payload:{}, raw:'' };
  try { return { payload:JSON.parse(text), raw:text }; }
  catch (_) { return { payload:{}, raw:text }; }
}
async function geminiTryOnImage(customerPhoto, productImage, mode, product, aspectRatio) {
  if (!AI_TRYON_ENABLED || !GEMINI_API_KEY || typeof fetch !== 'function') return { success:false, error:{ code:'GEMINI_NOT_CONFIGURED', message:'Gemini Image API chưa được cấu hình trên server.', detail:'' } };
  const allowedRatios = new Set(['1:1','3:4','4:3','9:16','16:9','2:3','3:2']);
  const ratio = allowedRatios.has(aspectRatio) ? aspectRatio : '3:4';
  const models = geminiModelCandidates(GEMINI_IMAGE_MODEL, ['gemini-3.1-flash-image']);
  const errors=[];
  const prompt=tryOnPrompt(mode, product);

  for (const model of models) {
    // 1) API hiện hành: Interactions.
    {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), AI_TRYON_TIMEOUT_MS);
      try {
        const response = await kblAiFetch('https://generativelanguage.googleapis.com/v1beta/interactions', {
          method: 'POST',
          headers: { 'x-goog-api-key': GEMINI_API_KEY, 'Content-Type': 'application/json' },
          signal: controller.signal,
          body: JSON.stringify({
            model,
            input: [
              { type: 'image', mime_type: customerPhoto.mimeType, data: customerPhoto.data },
              { type: 'image', mime_type: productImage.mimeType, data: productImage.data },
              { type: 'text', text: prompt }
            ],
            response_format: { type: 'image', mime_type:'image/jpeg', aspect_ratio: ratio, image_size: AI_TRYON_IMAGE_SIZE }
          })
        }, "geminiTryOnImage");
        const {payload,raw}=await readGeminiJsonResponse(response);
        if (response.ok) {
          const image = geminiInteractionImage(payload);
          if (image) return { success:true, ...image, model, api:'interactions' };
          errors.push({api:'interactions',model,status:response.status,kind:'no-image',detail:geminiApiErrorDetail(payload,raw)});
        } else {
          errors.push({api:'interactions',model,status:response.status,kind:'http',detail:geminiApiErrorDetail(payload,raw)});
        }
      } catch (error) {
        errors.push({api:'interactions',model,status:0,kind:error && error.name === 'AbortError' ? 'timeout' : 'network',detail:cleanLabelText(error && error.message || 'network error',220)});
      } finally { clearTimeout(timeout); }
    }

    // 2) Fallback chính thức: GenerateContent v1beta. Hữu ích khi Interactions bị chặn theo project/rollout.
    {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), AI_TRYON_TIMEOUT_MS);
      try {
        const response = await kblAiFetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`, {
          method:'POST',
          headers:{'x-goog-api-key':GEMINI_API_KEY,'Content-Type':'application/json'},
          signal:controller.signal,
          body:JSON.stringify({
            contents:[{role:'user',parts:[
              {text:prompt},
              {inline_data:{mime_type:customerPhoto.mimeType,data:customerPhoto.data}},
              {inline_data:{mime_type:productImage.mimeType,data:productImage.data}}
            ]}],
            generationConfig:{
              responseModalities:['IMAGE'],
              imageConfig:{aspectRatio:ratio,imageSize:AI_TRYON_IMAGE_SIZE}
            }
          })
        }, "geminiTryOnImage");
        const {payload,raw}=await readGeminiJsonResponse(response);
        if(response.ok){
          const image=geminiGenerateContentImage(payload);
          if(image) return {success:true,...image,model,api:'generateContent-v1beta'};
          errors.push({api:'generateContent-v1beta',model,status:response.status,kind:'no-image',detail:geminiApiErrorDetail(payload,raw)});
        } else {
          errors.push({api:'generateContent-v1beta',model,status:response.status,kind:'http',detail:geminiApiErrorDetail(payload,raw)});
        }
      } catch(error){
        errors.push({api:'generateContent-v1beta',model,status:0,kind:error && error.name === 'AbortError' ? 'timeout' : 'network',detail:cleanLabelText(error && error.message || 'network error',220)});
      } finally { clearTimeout(timeout); }
    }
  }

  const error=geminiTryOnFriendlyError(errors);
  console.warn('KBL Premium Try-on Gemini failed:', errors.map((item)=>`${item.api}/${item.model}/${item.status || item.kind}: ${item.detail || ''}`).join(' | '));
  return {success:false,error,errors:errors.map((item)=>({api:item.api,model:item.model,status:item.status,kind:item.kind}))};
}

