  const error=geminiTryOnFriendlyError(errors);
  console.warn('KBL Pendant + Chain Try-on Gemini failed:', errors.map((item)=>`${item.api}/${item.model}/${item.status||item.kind}: ${item.detail||''}`).join(' | '));
