function adviserRecommendations(message, intent) {
  const stock = verifiedAdviserStock();
  const category = ADVISER_CATEGORIES.has(intent.category) ? intent.category : '';
  let filtered = category && category !== 'other' ? stock.filter((p) => adviserCategoryForProduct(p) === category) : stock;
  const goldCode = GOLD_RULES.some((r) => r.code === String(intent.goldCode || '')) ? String(intent.goldCode) : '';
  if (goldCode) filtered = filtered.filter((p) => normalizeGoldCode(p.goldCode) === goldCode);
  const targetWeightChi = Math.max(0, number(intent.weightChi));
  if (targetWeightChi) {
    const tolerance = Math.max(AI_WEIGHT_TOLERANCE_CHI, targetWeightChi * 0.02);
    filtered = filtered.filter((p) => Math.abs(number(p.weightChi) - targetWeightChi) <= tolerance);
  }
  const requestedSize = cleanLabelText(intent.sizeLabel, 40);
  let missingSizeData = false;
  if (requestedSize) {
    const withSizeData = filtered.filter((p) => Boolean(adviserProductSizeLabel(p)));
    if (!withSizeData.length) { missingSizeData = true; filtered = []; }
    else filtered = withSizeData.filter((p) => adviserProductMatchesSize(p, requestedSize));
  }
  const parsedBudget = adviserBudgetConstraintFromText(message);
  const budget = Math.max(0, number(intent.budget || parsedBudget.budget));
  const budgetMode = ['min','max','around','range'].includes(String(intent.budgetMode||''))
    ? String(intent.budgetMode)
    : (parsedBudget.budgetMode || (budget ? 'max' : ''));
  const budgetMin = Math.max(0, number(intent.budgetMin || parsedBudget.budgetMin || (budgetMode==='min'?budget:0)));
  const budgetMax = Math.max(0, number(intent.budgetMax || parsedBudget.budgetMax || ((budgetMode==='max'||budgetMode==='around')?budget:0)));
  const criteria = { category, goldCode, weightChi: targetWeightChi, sizeLabel: requestedSize, budget, budgetMode, budgetMin, budgetMax };
  if (!filtered.length) return { items: [], hasAffordable: false, hasBudgetMatch:false, stockCount: stock.length, matchedCount: 0, missingSizeData, criteria };

  let budgetMatched = filtered;
  if (budget) {
    if (budgetMode === 'min') budgetMatched = filtered.filter((p) => number(p.referencePrice) >= budgetMin);
    else if (budgetMode === 'range') budgetMatched = filtered.filter((p) => number(p.referencePrice) >= budgetMin && number(p.referencePrice) <= budgetMax);
    else if (budgetMode === 'around') budgetMatched = filtered.filter((p) => number(p.referencePrice) >= budgetMin && number(p.referencePrice) <= budgetMax);
    else budgetMatched = filtered.filter((p) => number(p.referencePrice) <= (budgetMax || budget));
  }
  // Min/max/range là tiêu chí cứng: không được lén gửi món sai khoảng giá.
  // Around là tiêu chí mềm: nếu không có món trong dải ±20%, vẫn có thể gửi món gần nhất và nói rõ.
  const hardBudget = budget && ['min','max','range'].includes(budgetMode);
  const pool = budget ? (budgetMatched.length ? budgetMatched : (hardBudget ? [] : filtered)) : filtered;
  if (!pool.length) return { items: [], hasAffordable:false, hasBudgetMatch:false, stockCount:stock.length, matchedCount:0, missingSizeData, criteria };

  const keywords = adviserKeywords(`${message} ${intent.style || ''}`);
  const budgetReference = budgetMode==='range' ? ((budgetMin+budgetMax)/2) : budget;
  const items = pool.map((product) => {
    const price = number(product.referencePrice);
    const haystack = plainVietnamese(`${product.name} ${product.category} ${product.description} ${product.detail} ${product.specialMark} ${product.sizeLabel || ''}`);
    let score = category && adviserCategoryForProduct(product) === category ? 120 : 20;
    for (const keyword of keywords) if (haystack.includes(keyword)) score += 12;
    let budgetOk = true;
    if (budget) {
      const distance = Math.abs(budgetReference-price)/Math.max(budgetReference,1);
      score += Math.max(0,70-distance*70);
      if (budgetMode==='min') { budgetOk=price>=budgetMin; score += budgetOk ? 80 : -120; }
      else if (budgetMode==='range') { budgetOk=price>=budgetMin&&price<=budgetMax; score += budgetOk ? 90 : -120; }
      else if (budgetMode==='around') { budgetOk=price>=budgetMin&&price<=budgetMax; score += budgetOk ? 75 : -20; }
      else { budgetOk=price<=(budgetMax||budget); score += budgetOk ? 70 : -120; }
    }
    if (targetWeightChi) score += Math.max(0, 80 - Math.abs(number(product.weightChi)-targetWeightChi)*500);
    if (goldCode && normalizeGoldCode(product.goldCode) === goldCode) score += 80;
    const resolvedSizeLabel = adviserProductSizeLabel(product);
    if (requestedSize && resolvedSizeLabel) score += 80;
    const reasons=[];
    if (category && category !== 'other') reasons.push(`Đúng nhóm ${ADVISER_CATEGORY_LABELS[category]}`);
    if (goldCode) reasons.push(`Đúng vàng ${goldCode}`);
    if (targetWeightChi) reasons.push(`Trọng lượng ${number(product.weightChi).toLocaleString('vi-VN')} chỉ`);
    if (requestedSize) reasons.push(`Ni/size ${resolvedSizeLabel || requestedSize}`);
    if (budget) {
      if (budgetMode==='min') reasons.push(`Từ ${budgetMin.toLocaleString('vi-VN')}đ trở lên`);
      else if (budgetMode==='range') reasons.push(`Trong khoảng ${budgetMin.toLocaleString('vi-VN')}–${budgetMax.toLocaleString('vi-VN')}đ`);
      else if (budgetMode==='around') reasons.push(budgetOk?`Gần mức ${budget.toLocaleString('vi-VN')}đ`:`Mẫu gần mức ${budget.toLocaleString('vi-VN')}đ nhất`);
      else reasons.push(`Không quá ${(budgetMax||budget).toLocaleString('vi-VN')}đ`);
    }
    if (intent.purpose) reasons.push(`Có thể cân nhắc cho ${intent.purpose}`); else if (intent.recipient) reasons.push(`Có thể cân nhắc tặng ${intent.recipient}`);
    return {score,item:{id:String(product.id),sku:cleanInventoryCode(product.sku),name:cleanLabelText(product.name,160),category:cleanLabelText(product.category,80),goldCode:normalizeGoldCode(product.goldCode),weightChi:Math.max(0,number(product.weightChi)),sizeLabel:resolvedSizeLabel,workmanship:Math.max(0,number(product.workmanship)),image:safeImageSource(product.image),tryOnImage:safeImageSource(product.tryOnImage),referencePrice:price,withinBudget:budget?budgetOk:null,reason:reasons.join(' · ')||'Mẫu đang còn tại tiệm và đã được chủ tiệm duyệt.'}};
  }).sort((a,b)=>b.score-a.score || number(a.item.referencePrice)-number(b.item.referencePrice));
  return {items:items.slice(0,AI_RECOMMENDATION_LIMIT).map(e=>e.item),hasAffordable:Boolean(budgetMatched.length),hasBudgetMatch:Boolean(budgetMatched.length),stockCount:stock.length,matchedCount:items.length,missingSizeData,criteria};
}

function adviserSummary(intent, result) {
  const type = intent.category && intent.category !== 'other' ? ADVISER_CATEGORY_LABELS[intent.category] : 'trang sức';
  const criteria=[];
  if(intent.goldCode) criteria.push(`vàng ${intent.goldCode}`);
  if(intent.weightChi) criteria.push(`${number(intent.weightChi).toLocaleString('vi-VN')} chỉ`);
  if(intent.sizeLabel) criteria.push(`ni/size ${cleanLabelText(intent.sizeLabel,40)}`);
  const budget=Math.max(0,number(intent.budget));
  const budgetMode=['min','max','around','range'].includes(String(intent.budgetMode||''))?String(intent.budgetMode):(budget?'max':'');
  const budgetMin=Math.max(0,number(intent.budgetMin||(budgetMode==='min'?budget:0)));
  const budgetMax=Math.max(0,number(intent.budgetMax||((budgetMode==='max'||budgetMode==='around')?budget:0)));
  let budgetText='';
  if(budget){
    if(budgetMode==='min') budgetText=`từ ${budgetMin.toLocaleString('vi-VN')}đ trở lên`;
    else if(budgetMode==='range') budgetText=`từ ${budgetMin.toLocaleString('vi-VN')}đ đến ${budgetMax.toLocaleString('vi-VN')}đ`;
    else if(budgetMode==='around') budgetText=`quanh mức ${budget.toLocaleString('vi-VN')}đ`;
    else budgetText=`không quá ${(budgetMax||budget).toLocaleString('vi-VN')}đ`;
    criteria.push(budgetText);
  }
  const criteriaText=criteria.length?` (${criteria.join(' · ')})`:'';
  if(!result.items.length){
    if(result.missingSizeData) return `Kho đang có ${type} phù hợp các tiêu chí khác nhưng chưa có dữ liệu ni/size để lọc an toàn. Chủ tiệm cần bổ sung ni/size cho đúng Mã SP trước khi AI tư vấn.`;
    if(budgetText) return `Em đã lọc kho thật nhưng hiện chưa có mẫu ${type} ${budgetText} đáp ứng các tiêu chí anh/chị vừa hỏi. Em không gửi món sai khoảng giá.`;
    return result.stockCount ? `Hiện chưa có mẫu ${type}${criteriaText} đủ điều kiện và còn hàng. Hệ thống không tự thay bằng món sai tiêu chí.` : 'Hiện chưa có sản phẩm nào đủ điều kiện tư vấn tự động (còn hàng, đã duyệt, có ảnh và Mã SP).';
  }
  if(budgetMode==='around' && budget && !result.hasBudgetMatch) return `Kho chưa có mẫu ${type} đúng sát ${budget.toLocaleString('vi-VN')}đ; em gửi ${Math.min(result.items.length,6)} mẫu gần mức đó nhất để anh/chị so nhanh.`;
  const countText=result.matchedCount>result.items.length?`${result.items.length}/${result.matchedCount}`:String(result.items.length);
  if(budgetText) return `Dạ, em hiểu là anh/chị muốn xem ${type} ${budgetText}. Em đã lọc kho thật và tìm thấy ${countText} mẫu đang còn; em gửi đúng các mẫu theo khoảng giá bên dưới.`;
  return `Em tìm thấy ${countText} mẫu ${type}${criteriaText} đang còn tại tiệm. Quý khách vui lòng chọn sản phẩm ưng ý và gửi lại cho em.`;
}

function adviserLooksKnowledgeSeeking(value) {
  const raw = plainVietnamese(value);
  return /\b(la gi|nghia la gi|tai sao|vi sao|khac nhau|phan biet|nhan biet|co tot khong|co ben khong|co den khong|bi den|bi xi|xi mau|bao quan|lam sach|cach deo|cach chon|ham luong|tuoi vang|karat|k la gi|vang ta|vang tay|vang y|vang trang|vang hong|co nen mua|nen mua loai nao|de dau tu|de deo|di ung|kich ung|mem hay cung|co mat gia|mat gia|gia tri|kien thuc|giai thich)\b/.test(raw);
}
function adviserConversationMode(message, intent) {
  const raw = plainVietnamese(message);
  if (/\b(doi ngang|doi bu|thu doi|vang cu|do cu|lac cu|nhan cu|day cu|bong tai cu|doi qua|doi sang)\b/.test(raw)) return 'knowledge';
  if (adviserLooksKnowledgeSeeking(message)) return 'knowledge';
  if (/\b(gio mo cua|mo cua|dia chi|duong di|o dau|chi duong|dat lich|bao nhieu km|may km|khoang cach)\b/.test(raw)) return 'store';

  // Chỉ vào chế độ tìm sản phẩm khi CÂU HIỆN TẠI thực sự mang tín hiệu mua/tìm món.
  // Không dùng một con số tiền/size/ý định còn sót từ câu trước để ép mọi chủ đề sang kho hàng.
  const explicitShopping = /\b(tim mau|tim giup|chon mau|co mau nao|con mau nao|muon mua|can mua|mua tang|mua duoc gi|ngan sach|tam gia|duoi .*trieu|tren .*trieu|hon .*trieu|tu .*trieu|it nhat .*trieu|toi thieu .*trieu|khoang .*trieu|goi y mau)\b/.test(raw);
  const productNoun = /\b(trang suc|san pham|mau|nhan|lac|vong tay|day chuyen|day co|bong tai|hoa tai|mat day|kieng)\b/.test(raw);
  const productAction = /\b(mua|tim|chon|goi y|tham khao|con hang|co hang|muon|can)\b/.test(raw);
  const hasConcreteProductNeed = Boolean(intent && (
    intent.budget || intent.goldCode || intent.weightChi || intent.sizeLabel || intent.recipient || intent.style || intent.purpose ||
    (intent.category && intent.category !== 'other')
  ));
  const productSignals = explicitShopping || (productNoun && (productAction || hasConcreteProductNeed));
  if (productSignals) return 'product';

  if (/\b(bao hanh|thu doi|doi tra|tien cong|gia cong|610|980|9999|18k|14k|10k|tuoi vang|ham luong|gia vang|vang|trang suc|kim cuong|da quy)\b/.test(raw)) return 'knowledge';
  return 'general';
}
function publicGoldPriceFacts() {
  return GOLD_RULES.map((rule) => ({
    code: rule.code,
    name: rule.name,
    purity: rule.purity,
    buy: number(prices[`price_buy_${rule.code}`]),
    sell: number(prices[`price_sell_${rule.code}`])
  }));
}
function adviserIsExchangeQuestion(value) {
  const raw=plainVietnamese(value);
  return /\b(doi ngang|doi bu|thu doi|vang cu|do cu|lac cu|nhan cu|day cu|bong tai cu|doi qua|doi sang)\b/.test(raw);
}
function adviserExchangeOrigin(message, context = []) {
  const classify=(value)=>{
    const raw=plainVietnamese(value);
    const external=/\b(tiem khac|cho khac|noi khac|mua ngoai|vang ngoai|khong mua o kim bao lam|khong phai kim bao lam|khong mua ben minh|mua ben khac|mua tiem khac|o tiem khac|o ngoai|mua o ngoai)\b/.test(raw);
    const kbl=/\b(kim bao lam|kbl|mua o tiem minh|mua tai tiem minh|mua ben minh|mua cua ben em|mua o day|mua tai day|vang cua tiem minh|vang ben minh|o ben minh|tai ben minh|o minh|ben minh)\b/.test(raw);
    if(external&&!kbl) return 'external';
    if(kbl&&!external) return 'kbl';
    return 'unknown';
  };
  // Ưu tiên câu trả lời mới nhất của khách. Context website chỉ chứa các tin khách đã gửi.
  const latest=classify(message);
  if(latest!=='unknown') return latest;
  const history=Array.isArray(context)?context:[];
  for(let i=history.length-1;i>=Math.max(0,history.length-8);i--){
    const found=classify(history[i]);
    if(found!=='unknown') return found;
  }
  return 'unknown';
}
function adviserExchangeOldGoldCode(message, context = []) {
  const all=plainVietnamese([...(Array.isArray(context)?context:[]).slice(-6),message].join(' | '));
  if(/\b(9999|24k|999\.9)\b/.test(all)) return '9999';
  if(/\b(980)\b/.test(all)) return '980';
  if(/\b(750|18k)\b/.test(all)) return '750';
  if(/\b(610)\b/.test(all)) return '610';
  if(/\b(585|14k)\b/.test(all)) return '585';
  if(/\b(416|10k)\b/.test(all)) return '416';
  return '';
}
function adviserExchangeOldWeightChi(value) {
  const text=String(value||'').replace(/,/g,'.');
  const colloquial=text.match(/(\d+)\s*(?:chỉ|chi)\s+(\d{1,3})(?=\s|$)/i);
  if(colloquial) return Math.max(0,number(colloquial[1])+number(colloquial[2])/1000);
  const matches=[...text.matchAll(/(\d+(?:\.\d+)?)\s*(?:chỉ|chi)\b/gi)];
  if(matches.length) return Math.max(0,number(matches[0][1]));
  const ly=[...text.matchAll(/(\d+(?:\.\d+)?)\s*ly\b/gi)];
  if(ly.length) return Math.max(0,number(ly[0][1])/100);
  return 0;
}
function adviserPublicExchangeEstimate(message, context = [], selectedProduct = null) {
  const exchangeContext=adviserIsExchangeQuestion(message)||adviserIsExchangeQuestion((context||[]).join(' '));
  if(!exchangeContext) return null;
  const product=selectedProduct && normalizeGoldCode(selectedProduct.goldCode)==='610' ? selectedProduct : null;
  const oldWeightChi=adviserExchangeOldWeightChi(message) || adviserExchangeOldWeightChi((context||[]).slice(-6).join(' '));
  if(!product || !oldWeightChi) return {ready:false, oldWeightChi, product:product?{id:product.id,sku:cleanInventoryCode(product.sku),name:cleanLabelText(product.name,160),weightChi:number(product.weightChi),workmanship:number(product.workmanship)}:null};
  const newWeightChi=Math.max(0,number(product.weightChi));
  const workmanship=Math.max(0,number(product.workmanship));
  const buy=Math.max(0,number(prices.price_buy_610));
  const sell=Math.max(0,number(prices.price_sell_610));
  const delta=Math.round((newWeightChi-oldWeightChi)*1000)/1000;
  let kind='equal', rate=0, goldAmount=0;
  if(delta>0){kind='shortage';rate=sell;goldAmount=delta*sell;}
  else if(delta<0){kind='surplus';rate=buy;goldAmount=delta*buy;}
  const total=Math.round(goldAmount+workmanship);
  return {ready:true,oldWeightChi,newWeightChi,workmanship,buy,sell,deltaChi:delta,kind,rate,goldAmount:Math.round(goldAmount),total,product:{id:product.id,sku:cleanInventoryCode(product.sku),name:cleanLabelText(product.name,160)}};
}
function adviserPublicOutsideExchangeEstimate(message, context, selectedProduct) {
  if(!adviserIsExchangeQuestion(message)&&!adviserIsExchangeQuestion((context||[]).join(' '))) return null;
  const oldType=adviserExchangeOldGoldCode(message,context);
  const oldWeightChi=adviserExchangeOldWeightChi(message) || adviserExchangeOldWeightChi((context||[]).slice(-6).join(' '));
  const product=selectedProduct||null;
  if(!product||!oldWeightChi||!oldType) return {ready:false,oldType,oldWeightChi,product:product?{id:product.id,sku:cleanInventoryCode(product.sku),name:cleanLabelText(product.name,160),goldCode:normalizeGoldCode(product.goldCode),weightChi:number(product.weightChi),workmanship:number(product.workmanship)}:null};
  const newType=normalizeGoldCode(product.goldCode);
  const newWeightChi=Math.max(0,number(product.weightChi));
  const wage=Math.max(0,number(product.workmanship));
  const oldBuy=Math.max(0,number(prices[`price_buy_${oldType}`]));
  const newSell=Math.max(0,number(prices[`price_sell_${newType}`]));
  const overlap=Math.min(oldWeightChi,newWeightChi);
  const oldExtra=Math.max(0,oldWeightChi-newWeightChi);
  const newExtra=Math.max(0,newWeightChi-oldWeightChi);
  let total=0, specialFee=0, benefit=0, exchangeFeeRate=0, benefitRate=0;
  let chargeWage=false;
  if(oldType===newType&&(oldType==='610'||oldType==='980')) { chargeWage=overlap>0||newWeightChi>0; }
  else if(oldType==='9999'&&newType==='9999') { chargeWage=false; }
  else if(oldType==='9999'&&newType==='980') { chargeWage=overlap>0; }
  else if(oldType==='610'&&newType==='9999') {
    total += overlap*(newSell-oldBuy);
    chargeWage=false;
  }
  else {
    total += overlap*(newSell-oldBuy);
    chargeWage=overlap>0;
  }
  total += newExtra*newSell;
  total -= oldExtra*oldBuy;
  if(chargeWage) total += wage;
  if(oldType===newType&&(oldType==='980'||oldType==='610')) {
    exchangeFeeRate=oldType==='980'?Math.max(0,number(prices.exchange_fee_980_980,120000)):Math.max(0,number(prices.exchange_fee_610_610,number(prices.default_exchange_fee,400000)));
    specialFee=oldWeightChi*exchangeFeeRate;
    total+=specialFee;
  }
  if(oldType==='9999'&&newType==='610') {
    benefitRate=Math.max(0,number(prices.exchange_refund_9999_610,30000));
    benefit=oldWeightChi*benefitRate;
    total-=benefit;
  }
  return {ready:true,oldType,newType,oldWeightChi,newWeightChi,oldBuy,newSell,wage,specialFee:Math.round(specialFee),exchangeFeeRate:Math.round(exchangeFeeRate),benefit:Math.round(benefit),benefitRate:Math.round(benefitRate),total:Math.round(total),product:{id:product.id,sku:cleanInventoryCode(product.sku),name:cleanLabelText(product.name,160)}};
}
function adviserOutsideExchangePolicyText() {
  return 'Nếu vàng mua ở tiệm khác hoặc không xác định là vàng Kim Bảo Lâm, tiệm xử lý theo chế độ ĐỔI VÀNG BÙ của POS, không áp dụng chính sách đổi ngang KBL. Mức đổi/bù không cố định lâu dài; có thể thay đổi theo giá vàng, cặp vàng, trọng lượng, Mã SP và cấu hình POS hiện hành. Giá thu vàng cũ, giá vàng món mới và công món mới lấy từ dữ liệu đang chạy tại thời điểm tư vấn. AI không tự đặt giá đổi; số cuối cùng do POS tính lại sau khi cân thực tế tại tiệm.';
}

function adviserExchangePolicyText() {
  return 'Đổi ngang vàng 610 tại Kim Bảo Lâm dùng đúng trọng lượng thực tế, công niêm yết cố định của Mã SP mới và bảng giá mua/bán 610 đang đồng bộ trực tiếp từ POS tại thời điểm tư vấn. Nếu vàng cũ và món mới bằng trọng lượng thì phần vàng chênh bằng 0 và khách chỉ thanh toán công niêm yết của món mới. Nếu vàng cũ nhẹ hơn, phần thiếu nhân giá BÁN 610 hiện tại rồi cộng công món mới. Nếu vàng cũ nặng hơn, phần dư nhân giá MUA 610 hiện tại để cấn/trả lại, sau đó cấn với công món mới. Trọng lượng cũ phải cân thực tế tại tiệm và trừ hột/đá hoặc tạp chất nếu có; AI không tự định giá món cũ qua ảnh và không thay đổi công theo từng khách.';
}

function adviserPolicyFacts() {
  return {
    workmanship: 'Tiền công là phần chi phí chế tác/hoàn thiện của từng món, được cộng vào giá vàng theo dữ liệu sản phẩm và phải kiểm tra lại trước giao dịch.',
    warranty: 'Bảo hành kỹ thuật tùy tình trạng thực tế; hàn nối, chỉnh size, gắn lại đá hoặc sửa chữa được kiểm tra và báo thời gian/chi phí trước khi làm.',
    exchange: 'Khi khách muốn đổi vàng, trước tiên phải hỏi vàng cũ mua tại Kim Bảo Lâm hay mua ở nơi khác. Nếu là vàng KBL thì dùng Đổi Ngang KBL: ' + adviserExchangePolicyText() + ' Nếu là vàng ngoài thì dùng Đổi Vàng Bù: ' + adviserOutsideExchangePolicyText(),
    returns: 'Trong 2 ngày từ khi giao dịch hoàn tất, sản phẩm không hư hỏng và còn nguyên tình trạng có thể được xem xét đổi ngang/hoàn tiền theo chính sách của tiệm và kiểm tra thực tế.'
  };
}
function adviserExchangeSourceQuestion() {
  return 'Dạ, trước khi tính đổi em cần xác định đúng chính sách: món vàng cũ anh/chị mua tại Kim Bảo Lâm hay mua ở tiệm/chỗ khác ạ? Nếu mua tại Kim Bảo Lâm em sẽ tư vấn Đổi Ngang KBL; nếu mua nơi khác em sẽ tư vấn Đổi Vàng Bù theo bảng giá và quy tắc đang cài trong POS.';
}

function adviserCurrencyFromText(value) {
  const raw = plainVietnamese(value).replace(/\s+/g, ' ').trim();
  const pairs = [
    ['USD', /\b(usd|do la my|dollar|do la)\b/],
    ['EUR', /\b(eur|euro)\b/],
    ['JPY', /\b(jpy|yen|yen nhat)\b/],
    ['CNY', /\b(cny|rmb|nhan dan te)\b/],
    ['KRW', /\b(krw|won|won han)\b/],
    ['THB', /\b(thb|baht)\b/],
    ['SGD', /\b(sgd|do la singapore)\b/],
    ['AUD', /\b(aud|do la uc)\b/],
    ['CAD', /\b(cad|do la canada)\b/],
    ['GBP', /\b(gbp|bang anh|pound)\b/]
  ];
  for (const [code, re] of pairs) if (re.test(raw)) return code;
  return '';
}
function adviserFxAmountFromText(value) {
  const raw = plainVietnamese(value).replace(/,/g,'.').replace(/\s+/g,' ').trim();
  const m = raw.match(/(?:^|\s)(\d+(?:\.\d+)?)(?=\s*(?:usd|eur|euro|jpy|yen|cny|rmb|krw|won|thb|baht|sgd|aud|cad|gbp|bang anh|do la|dollar)\b)/);
  if (m) return Math.max(0, Math.min(1e9, Number(m[1]) || 0));
  return 0;
}
function adviserLooksLikeFxReferenceQuestion(value) {
  const raw = plainVietnamese(value).replace(/\s+/g,' ').trim();
  if (!adviserCurrencyFromText(raw)) return false;
  if (adviserHasTransactionIntent(raw)) return false;
  return /\b(bao nhieu|bao nhiu|nhieu tien|nhiu tien|may tien|quy doi|doi ra|bang bao nhieu|ty gia|tham khao|sang vnd|ra vnd)\b/.test(raw)
    || /^\s*(usd|eur|jpy|cny|krw|thb|sgd|aud|cad|gbp)\s*$/.test(raw);
}
async function adviserDirectFxReply(message) {
  if (!adviserLooksLikeFxReferenceQuestion(message)) return null;
  const base = adviserCurrencyFromText(message);
  if (!base) return null;
  const amount = adviserFxAmountFromText(message) || 1;
  const ref = await kblFxReference({ base, quote: 'VND', amount });
  if (!ref || !ref.available || !ref.converted) {
    return `Em nhận ra anh/chị đang hỏi quy đổi ${base} sang VND, nhưng nguồn tỷ giá tham khảo đang chưa phản hồi. Kim Bảo Lâm không mua bán/thu đổi ngoại tệ.`;
  }
  const amountLabel = Number(amount).toLocaleString('vi-VN');
  const convertedLabel = Math.round(Number(ref.converted)).toLocaleString('vi-VN');
  const dateText = ref.date ? ` (nguồn cập nhật ${ref.date})` : '';
  return `${amountLabel} ${base} ≈ ${convertedLabel} VND${dateText}. Đây chỉ là tỷ giá tham khảo công khai; Kim Bảo Lâm không mua bán/thu đổi ngoại tệ.`;
}
function adviserLooksLikePublicKnowledgeQuestion(value) {
  const raw = plainVietnamese(value).replace(/\s+/g,' ').trim();
  if (!raw || raw.length < 3) return false;
  if (adviserIsPriceQuestion(raw) || adviserCurrencyFromText(raw)) return false;
  if (kblAiV5ExplicitResearchRequest(raw)) return kblAiV5CanLearnQuery(raw);
  if (kblAiV5UnknownGoldCodeFromText(raw)) return true;
  if (kblAiV5LooksLikeGeneralJewelryKnowledgeQuery(raw)) return true;

  // V5.2: kiến thức công khai không chỉ giới hạn trong ngành vàng.
  // Ví dụ "mệnh hỏa hợp màu gì", "phong thủy nhẫn cho mệnh hỏa", "X là gì?"...
  // Những câu này được phép tra nguồn công khai, nhưng không được dùng web để thay dữ liệu riêng/current của KBL.
  if (/\b(menh|phong thuy|ngu hanh|kim moc thuy hoa tho|hop mau|mau hop|hop menh|khac menh|tuong sinh|tuong khac|cung menh|ban menh|sinh nam|tuoi nao|hop tuoi|mau nao)\b/.test(raw)) return true;

  // Nếu câu hiện tại là một yêu cầu mua sản phẩm thật thì để router sản phẩm xử lý.
  // Nhưng chỉ nhắc tên sản phẩm trong câu hỏi kiến thức (ví dụ "nhẫn phong thủy là gì") vẫn được research.
  const category = adviserCategoryFromText(raw);
  const explicitShopping = /\b(muon mua|can mua|tim mau|tim giup|chon mau|co mau nao|con mau nao|mua tang|ngan sach|tam gia|goi y mau|con hang|co hang)\b/.test(raw);
  if (category && category !== 'other' && explicitShopping) return false;

  if (/\b(la gi|gi la|ai la|tai sao|vi sao|lich su|nguon goc|nghia la gi|hoat dong the nao|khac gi|giai thich|tom tat|co tot|co nen|nen chon|nen dung|bao quan|phan biet|ham luong|karat|tuoi vang|hien nay|moi nhat|quy dinh|co may loai|may loai|hop gi|hop mau gi|mau gi|the nao|nhu the nao|cach nao|dung de lam gi)\b/.test(raw)) return true;

  // V5.3: câu hỏi công khai bình thường cũng được nhận diện, không bắt buộc phải thuộc ngành vàng.
  // Gate phía sau vẫn chặn dữ liệu riêng/live của KBL, store/lead và giao dịch thật.
  const original = String(value || '').trim();
  if (/[?？]$/.test(original) && (/\b(ai|gi|sao|the nao|bao nhieu|co phai|co dung|co that|lam sao|khi nao|bao gio|nen|duoc khong|co khong|co may)\b/.test(raw) || /\bco\b.{0,60}\bkhong\b/.test(raw))) return true;
  return (/\b(co phai|co dung|co that|lam sao|bao nhieu|khi nao|bao gio|vi sao|tai sao|ai|gi|sao vay|sao the|nhu nao|the nao|co may)\b/.test(raw) || /\bco\b.{0,60}\bkhong\b/.test(raw)) && raw.length <= 260;
}

function kblAiV52ReplyLooksUncertain(value) {
  const raw = plainVietnamese(value).replace(/\s+/g,' ').trim();
  if (!raw) return true;
  return /\b(chua biet|khong biet|khong chac|chua chac|chua ro|khong ro|chua co thong tin|khong co thong tin|chua lay duoc nguon|chua co nguon|khong co nguon|nguon.*chua phan hoi|chua tra duoc|khong tra duoc|can kiem tra|can tra them|khong muon doan|khong doan bua|thu hoi lai|thu lai sau|gui lai sau)\b/.test(raw);
}

function kblAiV52ContinuationAllowsOldIntent(message) {
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (!raw) return false;
  if (adviserLooksLikeShortFollowup(message)) return true;
  if (raw.length > 90) return false;
  return /\b(cai nay|cai do|mau nay|mau do|loai nay|loai do|con cai|con mau|con loai|tuong tu|giong vay|giong mau|re hon|mac hon|nho hon|lon hon|them mau|trong tam do|tam do|gia do|ngan sach do|so tien do|vay thi|the thi|con neu)\b/.test(raw);
}

function kblAiV52ProductNeedsPublicKnowledge(message) {
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (!raw || !kblAiV5CanLearnQuery(raw)) return false;
  // Tiêu chí mua hàng nhưng cần kiến thức ngoài kho để hiểu đúng trước khi gợi ý.
  return /\b(menh|phong thuy|ngu hanh|hop mau|mau hop|hop menh|tuong sinh|tuong khac|hop tuoi|cung menh|ban menh)\b/.test(raw);
}

async function kblAiV52AutoResearch(message, currentReply = '', context = [], dialogue = [], options = {}) {
  if (!KBL_AI_V5_LEARNING_ENABLED || !KBL_AI_V3_GOOGLE_SEARCH_ENABLED) return null;
  if (!kblAiV5CanLearnQuery(message)) return null;
  if (!adviserLooksLikePublicKnowledgeQuestion(message)) return null;

  const forced = Boolean(options.force);
  const replyUncertain = kblAiV52ReplyLooksUncertain(currentReply);
  const noUsefulReply = !cleanLabelText(currentReply, 2000);
  if (!forced && !replyUncertain && !noUsefulReply) return null;

  const reference = await kblAiV3GoogleSearchReference({ query: message });
  if (!reference || !reference.available || !reference.summary) return null;

  const sourceText=(reference.sources||[]).slice(0,2).map((x)=>cleanLabelText(x.title,120)).filter(Boolean).join(', ');
  return {
    text: `${cleanLabelText(reference.summary,1800)}${sourceText?` Nguồn tham khảo: ${sourceText}.`:''}`,
    engine: reference.cached ? 'kbl-v5.2-web-cache-auto-research' : 'kbl-v5.2-google-search-auto-research',
    research: {
      used:true,
      auto:true,
      cached:Boolean(reference.cached),
      source:'Google Search grounding',
      sourceCount:Array.isArray(reference.sources)?reference.sources.length:0,
      checkedAt:cleanLabelText(reference.checkedAt,60)
    }
  };
}
// ============================================================================
// KBL AI V5.3 – BACKEND ONLY RESEARCH / SYNTHESIS
// Không đụng Home/Admin/POS. Mục tiêu: nếu AI không chắc thì tự tra nguồn, học tạm,
// rồi diễn đạt lại tự nhiên thay vì trả nguyên văn fallback/search summary.
// ============================================================================
function kblAiV53ResearchQuery(message, context = [], dialogue = []) {
  const current = cleanLabelText(message, 700);
  if (!current) return '';
  const rawCurrent = plainVietnamese(current).replace(/\s+/g,' ').trim();
  const needsContext = adviserLooksLikeShortFollowup(current)
    || rawCurrent.length <= 48
    || /\b(cai nay|cai do|loai nay|loai do|no|vay|the|con neu|con cai|con loai|hop menh|hop mau|mau nao|mau gi)\b/.test(rawCurrent);
  if (!needsContext) return current;

  const recent = [];
  for (const turn of normalizeAdviserDialogue(dialogue).filter((x)=>x.role==='user').slice(-5)) recent.push(turn.text);
  if (Array.isArray(context)) recent.push(...context.slice(-4));
  const blocked = /\b(kim bao lam|kbl|ma sp|ma san pham|ton kho|con hang|gia cua tiem|gia ben em|so tai khoan|stk|vietqr|cccd|can cuoc|phieu cam|hop dong cam|diem vip|tai khoan khach|so dien thoai khach|don hang)\b/;
  const previous = [];
  const seen = new Set([plainVietnamese(current).replace(/\s+/g,' ').trim()]);
  for (const item of recent.reverse()) {
    const clean = redactAdviserText(cleanLabelText(item, 420));
    const norm = plainVietnamese(clean).replace(/\s+/g,' ').trim();
    if (!clean || !norm || seen.has(norm) || blocked.test(norm) || /\b\d{9,16}\b/.test(norm)) continue;
    seen.add(norm);
    previous.unshift(clean);
    if (previous.length >= 2) break;
  }
  if (!previous.length) return current;
  return `${previous.join(' | ')} | Câu hiện tại: ${current}`.slice(0,1000);
}

function kblAiV53NeedsResearch(message, currentReply = '', mode = 'general', strongSchoolMatch = false) {
  if (!KBL_AI_V5_LEARNING_ENABLED || !KBL_AI_V3_GOOGLE_SEARCH_ENABLED) return false;
  if (kblAiV6StableNoWebQuestion(message) && !kblAiV5ExplicitResearchRequest(message)) return false;
  if (!['general','knowledge'].includes(String(mode || ''))) return false;
  if (!kblAiV5CanLearnQuery(message)) return false;
  if (kblAiV5ExplicitResearchRequest(message)) return true;
  if (kblAiV61NeedsFreshWeb(message)) return true;
  if (kblAiV52ReplyLooksUncertain(currentReply)) return true;
  // V6.1: kiến thức phổ thông ổn định để Gemini trả trực tiếp. Chỉ tra web khi cần độ mới, khách yêu cầu nguồn hoặc model thật sự chưa chắc.
  return false;
}

async function kblAiV53SynthesizeResearchAnswer(message, reference, context = [], dialogue = [], options = {}) {
  if (!reference || !reference.available || !reference.summary) return '';
  const mode = ['general','knowledge'].includes(String(options.mode || '')) ? String(options.mode) : 'general';
  const intent = options.intent && typeof options.intent === 'object' ? options.intent : localAdviserIntent(message);
  const result = options.result && typeof options.result === 'object'
    ? options.result
    : { items: [], hasAffordable:false, stockCount:verifiedAdviserStock().length, matchedCount:0, missingSizeData:false };
  const selectedProduct = options.selectedProduct || null;
  const baseMatches = Array.isArray(options.knowledgeMatches) ? options.knowledgeMatches : [];
  const sourceTitles = (Array.isArray(reference.sources)?reference.sources:[])
    .slice(0,3).map((x)=>cleanLabelText(x&&x.title,140)).filter(Boolean);
  const researchMatch = {
    id:'web-live-'+shortHash(String(options.query || message)),
    source:'web-cache',
    group:'Nguồn công khai vừa đối chiếu',
    question:cleanLabelText(message,300),
    guidance:cleanLabelText(reference.summary,1800),
    liveData:false,
    score:99
  };
  const matches = [researchMatch, ...baseMatches].slice(0,5);
  try {
    const synth = await geminiJewelryConsultantReply(message, context, mode, intent, result, selectedProduct, dialogue, matches);
    const text = synth && synth.text ? cleanLabelText(synth.text,1900) : '';
    if (text && !kblAiV52ReplyLooksUncertain(text)) {
      const alreadyMentionsSource = /nguon|tham khao|doi chieu/i.test(plainVietnamese(text));
      return sourceTitles.length && !alreadyMentionsSource
        ? `${text} Nguồn tham khảo: ${sourceTitles.slice(0,2).join(', ')}.`
        : text;
    }
  } catch (_) {}
  const summary = cleanLabelText(reference.summary,1800);
  return sourceTitles.length ? `${summary} Nguồn tham khảo: ${sourceTitles.slice(0,2).join(', ')}.` : summary;
}

async function kblAiV53AutoResearch(message, currentReply = '', context = [], dialogue = [], options = {}) {
  const mode = String(options.mode || 'general');
  const strongSchoolMatch = Boolean(options.strongSchoolMatch);
  const forced = Boolean(options.force);
  if (!forced && !kblAiV53NeedsResearch(message, currentReply, mode, strongSchoolMatch)) return null;
  if (!KBL_AI_V5_LEARNING_ENABLED || !KBL_AI_V3_GOOGLE_SEARCH_ENABLED || !kblAiV5CanLearnQuery(message)) return null;
  if (!['general','knowledge'].includes(mode)) return null;

  const query = kblAiV53ResearchQuery(message, context, dialogue) || message;
  const reference = await kblAiV3GoogleSearchReference({ query });
  if (!reference || !reference.available || !reference.summary) return null;
  const text = await kblAiV53SynthesizeResearchAnswer(message, reference, context, dialogue, { ...options, query, mode });
  if (!text) return null;
  return {
    text,
    engine: reference.cached ? 'kbl-v5.3-web-cache-synthesized' : 'kbl-v5.3-google-search-synthesized',
    research: {
      used:true,
      auto:true,
      cached:Boolean(reference.cached),
      source:'Google Search grounding',
      sourceCount:Array.isArray(reference.sources)?reference.sources.length:0,
      checkedAt:cleanLabelText(reference.checkedAt,60),
      contextualized:query !== cleanLabelText(message,700)
    }
  };
}

function kblAiV53AgentResearchMeta(toolResults = []) {
  const row = [...(Array.isArray(toolResults)?toolResults:[])].reverse().find((x)=>x&&x.name==='get_google_search_reference');
  const ref = row && row.output && row.output.reference;
  if (!ref || !ref.available) return null;
  return {
    used:true,
    auto:false,
    cached:Boolean(ref.cached),
    source:'Google Search grounding',
    sourceCount:Array.isArray(ref.sources)?ref.sources.length:0,
    checkedAt:cleanLabelText(ref.checkedAt,60)
  };
}

function adviserPaymentInfoQuestion(value) {
  const raw=plainVietnamese(value);
  return /\b(so tai khoan|stk|tai khoan ngan hang|bank nao|ngan hang nao|chuyen khoan vao dau|thanh toan vao dau|thanh toan o dau|co chuyen khoan|co vietqr|vietqr|ma qr thanh toan|cach thanh toan|thanh toan nhu the nao)\b/.test(raw);
}
function adviserPaymentConfirmation(value) {
  const raw=plainVietnamese(value);
  return /\b(toi da chuyen|em da chuyen|minh da chuyen|da chuyen tien|chuyen tien roi|xac nhan tien|kiem tra tien|nhan duoc tien|toi coc|em coc|minh coc|chuyen coc|dat coc|coc tien)\b/.test(raw);
}
function adviserDirectPaymentInfoReply(message) {
  if (!adviserPaymentInfoQuestion(message)) return '';
  let overview={};
  try { if(kblCommerceV5&&typeof kblCommerceV5.overview==='function') overview=kblCommerceV5.overview()||{}; } catch (_) {}
  const candidates=[overview&&overview.settings,overview&&overview.payment,overview].filter((x)=>x&&typeof x==='object');
  let payment={};
  for(const item of candidates){if(item.accountNo||item.bankId||item.accountName){payment=item;break;}}
  const bank=cleanLabelText(payment.bankId||payment.bank||'',50), accountNo=cleanLabelText(payment.accountNo||payment.accountNumber||'',80), accountName=cleanLabelText(payment.accountName||payment.ownerName||'',120);
  if(accountNo){return `Tiệm hỗ trợ chuyển khoản/VietQR. Tài khoản đang cấu hình: ${bank?bank+' · ':''}${accountNo}${accountName?` · ${accountName}`:''}. Khi thanh toán thật, anh/chị vui lòng đối chiếu đúng thông tin hiển thị ở bước checkout/VietQR trước khi chuyển.`;}
  return 'Tiệm hỗ trợ tiền mặt, chuyển khoản và VietQR. Em chưa đọc được số tài khoản đã cấu hình từ hệ thống ở lượt này nên không tự bịa số; khi checkout/VietQR hiển thị thông tin, anh/chị đối chiếu đúng tên tài khoản trước khi chuyển.';
}
async function adviserPublicKnowledgeFallback(message) {
  const school = kblAiV5StrongDirectKnowledge(message);
  if (school) return { text:school, engine:'kbl-v5.1-school-fallback', research:{used:false, source:'KBL AI School'} };
  if (!adviserLooksLikePublicKnowledgeQuestion(message)) return null;
  const google = await kblAiV3GoogleSearchReference({ query: message });
  if (google && google.available && google.summary) {
    const sourceText=(google.sources||[]).slice(0,2).map((x)=>cleanLabelText(x.title,120)).filter(Boolean).join(', ');
    return {
      text:`${google.summary}${sourceText?` Nguồn tham khảo: ${sourceText}.`:''}`,
      engine:google.cached?'kbl-v5.1-web-cache-fallback':'kbl-v5.1-google-search-fallback',
      research:{used:true,cached:Boolean(google.cached),source:'Google Search grounding',sourceCount:Array.isArray(google.sources)?google.sources.length:0,checkedAt:cleanLabelText(google.checkedAt,60)}
    };
  }
  const ref = await kblWikipediaReference({ query: message });
  if (!ref || !ref.available || !ref.summary) return null;
  return { text:`${ref.summary} Nguồn tham khảo: ${ref.source}.`, engine:'kbl-v5.1-wikipedia-fallback', research:{used:true,cached:false,source:ref.source,sourceCount:1} };
}

function localJewelryConsultantReply(message, mode, intent, result, selectedProduct = null, context = []) {
  const raw = plainVietnamese(message);
  const exchangeContext=adviserIsExchangeQuestion(message)||adviserIsExchangeQuestion((context||[]).join(' '));
  if (mode === 'store') return `Dạ, Tiệm vàng Kim Bảo Lâm hiện mở cửa ${cleanLabelText(shop.hours,120)}. Địa chỉ: ${cleanLabelText(shop.address,220)}. Anh/chị có thể cho em biết khu vực đang ở để em hướng dẫn cách đến tiệm thuận tiện hơn.`;
  if (mode === 'knowledge') {
    if (exchangeContext) {
      const origin=adviserExchangeOrigin(message,context);
      if(origin==='unknown') return adviserExchangeSourceQuestion();
      if(origin==='kbl') {
        const estimate=adviserPublicExchangeEstimate(message,context,selectedProduct);
        if(estimate&&estimate.ready){
          const p=estimate.product;
          const diff=estimate.kind==='equal'
            ? 'Vàng mới và vàng cũ đang bằng trọng lượng nên phần vàng chênh là 0.'
            : estimate.kind==='shortage'
              ? `Vàng mới nặng hơn ${Math.abs(estimate.deltaChi).toLocaleString('vi-VN')} chỉ; phần thiếu tạm tính ${Math.abs(estimate.deltaChi).toLocaleString('vi-VN')} × ${estimate.sell.toLocaleString('vi-VN')}đ = ${Math.abs(estimate.goldAmount).toLocaleString('vi-VN')}đ.`
              : `Vàng cũ dư ${Math.abs(estimate.deltaChi).toLocaleString('vi-VN')} chỉ; phần dư tạm tính ${Math.abs(estimate.deltaChi).toLocaleString('vi-VN')} × ${estimate.buy.toLocaleString('vi-VN')}đ = ${Math.abs(estimate.goldAmount).toLocaleString('vi-VN')}đ để cấn lại.`;
          const final=estimate.total>=0?`Tổng khách tạm thanh toán khoảng ${estimate.total.toLocaleString('vi-VN')}đ.`:`Sau khi cấn công, tiệm tạm trả lại khách khoảng ${Math.abs(estimate.total).toLocaleString('vi-VN')}đ.`;
          return `Dạ, đây là vàng mua tại Kim Bảo Lâm nên áp dụng Đổi Ngang KBL. Với ${p.name} (Mã SP ${p.sku}) nặng ${estimate.newWeightChi.toLocaleString('vi-VN')} chỉ và công niêm yết ${estimate.workmanship.toLocaleString('vi-VN')}đ: ${diff} ${final} Khi giao dịch, tiệm sẽ cân lại vàng cũ thực tế rồi mới xác nhận số cuối cùng.`;
        }
        return `Dạ, vàng mua tại Kim Bảo Lâm được tư vấn theo Đổi Ngang KBL. ${adviserExchangePolicyText()} Anh/chị hãy chọn đúng mẫu mới/Mã SP và cho em trọng lượng vàng cũ; tại quầy tiệm sẽ cân lại thực tế trước khi chốt.`;
      }
      const estimate=adviserPublicOutsideExchangeEstimate(message,context,selectedProduct);
      if(estimate&&estimate.ready){
        const p=estimate.product;
        const action=estimate.total>=0?`Khách tạm bù khoảng ${estimate.total.toLocaleString('vi-VN')}đ.`:`Sau cấn trừ, tiệm tạm trả khách khoảng ${Math.abs(estimate.total).toLocaleString('vi-VN')}đ.`;
        const extra=[];
        if(estimate.specialFee) extra.push(`phí đổi đang cài trong POS ${estimate.specialFee.toLocaleString('vi-VN')}đ`);
        if(estimate.benefit) extra.push(`khoản điều chỉnh đang cài trong POS ${estimate.benefit.toLocaleString('vi-VN')}đ`);
        return `Dạ, vì vàng cũ mua ở nơi khác nên tiệm áp dụng Đổi Vàng Bù, không áp dụng đổi ngang KBL. Vàng cũ ${estimate.oldType} ${estimate.oldWeightChi.toLocaleString('vi-VN')} chỉ được tính theo giá mua hiện tại ${estimate.oldBuy.toLocaleString('vi-VN')}đ/chỉ; mẫu ${p.name} (Mã SP ${p.sku}) dùng giá bán ${estimate.newType} hiện tại ${estimate.newSell.toLocaleString('vi-VN')}đ/chỉ và công của đúng Mã SP${extra.length?`, kèm ${extra.join(', ')}`:''}. ${action} Số cuối cùng được POS tính lại sau khi cân thực tế tại tiệm.`;
      }
      return `Dạ, vàng mua ở nơi khác sẽ đi theo Đổi Vàng Bù của POS. ${adviserOutsideExchangePolicyText()} Anh/chị cho em loại vàng cũ, trọng lượng và chọn mẫu/Mã SP muốn đổi để em tính tạm theo bảng giá đang chạy.`;
    }
    if (/610/.test(raw)) return 'Vàng 610 có hàm lượng vàng công bố 61,00%. Loại này thường được dùng cho trang sức vì có độ cứng phù hợp hơn vàng gần nguyên chất. Giá thực tế của từng món còn phụ thuộc trọng lượng, tiền công và mẫu sản phẩm.';
    if (/980/.test(raw)) return 'Vàng 980 có hàm lượng vàng công bố 98,00%. Nếu anh/chị hỏi giá, em sẽ lấy đúng bảng giá hiện tại của Kim Bảo Lâm; nếu hỏi một món trang sức, em sẽ tách giá vàng và tiền công theo đúng sản phẩm.';
    if (/9999/.test(raw)) return 'Vàng 9999 có hàm lượng vàng 99,99%, thường được xem là vàng gần nguyên chất. Giá mua/bán thay đổi theo bảng giá hiện tại; nếu anh/chị muốn, em có thể đọc giá đang niêm yết ngay lúc này.';
    if (/tien cong|gia cong/.test(raw)) return adviserPolicyFacts().workmanship;
    if (/bao hanh/.test(raw)) return adviserPolicyFacts().warranty;
    if (/thu doi|doi tra|doi ngang|doi bu/.test(raw)) return `${adviserPolicyFacts().exchange} ${adviserPolicyFacts().returns}`;
    if (/gia vang/.test(raw)) {
      const p=publicGoldPriceFacts().filter(x=>['9999','980','610'].includes(x.code)).map(x=>`${x.name}: mua ${x.buy.toLocaleString('vi-VN')}đ/chỉ, bán ${x.sell.toLocaleString('vi-VN')}đ/chỉ`).join('; ');
      return `Dạ, giá Kim Bảo Lâm hiện tại: ${p}. Anh/chị muốn em tính theo bao nhiêu chỉ/phân không ạ?`;
    }
  }
  if (mode === 'product') return adviserSummary(intent, result);
  return `Em hiểu câu “${cleanLabelText(message,120)}”, nhưng lượt này em chưa lấy được nguồn đủ chắc để trả lời chính xác. Em không muốn đoán bừa; anh/chị thử hỏi lại rõ hơn một chút hoặc gửi lại sau ít phút nhé.`;
}
function adviserGeminiContents(message, context = [], dialogue = []) {
  const allTurns = normalizeAdviserDialogue(dialogue);
  // V6.1: giữ đủ lượt gần nhất để hiểu câu nối tiếp, nhưng không bơm cả lịch sử dài vào model.
  // State quan trọng (mẫu/size/ngân sách/loại vàng/địa chỉ) đã được memory middleware giữ riêng.
  const wantedTurns = KBL_AI_V61_CONVERSATION_ENABLED
    ? Math.min(KBL_AI_V61_DIALOGUE_TURNS, adviserLooksLikeShortFollowup(message) ? 14 : 10)
    : AI_CHAT_MEMORY_TURNS;
  const turns = allTurns.slice(-wantedTurns);
  const contents = [];
  for (const turn of turns) {
    const role = turn.role === 'assistant' ? 'model' : 'user';
    if (!turn.text) continue;
    const previous = contents[contents.length - 1];
    if (previous && previous.role === role) {
      previous.parts[0].text += `\n${turn.text}`;
    } else {
      contents.push({ role, parts: [{ text: turn.text }] });
    }
  }
  if (!contents.length && Array.isArray(context) && context.length) {
    const recent = context.slice(-4).map(redactAdviserText).filter(Boolean);
    if (recent.length) contents.push({ role:'user', parts:[{ text:`Ngữ cảnh các câu khách đã nói trước đó:\n${recent.join('\n')}` }] });
  }
  const latest = redactAdviserText(message);
  const last = contents[contents.length - 1];
  // Memory middleware có thể đã chèn chính câu hiện tại vào dialogue. Không lặp lại lần hai.
  if (last && last.role === 'user' && plainVietnamese(last.parts[0].text).trim() === plainVietnamese(latest).trim()) {
    // đã có câu hiện tại
  } else if (last && last.role === 'user') last.parts[0].text += `\n${latest}`;
  else contents.push({ role:'user', parts:[{ text: latest }] });
  return contents.slice(-Math.max(8, wantedTurns));
}

function adviserLooksLikeShortFollowup(message) {
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (!raw || raw.length > 58) return false;
  if (/^(9999|980|750|610|585|416|24k|18k|14k|10k)$/.test(raw)) return true;
  if (/^(hop menh|hop mau|mau nao|mau gi|phong thuy|menh nao|con menh|the menh|vay menh)$/.test(raw)) return true;
  return /^(con |the |vay |roi |mau |mon |cai |no |loai |gia |bao nhieu|nhiu|nhieu|sao |duoc khong|co khong|van con|cai nay|cai do|mau nay|mau do|hop menh|hop mau|phong thuy)/.test(raw);
}

function kblAiV61SessionSummary(context = []) {
  if (!Array.isArray(context)) return '';
  const row = [...context].reverse().find((value) => /^Bộ nhớ phiên tư vấn:/i.test(String(value || '').trim()));
  return row ? cleanLabelText(row, 700) : '';
}

function kblAiV61PurchaseSignal(message) {
  const raw = plainVietnamese(message);
  return /\b(muon mua|can mua|chon mau|tim mau|giu mau|giu hang|dat lich|qua xem|chot mau|chot don|lay mau|lay cai|goi y mau|con hang|mau nao)\b/.test(raw);
}

function kblAiV61StyleCue(message, mode = 'general') {
  if (!KBL_AI_V61_CONVERSATION_ENABLED) return '';
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  const followup = adviserLooksLikeShortFollowup(message);
  const deep = /\b(tai sao|vi sao|phan tich|so sanh|giai thich ky|tung buoc|chi tiet)\b/.test(raw) || String(message || '').length > 220;
  const shopping = kblAiV61PurchaseSignal(message) || mode === 'product';
  const parts = [
    followup ? 'Đây là câu nối tiếp: trả lời thẳng ý đang nối, không chào lại và không bắt khách nhắc lại dữ kiện đã có.' : 'Bắt đầu bằng câu trả lời/kết luận, không mở bài kiểu trợ lý AI.',
    deep ? 'Câu này cần giải thích: có thể dài hơn nhưng chia đoạn ngắn, ưu tiên ví dụ dễ hiểu.' : 'Mục tiêu 1–4 câu tự nhiên; chỉ dài hơn khi thật sự cần.',
    shopping ? 'Có tín hiệu mua: chỉ gợi đúng một bước tiếp theo nếu nó giúp khách quyết định.' : 'Không có tín hiệu mua rõ: không chen quảng cáo, giữ mẫu, đặt lịch hay câu chốt bán hàng.',
    'Tránh lặp “Dạ, anh/chị” ở mọi lượt; có thể dùng “đúng rồi”, “nếu vậy thì…”, “còn trường hợp này…” khi hợp ngữ cảnh.'
  ];
  return parts.join(' ');
}


// ============================================================================
// KBL AI ADVISER V7 — SALES DECISION BRAIN (LOCAL / ZERO EXTRA API CALL)
// Chỉ nâng tầng hiểu khách + điều phối hội thoại. Không sửa POS, giá, kho,
// chính sách, đơn hàng, Try-on, Prompt AI hay giao diện Home/Admin.
// ============================================================================
function kblAiV7CustomerStage(message, memoryState = {}) {
  if (!KBL_AI_V7_SALES_BRAIN_ENABLED) return '';
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (!raw) return cleanLabelText(memoryState && memoryState.customerStage,30) || 'browse';
  if (/\b(chot mau|chot don|muon mua|lay mau|lay cai|giu mau|giu hang|dat lich|hen qua|qua xem|ghe xem|toi xem|mua luon|lay luon)\b/.test(raw)) return 'ready';
  if (/\b(so sanh|phan van|nen chon|chon cai nao|mau nao hon|cai nao hon|khac nhau|con hang|con khong|gia mau|gia cai|thu len|thu ai|hop tay|deo hang ngay|co ben khong)\b/.test(raw)) return 'decision';
  if (/\b(tim mau|goi y|mau nao|muon xem|can mua|mua tang|mua cho|ngan sach|tam gia|khoang|thich|phong cach|nhan|day chuyen|bong tai|lac tay|mat day)\b/.test(raw)) return 'consideration';
  return 'browse';
}

function kblAiV7DecisionFriction(message) {
  if (!KBL_AI_V7_SALES_BRAIN_ENABLED) return '';
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (/\b(mac|dat qua|cao qua|cong cao|gia cao|vuot ngan sach|khong du tien|re hon)\b/.test(raw)) return 'price';
  if (/\b(khong thich|khong hop|khong ung|xau|hoi to|hoi nho|qua to|qua nho|khong dung gu|mau khac)\b/.test(raw)) return 'style-fit';
  if (/\b(so hang gia|that khong|uy tin|bao hanh|chat luong|co dam bao|co chac|da gi|kim cuong)\b/.test(raw)) return 'trust';
  if (/\b(size|ni|rong|chat|vua khong|hop tay|deo vua|kich thuoc)\b/.test(raw)) return 'fit-size';
  if (/\b(con hang|het hang|khi nao co|co san|giu duoc)\b/.test(raw)) return 'availability';
  return '';
}

function kblAiV7BuyingSignal(message, intent = {}, selectedProduct = null) {
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  const explicit=/\b(muon mua|can mua|tim mau|goi y mau|chon mau|mua tang|mua cho|mau nao|nhan vang|nhan cuoi|nhan hot|day chuyen|bong tai|lac tay|mat day|trang suc|giu mau|dat lich|qua xem)\b/.test(raw);
  const productFollowup=Boolean(selectedProduct) && (adviserLooksLikeShortFollowup(message) || /\b(gia|con hang|con khong|size|ni|trong luong|tien cong|mau nay|cai nay|mau do|cai do|deo|hop|thu)\b/.test(raw));
  if (explicit || productFollowup) return true;
  if (intent && (number(intent.budget)>0 || cleanLabelText(intent.style,80) || cleanLabelText(intent.recipient,80) || cleanLabelText(intent.purpose,80) || (intent.category && intent.category !== 'other' && /\b(mua|tim|chon|xem|goi y|gia|mau|trang suc)\b/.test(raw)))) return true;
  return false;
}

function kblAiV7ResponsePace(message, stage, friction) {
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (/\b(chi can|noi ngan|ngan gon|nhanh|gap|bao gia|bao nhieu)\b/.test(raw)) return 'fast';
  if (friction || stage === 'decision') return 'reassure';
  if (/\b(tai sao|vi sao|phan tich|so sanh|giai thich|chi tiet|tu van ky)\b/.test(raw) || String(message||'').length > 180) return 'deep';
  return 'natural';
}

function kblAiV7BestNextAction(stage, message, intent = {}, selectedProduct = null, productCount = 0, friction = '') {
  if (!KBL_AI_V7_SALES_BRAIN_ENABLED) return 'none';
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  if (!kblAiV7BuyingSignal(message,intent,selectedProduct)) return 'none';
  if (friction === 'price') return 'solve-objection-first';
  if (friction === 'style-fit' || friction === 'fit-size') return selectedProduct ? 'try-or-compare' : 'refine-one-preference';
  if (friction === 'trust') return 'explain-verified-facts-first';
  if (friction === 'availability') return selectedProduct ? 'verify-stock' : 'identify-product';
  if (stage === 'ready') return selectedProduct ? 'hold-or-book' : 'identify-product';
  if (stage === 'decision') return productCount >= 2 ? 'compare-shortlist' : (selectedProduct ? 'try-or-book' : 'refine-one-preference');
  if (stage === 'consideration') {
    if (!intent || (!intent.category && !number(intent.budget) && !intent.style && !intent.purpose && !intent.recipient)) return 'ask-one-high-value-preference';
    return productCount ? 'show-shortlist' : 'refine-one-preference';
  }
  return 'none';
}

function kblAiV7SalesBrain(message, context = [], dialogue = [], intent = {}, selectedProduct = null, products = [], memoryState = {}) {
  if (!KBL_AI_V7_SALES_BRAIN_ENABLED) return null;
  const state = memoryState && typeof memoryState === 'object' ? memoryState : {};
  const buyingSignal = kblAiV7BuyingSignal(message,intent,selectedProduct);
  const stageNow = kblAiV7CustomerStage(message, state);
  const rememberedStage = cleanLabelText(state.customerStage,30);
  // Khi khách đổi sang chủ đề khác, không để funnel cũ kéo ngược cuộc trò chuyện về bán hàng.
  const stage = stageNow !== 'browse' ? stageNow : (buyingSignal ? (rememberedStage || 'consideration') : 'browse');
  const frictionNow = kblAiV7DecisionFriction(message);
  const friction = buyingSignal ? (frictionNow || cleanLabelText(state.decisionFriction,40)) : '';
  const productCount = Array.isArray(products) ? products.filter(Boolean).length : 0;
  const pace = kblAiV7ResponsePace(message,stage,friction);
  const nextAction = kblAiV7BestNextAction(stage,message,intent,selectedProduct,productCount,friction);
  const known = {
    category: cleanLabelText(intent&&intent.category || state.category,30),
    budget: Math.max(0,number(intent&&intent.budget || state.budget)),
    goldCode: cleanLabelText(intent&&intent.goldCode || state.goldCode,10),
    weightChi: Math.max(0,number(intent&&intent.weightChi || state.weightChi)),
    sizeLabel: cleanLabelText(intent&&intent.sizeLabel || state.sizeLabel,40),
    recipient: cleanLabelText(intent&&intent.recipient || state.recipient,80),
    style: cleanLabelText(intent&&intent.style || state.style,80),
    purpose: cleanLabelText(intent&&intent.purpose || state.purpose,80),
    selectedSku: selectedProduct ? cleanInventoryCode(selectedProduct.sku) : cleanInventoryCode(state.selectedSku)
  };
  let bestQuestion='';
  if (buyingSignal && stage !== 'ready') {
    if (!known.category && !selectedProduct) bestQuestion='Khách đang cần loại trang sức nào là câu làm thay đổi kết quả nhiều nhất.';
    else if (!known.budget && !selectedProduct && stage !== 'browse') bestQuestion='Nếu cần thu hẹp nhiều mẫu, hỏi tầm ngân sách; nếu vẫn tư vấn tốt được thì đừng hỏi.';
    else if (!known.style && !selectedProduct && stage === 'consideration') bestQuestion='Nếu có quá nhiều mẫu tương đương, hỏi một lựa chọn gu: thanh lịch/dễ đeo hay nổi bật.';
    else if (selectedProduct && stage === 'decision' && friction === 'fit-size' && !known.sizeLabel) bestQuestion='Hỏi ni/size vì đang ảnh hưởng trực tiếp quyết định.';
  }
  return {
    version:'7.0', stage, buyingSignal, friction:friction||'none', pace, nextAction,
    known, productCount, hasSelectedProduct:Boolean(selectedProduct), bestQuestion,
    rules:[
      'Trả lời câu hiện tại trước, rồi mới dẫn bước tiếp theo.',
      'Không hỏi lại dữ kiện đã có trong known/session memory.',
      'Tối đa một câu hỏi mỗi lượt; ưu tiên câu làm thay đổi quyết định nhiều nhất.',
      'Khách phản đối/đắn đo thì xử lý lý do đó trước, không chốt bán ngay.',
      'Chỉ gợi sản phẩm thật từ verified inventory; không bịa mã/giá/tồn kho.',
      'Nếu khách không có tín hiệu mua, không kéo họ vào funnel.'
    ]
  };
}

function kblAiV61NeedsFreshWeb(message) {
  if (kblAiV5ExplicitResearchRequest(message)) return true;
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  // Không search chỉ vì có từ "hôm nay/bây giờ" trong câu đời thường.
  // Phải đồng thời có tín hiệu cần dữ liệu thay đổi theo thời gian hoặc một chủ đề vốn biến động.
  const freshCue = /\b(hom nay|hien nay|bay gio|luc nay|moi nhat|cap nhat|vua xay ra|tin moi|duong kim|ai dang la|hien tai ai)\b/.test(raw);
  const liveDomain = /\b(gia|ty gia|tin tuc|thi truong|luat|quy dinh|thue|lai suat|tong thong|thu tuong|chu tich|ceo|ket qua tran|ti so|lich thi dau|thoi tiet|co phieu|crypto|bitcoin|vang the gioi|xang dau)\b/.test(raw);
  const inherentlyLive = /\b(kqxs|xo so|ket qua tran|ti so|lich thi dau|thoi tiet|gia co phieu|gia crypto|gia bitcoin|ty gia)\b/.test(raw);
  return inherentlyLive || (freshCue && liveDomain);
}

function kblAiV61NeedsToolAgent(message, mode, intent = {}, requestContext = {}) {
  if (!KBL_AI_V61_CONVERSATION_ENABLED || !KBL_AI_V61_ADAPTIVE_TOOL_ROUTING) return true;
  // V8: Agent gets first chance on every normal conversational turn. It may answer directly
  // without calling a tool, but any KBL/current fact must still be sourced through verified context/tools.
  if (KBL_AI_V8_AGENT_FIRST_ENABLED && GEMINI_API_KEY) return true;
  const raw = plainVietnamese(message).replace(/\s+/g,' ').trim();
  const brain = requestContext && requestContext.brainPlan || {},multi=requestContext&&requestContext.multilingualPlan||null;
  if (kblAiV61NeedsFreshWeb(message) || brain.webAllowed || (multi&&multi.needsFreshWeb)) return true;
  if (multi&&(['product','store'].includes(String(multi.mode||''))||['hold','booking','buy'].includes(String(multi.action||''))||String(multi.policyTopic||''))) return true;
  if (adviserIsExchangeQuestion(message)) return true;
  if (/\b(tru hot|tru da|hao hut|quy doi|tinh tien|tinh tong|thanh tien|mua vao|ban ra|thu vao|doi vang|cam do|lai suat)\b/.test(raw)) return true;
  if (/\b(diem vip|diem thuong|vip|tracking|ma van don|don hang|tinh trang don|bao hanh dien tu)\b/.test(raw)) return true;
  if (/\b(con hang|het hang|ton kho|ma sp|ma san pham|mau \d+|mon thu|cai vua|mau vua|mau nay|mau do|cai nay|cai do)\b/.test(raw)) return true;
  if (mode === 'product' && requestContext && requestContext.selectedProduct && /\b(gia|con|size|ni|trong luong|cong|chi tiet|mau nay|cai nay)\b/.test(raw)) return true;
  const numericCount = (String(message || '').match(/\d+(?:[.,]\d+)?/g) || []).length;
  if (numericCount >= 3 && /\b(vang|tien|gia|doi|mua|ban|loi|lai|phi)\b/.test(raw)) return true;
  return false;
}

function adviserThinkingLevel(message, mode, intent = {}) {
  const raw = plainVietnamese(message),original=String(message||'').toLowerCase();
  const complexVi=/(tai sao|vi sao|so sanh|phan tich|khac nhau|uu diem|nhuoc diem|nen chon|tinh|tinh toan|doi vang|thu doi|loi nhuan|diem|vip|bao lau|moi thang|moi ngay|tiet kiem|de danh|kiem duoc|ban duoc|mua duoc)/.test(raw);
  const complexIntl=/(why|compare|comparison|analy[sz]e|difference|pros|cons|which should|calculate|calculation|exchange|profit|interest|explain|recommend|trade-?off|porque|comparar|analizar|diferencia|pourquoi|comparer|analyser|warum|vergleichen|analysieren|为什么|比較|比较|分析|どうして|なぜ|比較|분석|비교|왜)/iu.test(original);
  if (complexVi||complexIntl) return 'medium';
  // Câu nối tiếp thật sự ngắn vẫn ưu tiên tốc độ; phần phức tạp ở mọi ngôn ngữ đã được nâng ở trên.
  if (adviserLooksLikeShortFollowup(message)) return 'low';
  if (mode === 'product' && raw.length < 160) return 'low';
  if (mode === 'general') return String(message||'').length > 220 ? 'medium' : 'low';
  if (Number(intent && intent.budget) > 0 && String(message||'').length > 140) return 'medium';
  return String(message||'').length > 200 ? 'medium' : 'low';
}

