const CLOUD_PRICE_DEFAULT_RELAY_URL = 'https://script.google.com/macros/s/AKfycbxTpmcPTF6kgUbraMyeaxR-uVIh9U7ePKXYfcSLZZeRJ6l5tk5vA4aau3VHMw9iGfZm/exec';
const CLOUD_PRICE_DEFAULT_POLL_MS = 12000;
