const KBL_SOURCE_VIDEO_STREAM_MAX_BYTES = Math.max(80 * 1024 * 1024, Math.min(1024 * 1024 * 1024, Number(process.env.KBL_SOURCE_VIDEO_STREAM_MAX_BYTES || 600 * 1024 * 1024) || 600 * 1024 * 1024));
