const kblStudioMediaCache = new Map();
async function kblStudioMediaInfo(source) {
  const safe = safeStudioVideoSource(source), file = safe && publisherLocalPublicPath(safe);
  if (!file || !/\.(mp4|mov|webm)$/i.test(file)) throw new Error('RAW/render phải là video đã upload lên website.');
  const st = await fs.promises.stat(file), key = file + ':' + st.size + ':' + st.mtimeMs;
  let hash = kblStudioMediaCache.get(key);
  if (!hash) { const h = crypto.createHash('sha256'); for await (const bytes of fs.createReadStream(file)) h.update(bytes); hash = h.digest('hex'); kblStudioMediaCache.clear(); kblStudioMediaCache.set(key, hash); }
  return {path:file, source:safe, size:st.size, hash, mime:/\.webm$/i.test(file)?'video/webm':/\.mov$/i.test(file)?'video/quicktime':'video/mp4'};
}
