const kblHistoryDayFormatter = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit' });
app.get('/api/prices/history', (_req, res) => {
  priceHistory = prunePriceHistory(priceHistory);
  const records = priceHistory.map((entry) => ({ at: entry.at, source: entry.source, prices: entry.prices }));
  const vietnamDay = (value) => {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value || '').slice(0, 10);
    const parts = kblHistoryDayFormatter.formatToParts(date);
    const map = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    return `${map.year}-${map.month}-${map.day}`;
  };
  const parseDayUtc = (key) => {
    const match = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return match ? new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]))) : null;
  };
  const shiftDay = (key, offset) => {
    const date = parseDayUtc(key);
    if (!date) return key;
    date.setUTCDate(date.getUTCDate() + offset);
    return date.toISOString().slice(0, 10);
  };
  const todayKey = vietnamDay(new Date());
  const recordDays = records.map(entry => vietnamDay(entry.at));
  const firstRecordDay = recordDays[0] || '';
  const daily = [];
  let recordIndex = 0, effective = null, effectiveDay = '';
  // Tạo tối đa 7 mốc ngày liên tục. Nếu một ngày không đổi giá, dùng giá hiệu lực gần nhất trước đó.
  // Không bịa dữ liệu trước ngày hệ thống bắt đầu ghi lịch sử.
  for (let offset = -6; offset <= 0; offset += 1) {
    const date = shiftDay(todayKey, offset);
    if (firstRecordDay && date < firstRecordDay) continue;
    while (recordIndex < records.length && recordDays[recordIndex] <= date) {
      effective = records[recordIndex];
      effectiveDay = recordDays[recordIndex];
      recordIndex += 1;
    }
    if (effective) daily.push({ date, ...effective, carriedForward: effectiveDay !== date });
  }
  const pair = latestPriceHistoryPair();
  json(res, 200, { success: true, days: 7, history: records, daily, current: pair.current, previous: pair.previous, changes: priceChangeMap() });
});
app.get('/api/prices/stream', rateLimit('price-stream', 30, 5 * 60 * 1000), (req, res) => {
  if (streams.size >= 200) return json(res, 503, { success: false, message: 'Bảng giá đang bận, vui lòng tải lại sau.' });
  res.status(200).set({ 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive' });
  if (res.flushHeaders) res.flushHeaders(); streams.add(res); res.write(`event: prices\ndata: ${JSON.stringify(pricePayload('initial'))}\n\n`);
  const timer = setInterval(() => { try { res.write(': keep-alive\n\n'); } catch (_) { clearInterval(timer); streams.delete(res); } }, 20000);
  req.on('close', () => { clearInterval(timer); streams.delete(res); });
});

app.post('/api/prices', rateLimit('admin-price', 30, 10 * 60 * 1000), (req, res) => {
  if (!requireAdmin(req, res)) return;
  const incoming = req.body && req.body.prices && typeof req.body.prices === 'object' ? req.body.prices : req.body;
  if (!incoming || typeof incoming !== 'object') return json(res, 400, { success: false, message: 'Dữ liệu bảng giá không hợp lệ.' });
  const saved = savePrices(incoming, 'remote');
  auditEvent(req, 'price.update', 'ok', { actor: 'owner', sell9999: saved.price_sell_9999 });
  return json(res, 200, { success: true, prices: saved });
});
app.post('/api/sync/cloud-price-config', rateLimit('sync-cloud-price', 60, 10 * 60 * 1000), (req, res) => {
  if (!requireSync(req, res)) return;
  const input = req.body && req.body.config && typeof req.body.config === 'object' ? req.body.config : req.body;
  if (!input || typeof input !== 'object') return json(res, 400, { success: false, message: 'Cấu hình Cloud Price không hợp lệ.' });
  try {
    const status = saveCloudPriceConfig(input);
    auditEvent(req, 'cloud-price.config-sync', 'ok', { actor: 'pos', enabled: status.enabled, markupVnd: status.markupVnd, pollMs: status.pollMs });
    triggerCloudPricePoll('config-sync');
    return json(res, 200, { success: true, cloudPrice: status });
  } catch (error) {
    return json(res, 400, { success: false, message: error.message || String(error) });
  }
});
app.post('/api/sync/prices', rateLimit('sync-price', 120, 10 * 60 * 1000), (req, res) => {
  if (!requireSync(req, res)) return;
  const incoming = req.body && req.body.prices && typeof req.body.prices === 'object' ? req.body.prices : req.body;
  const cloudConfig = effectiveCloudPriceConfig();
  const cloudOwnsBase = cloudConfig.enabled && Boolean(cloudConfig.relayUrl && cloudConfig.relayToken) && Boolean(cloudPriceRuntime.lastSuccessAt);
  const mergedIncoming = incoming && typeof incoming === 'object' ? { ...incoming } : {};
  if (cloudOwnsBase) mergedIncoming.price_sell_9999 = prices.price_sell_9999;
  const saved = savePrices(mergedIncoming, cloudOwnsBase ? 'pos-sync-settings' : 'pos-sync');
  auditEvent(req, 'price.sync', 'ok', { actor: 'pos', sell9999: saved.price_sell_9999, cloudOwnsBase });
  kblDiscoveryQueueUrls(kblDiscoveryCoreUrls(),'price-sync');
  return json(res, 200, { success: true, prices: saved });
});

