app.post('/api/shipping/estimate', rateLimit('shipping-estimate', 30, 10 * 60 * 1000), async (req, res) => {
  const input = req.body || {};
  const product = verifiedAdviserStock().find((item) => String(item.id) === String(input.productId || '')) || null;
  const requestContext = {
    selectedProduct: product,
    recentProducts: product ? [product] : [],
    latitude: validLatitude(input.latitude),
    longitude: validLongitude(input.longitude),
    accuracy: Math.max(0, number(input.accuracy))
  };
  const quote = await kblAgentShippingQuote({ address: cleanLabelText(input.address,300), accuracy:Math.max(0,number(input.accuracy)) }, requestContext);
  if (!quote.ready) {
    const message = quote.reason === 'missing-location-or-geoapify-key'
      ? 'Chưa nhận được vị trí hợp lệ hoặc GEOAPIFY_API_KEY chưa được cấu hình.'
      : quote.reason === 'shop-location-missing'
        ? 'Chưa xác định được vị trí cửa hàng. Hãy kiểm tra địa chỉ cửa hàng hoặc GEOAPIFY_API_KEY.'
        : quote.reason === 'poor-location-accuracy'
          ? 'Vị trí thiết bị đang quá sai số. Anh/chị bật Vị trí chính xác hoặc nhập địa chỉ rõ hơn rồi thử lại.'
          : 'Chưa nhận được vị trí hợp lệ của khách. Anh/chị hãy cho phép vị trí và thử lại.';
    return json(res, 400, { success: false, message, reason: quote.reason });
  }
  auditEvent(req, 'shipping.estimate', 'ok', { productId: product && product.id || '', distanceKm: quote.distanceKm, waived: quote.waived, method: quote.method || '' });
  json(res, 200, { success: true, quote: { distanceKm: quote.distanceKm, durationMinutes: quote.durationMinutes || 0, fee: quote.fee, waived: quote.waived, waiverReason: quote.waiverReason, requiresOwner: quote.requiresOwner, address: quote.address || '', method: quote.method || '', calculatedAt: new Date().toISOString() } });
});

