app.post('/api/auth/register', rateLimit('register', 5, 30 * 60 * 1000), (req, res) => {
  if (!PUBLIC_REGISTRATION_ENABLED) {
    auditEvent(req, 'customer.register', 'disabled');
    return json(res, 403, { success: false, message: 'Đăng ký tài khoản khách đang tạm khóa.' });
  }
  const phone = phoneKey(req.body && req.body.phone);
  const password = String(req.body && req.body.password || '');
  const name = cleanLabelText(req.body && req.body.name, 100);
  if (!/^0[0-9]{8,11}$/.test(phone)) return json(res, 400, { success: false, message: 'Số điện thoại chưa đúng.' });
  if (password.length < 8 || password.length > 128) return json(res, 400, { success: false, message: 'Mật khẩu cần từ 8 đến 128 ký tự.' });
  const existing = users.find((u) => phoneKey(u.phone) === phone);
  if (existing) return json(res, 409, { success: false, code:'ACCOUNT_EXISTS', message: 'Số điện thoại này đã có tài khoản. Vui lòng đăng nhập.' });
  const pass = hashPassword(password);
  const user = { id: 'u_' + crypto.randomBytes(16).toString('hex'), phone, name, salt: pass.salt, hash: pass.hash, createdAt: new Date().toISOString(), verifiedAt: null, tryOnBonusRemaining: 0 };
  users.push(user); writeJson(USERS_FILE, users);
  setSession(res, user);
  markAccountActivity(user, res);
  auditEvent(req, 'customer.register', 'ok', { phoneHash: shortHash(phone), userId: user.id });
  return json(res, 201, { success: true, user: publicAccountUser(user), message: 'Đã tạo tài khoản và đăng nhập. Tài khoản có thể dùng Premium Try-on ngay.' });
});
app.post('/api/auth/login', rateLimit('login', 10, 15 * 60 * 1000), (req, res) => {
  const phone = phoneKey(req.body && req.body.phone);
  const user = users.find((u) => phoneKey(u.phone) === phone);
  const password = String(req.body && req.body.password || '');
  const valid = password.length <= 128 && verifyPassword(password, user || DUMMY_USER);
  if (!user || !valid) {
    auditEvent(req, 'customer.login', 'denied', { phoneHash: shortHash(phone) });
    return json(res, 401, { success: false, message: 'Số điện thoại hoặc mật khẩu không đúng.' });
  }
  setSession(res, user);
  markAccountActivity(user, res);
  auditEvent(req, 'customer.login', 'ok', { phoneHash: shortHash(phone), userId:user.id });
  return json(res, 200, { success: true, user: publicAccountUser(user) });
});

