app.post('/api/prompt-ai/consult',rateLimit('prompt-ai-consult',30,10*60*1000),async(req,res)=>{
  const user=requireUser(req,res);if(!user)return;
  const account=kblPromptAccount(user,true),profile=kblPromptProfile(account.profile),allowance=kblPromptConsultAllowance(account);
  if(!kblPromptProfileComplete(profile))return json(res,409,{success:false,code:'PROFILE_REQUIRED',message:'Vui lòng hoàn thành Cài đặt ngành nghề trước khi dùng AI tư vấn.'});
  if(allowance.remaining<=0)return json(res,429,{success:false,code:'CONSULT_LIMIT',message:`Đã đạt giới hạn ${allowance.max} lượt tư vấn AI hôm nay. Hãy quay lại sau hoặc dùng brief đã chốt.`});
  const mode=String(req.body&&req.body.mode)==='video'?'video':'image',phase=String(req.body&&req.body.phase)==='business'?'business':'creative';
  const message=kblPromptText(req.body&&req.body.message,2400),rawImages=Array.isArray(req.body&&req.body.images)?req.body.images:(req.body&&req.body.image?[req.body.image]:[]),images=kblPromptImages(rawImages);
  if(!message&&!images.length)return json(res,400,{success:false,message:'Hãy nhập yêu cầu hoặc gửi ít nhất một ảnh tham chiếu.'});
  if(rawImages.length>10)return json(res,400,{success:false,message:'Mỗi lần hỗ trợ tối đa 10 ảnh.'});
  if(rawImages.length&&images.length!==rawImages.length)return json(res,400,{success:false,message:'Ảnh phải là PNG/JPEG/WebP; tối đa khoảng 3,5MB/ảnh và tổng khoảng 18MB.'});
  try{
    const result=await kblPromptGeminiConsult({mode,message,history:req.body&&req.body.history,profile,images:rawImages,businessContext:account.businessContext,phase,previousBrief:req.body&&req.body.previousBrief,referenceImageCountHint:req.body&&req.body.referenceImageCount});
    account.businessContext=kblPromptMergeBusinessContext(account.businessContext,result.result&&result.result.businessContextUpdate);
    account.consultDay=kblPromptDayKey();account.consultCalls=Math.max(0,number(account.consultCalls))+1;account.updatedAt=new Date().toISOString();
    const usage=result.usage||{},row={id:'PC-'+crypto.randomBytes(8).toString('hex').toUpperCase(),kind:'consult',userId:user.id,mode,phase,imageCount:images.length,model:result.model,at:new Date().toISOString(),promptTokens:number(usage.promptTokenCount),completionTokens:number(usage.candidatesTokenCount),totalTokens:number(usage.totalTokenCount)};
    kblPromptState.usage.push(row);kblPromptState.usage=kblPromptState.usage.slice(-10000);kblPromptSave();
    return json(res,200,{success:true,consultant:result.result,model:result.model,research:result.research||{used:false},consult:kblPromptConsultAllowance(account),businessContext:kblPromptBusinessContext(account.businessContext),credits:account.credits});
  }catch(error){return json(res,502,{success:false,message:kblPromptText(error&&error.message||'Gemini Consultant chưa phản hồi.',320)})}
});
app.post('/api/prompt-ai/finalize',rateLimit('prompt-ai-finalize',20,10*60*1000),async(req,res)=>{
  const user=requireUser(req,res);if(!user)return;
  const account=kblPromptAccount(user,true),profile=kblPromptProfile(account.profile);
  if(!kblPromptProfileComplete(profile))return json(res,409,{success:false,code:'PROFILE_REQUIRED',message:'Vui lòng hoàn thành Cài đặt trước.'});
  const mode=String(req.body&&req.body.mode)==='video'?'video':'image';
  const brief=req.body&&req.body.brief&&typeof req.body.brief==='object'&&!Array.isArray(req.body.brief)?req.body.brief:null;
  if(!brief)return json(res,400,{success:false,message:'Business/Creative Brief chưa sẵn sàng. Hãy tư vấn với Gemini trước khi chốt.'});
  const promptCount=kblPromptBriefPromptCount(brief);
  if(account.credits<promptCount)return json(res,402,{success:false,code:'CREDITS_REQUIRED',message:`Cần ${promptCount} lượt để tạo ${promptCount} prompt riêng, nhưng tài khoản chỉ còn ${account.credits} lượt.`,needPayment:true,requiredCredits:promptCount});
  // Reserve đúng số prompt trước call để chống bấm song song; lỗi upstream hoàn đủ.
  account.credits-=promptCount;account.updatedAt=new Date().toISOString();kblPromptSave();
  try{
    const final=await kblPromptFinalizeAgentV8({mode,brief:{...brief,promptCount},profile});
    account.totalFinalized=Math.max(0,number(account.totalFinalized))+promptCount;account.updatedAt=new Date().toISOString();
    const u=final.usage||{},cached=number(u.prompt_tokens_details&&u.prompt_tokens_details.cached_tokens);
    kblPromptState.usage.push({id:'PF-'+crypto.randomBytes(8).toString('hex').toUpperCase(),kind:'final',userId:user.id,mode,promptCount,model:final.model,at:new Date().toISOString(),promptTokens:number(u.prompt_tokens),completionTokens:number(u.completion_tokens),cachedTokens:cached,totalTokens:number(u.total_tokens)});
    kblPromptState.usage=kblPromptState.usage.slice(-10000);kblPromptSave();
    return json(res,200,{success:true,prompt:final.prompt,prompts:final.prompts,promptCount,model:final.model,charged:promptCount,credits:account.credits,platforms:kblPromptState.settings.platforms[mode].filter(x=>x.enabled!==false)});
  }catch(error){
    account.credits+=promptCount;account.updatedAt=new Date().toISOString();kblPromptSave();
    return json(res,502,{success:false,message:kblPromptText(error&&error.message||'Prompt Final Director chưa tạo được prompt cuối.',320),refunded:true,refundedCredits:promptCount,credits:account.credits});
  }
});
