app.post('/api/my/favorites', rateLimit('favorites', 60, 10 * 60 * 1000), (req, res) => {
  const user = sessionUser(req);
  if (!user) return json(res, 401, { success: false, code: 'LOGIN_REQUIRED', message: 'Vui lòng đăng nhập để lưu sản phẩm yêu thích.' });
  const product = visibleProductById(req.body && req.body.productId);
  if (!product) return json(res, 404, { success: false, message: 'Không tìm thấy sản phẩm đang hiển thị.' });
  const customer = ensureCustomerForUser(user);
  customer.favoriteProductIds = Array.isArray(customer.favoriteProductIds) ? customer.favoriteProductIds.map(String) : [];
  const id = String(product.id);
  const requested = req.body && typeof req.body.active === 'boolean' ? req.body.active : !customer.favoriteProductIds.includes(id);
  const had = customer.favoriteProductIds.includes(id);
  if (requested && !had) customer.favoriteProductIds.unshift(id);
  if (!requested && had) customer.favoriteProductIds = customer.favoriteProductIds.filter((value) => value !== id);
  customer.favoriteProductIds = customer.favoriteProductIds.slice(0, 200);
  customer.lastInterestAt = new Date().toISOString();
  customer.customerStatus = number(customer.completedOrders) > 0 ? 'Khách cũ' : 'Khách quan tâm';
  writeJson(CUSTOMERS_FILE, customers);
  if (requested && !had) recordProductMetric(product, 'favorite');
  auditEvent(req, requested ? 'favorite.add' : 'favorite.remove', 'ok', { userId: user.id, productId: id, sku: cleanInventoryCode(product.sku) });
  return json(res, 200, { success: true, active: requested, favoriteProductIds: customer.favoriteProductIds });
});

