  const scenes=videoStudioBuildSceneChain(templateId,snap,priceRows,title,productRows,providedScript,directorStyle,directorNote,durationSeconds,Boolean(providedScript));
  const script=providedScript||scenes.map(s=>s.script).filter(Boolean).join('\n');
