  const schema={type:'object',additionalProperties:false,properties:{facebookCaption:{type:'string'},tiktokCaption:{type:'string'},youtubeCaption:{type:'string'},reelCaption:{type:'string'}},required:['facebookCaption','tiktokCaption','youtubeCaption','reelCaption']};
