app.get('/api/admin/products', (req, res) => {
  if (!requireAdmin(req, res)) return;
  if(req.query.limit!==undefined){
    const limit=Number(req.query.limit),offset=Number(req.query.offset||0);
    if(!Number.isInteger(limit)||limit<1||limit>100||!Number.isSafeInteger(offset)||offset<0)return json(res,400,{success:false,message:'Tham số trang kho không hợp lệ.'});
    const revision=crypto.createHash('sha256').update(JSON.stringify(products.map(p=>[p.id,p.updatedAt||'',p.status||'',p.publicationStatus||'']))).digest('hex');
    if(req.query.revision&&String(req.query.revision)!==revision)return json(res,409,{success:false,message:'Kho vừa thay đổi. Hãy tải lại từ đầu.'});
    const next=offset+limit;
    return kblAdminReadJson(req,res,{success:true,products:products.slice(offset,next).map(productForAdmin),total:products.length,nextOffset:next<products.length?next:null,revision});
  }
  kblAdminReadJson(req,res,{ success: true, products: products.map(productForAdmin) });
});
