app.post('/api/admin/orders/:id/status', (req, res) => {
  if (!requireAdmin(req, res)) return;
  const order = orders.find((item) => item.id === req.params.id);
  if (!order) return json(res, 404, { success: false, message: 'Không tìm thấy yêu cầu.' });
  const allowedStatuses = ['Mới', 'Chờ xác nhận', 'Đã liên hệ', 'Đã xác nhận', 'Hoàn tất', 'Đã hủy', 'Chờ xác nhận quốc tế', 'Chờ thanh toán quốc tế', 'Chờ xác minh thanh toán quốc tế', 'Đã thanh toán quốc tế', 'Đang chuẩn bị quốc tế', 'Đã giao hãng vận chuyển', 'Khách hủy thanh toán quốc tế'];
  const requestedStatus = String(req.body && req.body.status || 'Đã liên hệ');
  order.status = allowedStatuses.includes(requestedStatus) ? requestedStatus : 'Đã liên hệ';
  order.updatedAt = new Date().toISOString();
  saveOrders();
  if (order.status === 'Hoàn tất') {
    order.completedAt = order.completedAt || order.updatedAt;
    markCustomerOrderComplete(order);
    if (kblCommerceV5) { const w=kblCommerceV5.autoWarrantyForOrder(order,{source:'admin-order-complete'}); if(w&&w.success){order.warrantyId=w.warranty.id;saveOrders();} kblCommerceV5.releaseReservation({orderId:order.id,reason:'order-complete'}); }
  }
  if (order.status === 'Đã hủy' && kblCommerceV5) kblCommerceV5.releaseReservation({orderId:order.id,reason:'order-cancelled'});
  auditEvent(req, 'order.status', 'ok', { orderId: order.id, status: order.status });
  json(res, 200, { success: true, order });
});
