app.post('/api/admin/content/generate', rateLimit('ai-content', 30, 10 * 60 * 1000), async (req, res) => {
  if (!requireAdmin(req, res)) return;
  if (!AI_CONTENT_ENABLED) return json(res, 503, { success:false, message:'AI Content Studio đang tắt.' });
  const input=req.body||{}, productId=String(input.productId||'').trim(), product=products.find(item=>String(item.id)===productId);
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  if(normalizeProductKind(product.kind)!=='current'||String(product.status||'')!=='available'||!cleanInventoryCode(product.sku)||!contentReferenceImageSource(product)) return json(res,409,{success:false,message:'Sản phẩm POS phải đang còn hàng, có Mã SP và đã có ảnh gốc hoặc ảnh trưng bày đã duyệt trước khi tạo nội dung.'});
  const snapshot=contentProductSnapshot(product); if(!snapshot||snapshot.referencePrice<=0)return json(res,409,{success:false,message:'Sản phẩm chưa có giá tham khảo hợp lệ.'});
  const campaign=cleanLabelText(input.campaign,160), tone=normalizeContentTone(input.tone);
  const gemini=await geminiContentDraft(snapshot,campaign,tone), openai=gemini?null:await openAiContentDraft(snapshot,campaign,tone), ai=gemini||openai, content=ai||localContentDraft(snapshot,campaign,tone);
  const engine=gemini?'gemini-content':openai?'openai-content':'local-template';
  auditEvent(req,'content.generate','ok',{productId:snapshot.id,sku:snapshot.sku,engine,model:ai&&ai._model||''});
  return json(res,200,{success:true,engine,model:ai&&ai._model||'',product:snapshot,content,disclaimer:''});
});

