    message: publisherFix.redact(item.message || '', 500), externalId: cleanLabelText(item.externalId || item.publishId || '', 160),
    publishId: cleanLabelText(item.publishId || '', 160), containerId: cleanLabelText(item.containerId || '', 160),
    stage: cleanLabelText(item.stage || '', 80), visibility: item.visibility || '', requestedVisibility: item.requestedVisibility || '',
