  for(const [key,ms] of windows){const tolerance=Math.max(7*60000,Math.min(2*3600000,ms*.22)),old=kblGoldIntelSampleNear(now-ms,tolerance);if(old&&number(old.xauUsd)>0)out[key]=Number((number(current.xauUsd)-number(old.xauUsd)).toFixed(2));}
