  const deepAttemptAt=String(lastStats.kind||'')==='deep'?lastAttempt:0,deepBase=Math.max(kblIsoMs(aiMasterState.lastDeepAt),deepAttemptAt),deepDue=!deepBase||now-deepBase>=KBL_AI_MASTER_DEEP_MS;
