  const unsafeKbl=/(?:kbl|kim bao lam)[^\n]{0,90}(?:giam|sale|uu dai|khuyen mai|gia chi|gia ban|con hang|chi con|bao hanh|cam ket|loi nhuan|phi doi|tien cong)/i,unsafePromise=/(?:re nhat|so 1|dam bao loi nhuan|cam ket tang gia|chac chan tang|chac chan giam|khong bao gio lo|bao loi|loi nhuan chac chan)/i;
