  if(/\b(ngan sach|duoi [0-9]|trieu|tam gia|gia mem|budget|bao nhieu tien)\b/.test(s))return 'budget-value';
  if(/\b(so sanh|chon mau|chon 1|hay | vs |phu hop hon|3 mau)\b/.test(s))return 'comparison-choice';
  if(/\b(kien thuc|vi sao|cach |luu y|meo|phan biet|ham luong|tuoi vang|bao quan|giai thich)\b/.test(s))return 'education-trust';
  if(/\b(gia vang|thi truong|xau|fed|lai suat|usd|tin nhanh|bien dong|world event|market)\b/.test(s))return 'market-explainer';
