app.post('/api/admin/publisher/media-check',rateLimit('publisher-media-check',20,10*60*1000),async(req,res)=>{
  if(!requireAdmin(req,res))return;
  try {
    let payload;
    if(req.body && req.body.sourceType === 'product') {
      const product=products.find(row=>String(row.id)===String(req.body.productId||''));
      if(!product) return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
      payload=publisherPayloadForPlatform(req,product,'instagram');
    } else {
      const job=publisherVideoJobById(req.body && req.body.videoJobId);
      if(!job || job.status!=='approved') return json(res,409,{success:false,message:'Hãy chọn video đã duyệt.'});
      payload=publisherVideoJobPayload(req,job,'instagram');
    }
    const instagram=await publisherCheckMedia(payload,'instagram');
    const threads=await publisherCheckMedia(payload,'threads');
    const size=instagram.localBytes||instagram.remoteBytes||0;
    const video=Boolean(payload.media.video), limit=video?publisherFix.TELEGRAM_VIDEO_LIMIT:publisherFix.TELEGRAM_PHOTO_LIMIT;
    const telegram={ok:Boolean(size&&size<=limit),bytes:size,message:!size?'Chưa xác định được dung lượng file.':size>limit?`File ${(size/1e6).toFixed(1)} MB vượt giới hạn ${(limit/1e6).toFixed(0)} MB. Xuất bản riêng nhỏ hơn giới hạn rồi duyệt để gửi.`:`File ${(size/1e6).toFixed(1)} MB trong giới hạn upload ${(limit/1e6).toFixed(0)} MB; còn cần Bot/Chat ID hợp lệ.`};
    return json(res,200,{success:true,reports:{instagram,threads,telegram},message:'Chỉ kiểm tra media; không tạo bài hoặc container trên nền tảng.'});
  } catch(error) {return json(res,400,{success:false,message:publisherFix.redact(error.message,500)})}
});
