// KBL E7.3.4 · BACKGROUND LONG VIDEO ANALYSIS SAFE.
// First same-path handler intentionally shadows the legacy synchronous handler below. The old handler
// is kept untouched for rollback/reference, while Admin polls the new status endpoint to avoid proxy 504.
const kblLongVideoAnalysisRunning=new Set();
function kblLongVideoAnalysisState(job){const s=job&&job.longVideoAnalysisState&&typeof job.longVideoAnalysisState==='object'?job.longVideoAnalysisState:{};return {status:String(s.status||((job&&job.longVideoAnalysis)?'done':'idle')),queuedAt:s.queuedAt||'',startedAt:s.startedAt||'',finishedAt:s.finishedAt||'',message:cleanLabelText(s.message||'',400),model:cleanLabelText(s.model||'',120)}}
async function kblRunLongVideoAnalysisBackground(job,req){const id=String(job&&job.id||'');if(!id||kblLongVideoAnalysisRunning.has(id))return;kblLongVideoAnalysisRunning.add(id);const now=new Date().toISOString();job.longVideoAnalysisState={status:'running',queuedAt:job.longVideoAnalysisState&&job.longVideoAnalysisState.queuedAt||now,startedAt:now,finishedAt:'',message:'Gemini đang xem/nghe toàn bộ video trong job nền.',model:''};job.updatedAt=now;persistVideoRenderJobs();try{const built=await kblAnalyzeLongVideo(job),finishedAt=new Date().toISOString();job.longVideoAnalysis={...built.data,engine:'gemini-long-video-bg',model:built.model,analyzedAt:finishedAt};job.script=cleanContentText(built.data.transcriptText||'',12000);job.caption=cleanContentText(built.data.summary||'',5000);job.longVideoAnalysisState={status:'done',queuedAt:job.longVideoAnalysisState.queuedAt,startedAt:job.longVideoAnalysisState.startedAt,finishedAt,message:'AI đã xem/nghe toàn bộ video.',model:built.model};job.updatedAt=finishedAt;persistVideoRenderJobs();auditEvent(req,'publisher.long-video-analyze-bg','ok',{jobId:job.id,model:built.model})}catch(error){const finishedAt=new Date().toISOString(),message=cleanLabelText(error&&error.message||'Không phân tích được video.',400);job.longVideoAnalysisState={status:'error',queuedAt:job.longVideoAnalysisState&&job.longVideoAnalysisState.queuedAt||'',startedAt:job.longVideoAnalysisState&&job.longVideoAnalysisState.startedAt||'',finishedAt,message,model:''};job.updatedAt=finishedAt;persistVideoRenderJobs();auditEvent(req,'publisher.long-video-analyze-bg','error',{jobId:job.id,message})}finally{kblLongVideoAnalysisRunning.delete(id)}}
app.post('/api/admin/publisher/long-video/:id/analyze',rateLimit('publisher-long-video-analyze-bg',30,60*60*1000),(req,res)=>{if(!requireAdmin(req,res))return;const job=publisherVideoJobById(req.params.id);if(!job||!job.longVideoSource)return json(res,404,{success:false,message:'Không tìm thấy video ngoài/video dài.'});if(job.longVideoAnalysis&&typeof job.longVideoAnalysis==='object')return json(res,200,{success:true,analysis:job.longVideoAnalysis,state:kblLongVideoAnalysisState(job),job:kblLongVideoPublicJob(job),message:'Video này đã được AI quét xong.'});if(kblLongVideoAnalysisRunning.has(String(job.id)))return json(res,202,{success:true,queued:true,state:kblLongVideoAnalysisState(job),job:kblLongVideoPublicJob(job),message:'AI đang quét video trong nền.'});const now=new Date().toISOString();job.longVideoAnalysisState={status:'queued',queuedAt:now,startedAt:'',finishedAt:'',message:'Đã xếp AI quét video chạy nền.',model:''};job.updatedAt=now;persistVideoRenderJobs();setImmediate(()=>kblRunLongVideoAnalysisBackground(job,req));return json(res,202,{success:true,queued:true,state:kblLongVideoAnalysisState(job),job:kblLongVideoPublicJob(job),message:'Đã xếp AI QUÉT VIDEO chạy nền. Admin sẽ tự cập nhật; không giữ HTTP chờ Gemini.'})});
