app.get('/api/admin/live/queue',(req,res)=>{
  if(!requireAdmin(req,res))return;
  const rows=products.filter(p=>p&&p.liveSelected&&publisherProductReady(p)).sort((a,b)=>Math.max(0,number(a.liveOrder))-Math.max(0,number(b.liveOrder))).map(productForAdmin);
  return json(res,200,{success:true,queue:rows});
});
app.post('/api/admin/live/toggle/:id',rateLimit('live-toggle',120,10*60*1000),(req,res)=>{
  if(!requireAdmin(req,res))return;
  const product=products.find(item=>String(item.id)===String(req.params.id));
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  const selected=Boolean(req.body&&req.body.selected);
  if(selected&&!publisherProductReady(product))return json(res,409,{success:false,message:'Chỉ đưa vào Live sản phẩm đang còn, đã TRƯNG BÀY và có media đã duyệt.'});
  product.liveSelected=selected;
  if(selected&&!number(product.liveOrder)){const max=Math.max(0,...products.map(p=>Math.floor(number(p&&p.liveOrder))));product.liveOrder=max+1}
  if(!selected)product.liveOrder=0;
  product.updatedAt=new Date().toISOString();writeJson(PRODUCTS_FILE,products);
  return json(res,200,{success:true,product:productForAdmin(product)});
});
app.post('/api/admin/live/reorder',rateLimit('live-reorder',120,10*60*1000),(req,res)=>{
  if(!requireAdmin(req,res))return;
  const ids=Array.isArray(req.body&&req.body.ids)?req.body.ids.map(String).slice(0,50):[];
  const eligibleIds=ids.filter(id=>{const product=products.find(row=>String(row&&row.id)===String(id));return publisherProductReady(product)});
  const map=new Map(eligibleIds.map((id,index)=>[id,index+1]));
  products.forEach(product=>{if(map.has(String(product.id))){product.liveSelected=true;product.liveOrder=map.get(String(product.id))}else if(product.liveSelected&&ids.length){product.liveSelected=false;product.liveOrder=0}});
  writeJson(PRODUCTS_FILE,products);
  return json(res,200,{success:true,queue:products.filter(p=>p.liveSelected&&publisherProductReady(p)).sort((a,b)=>number(a.liveOrder)-number(b.liveOrder)).map(productForAdmin)});
});

app.post('/api/admin/content/source-image', rateLimit('content-source-image', 60, 10 * 60 * 1000), (req,res)=>{
  if(!requireAdmin(req,res))return;
  const input=req.body||{}, productId=String(input.productId||'').trim(), product=products.find(item=>String(item.id)===productId);
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  if(normalizeProductKind(product.kind)!=='current'||String(product.status||'')!=='available'||!cleanInventoryCode(product.sku))return json(res,409,{success:false,message:'Chỉ gắn media gốc cho hàng POS đang còn và có Mã SP.'});
  const image=safeImageSource(input.imageDataUrl);
  if(!image||!image.startsWith('data:image/'))return json(res,400,{success:false,message:'Ảnh gốc phải là JPG/PNG/WebP hợp lệ.'});
  const saved=persistInlineImageToPublic(image,`${product.sku||product.id}-studio-source`);
  if(!saved)return json(res,500,{success:false,message:'Server chưa lưu được ảnh gốc.'});
  const now=new Date().toISOString();product.originalStudioImage=saved;product.originalStudioImageAt=now;product.updatedAt=now;writeJson(PRODUCTS_FILE,products);
  auditEvent(req,'content.source-image-save','ok',{productId:product.id,sku:cleanInventoryCode(product.sku)});
  return json(res,200,{success:true,image:saved,product:productForAdmin(product),manifest:productContentManifest(product),message:'Đã gắn ảnh gốc vào Product Manifest.'});
});
app.post('/api/admin/content/name-suggestions', rateLimit('content-name-suggestions', 30, 10 * 60 * 1000), async (req,res)=>{
  if(!requireAdmin(req,res))return;
  if(!AI_CONTENT_ENABLED)return json(res,503,{success:false,message:'AI Content Studio đang tắt.'});
  if(!GEMINI_API_KEY)return json(res,503,{success:false,message:'Chưa cấu hình Gemini API để AI nhìn ảnh và gợi ý tên.'});
  const input=req.body||{},productId=String(input.productId||'').trim(),product=products.find(item=>String(item.id)===productId);
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  if(normalizeProductKind(product.kind)!=='current'||String(product.status||'')!=='available'||!cleanInventoryCode(product.sku))return json(res,409,{success:false,message:'Chỉ gợi ý tên cho hàng POS đang còn và có Mã SP.'});
  const image=safeImageSource(input.imageDataUrl);
  if(!image||!image.startsWith('data:image/'))return json(res,400,{success:false,message:'Hãy tải ảnh thật của đúng SKU để AI gợi ý tên.'});
  let result;
  try{result=await geminiPendingProductNameSuggestions(product,image)}catch(error){
    const reason=cleanLabelText(error&&error.message||'AI chưa tạo được 5 tên.',260);
    auditEvent(req,'content.name-suggestions','error',{productId:product.id,sku:cleanInventoryCode(product.sku),reason});
    return json(res,502,{success:false,message:reason});
  }
  const now=new Date().toISOString();
  product.aiNameSuggestions=result.names;product.aiNameVisualSummary=result.visualSummary;product.aiNameCategorySuggestion=result.categorySuggestion;product.aiNameSuggestionsAt=now;product.aiNameSuggestionModel=result.model;product.updatedAt=now;writeJson(PRODUCTS_FILE,products);
  auditEvent(req,'content.name-suggestions','ok',{productId:product.id,sku:cleanInventoryCode(product.sku),model:result.model});
  return json(res,200,{success:true,names:result.names,visualSummary:result.visualSummary,categorySuggestion:result.categorySuggestion,model:result.model,product:productForAdmin(product),message:'AI đã đề xuất đúng 5 tên trưng bày. Tên POS vẫn giữ nguyên.'});
});
