app.post('/api/admin/content/source-video/:id', rateLimit('content-source-video', 20, 10 * 60 * 1000), (req,res)=>{
  if(!requireAdmin(req,res))return;
  const product=products.find(item=>String(item.id)===String(req.params.id||''));
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  if(normalizeProductKind(product.kind)!=='current'||String(product.status||'')!=='available'||!cleanInventoryCode(product.sku))return json(res,409,{success:false,message:'Chỉ gắn video gốc cho hàng POS đang còn và có Mã SP.'});
  const mime=String(req.headers['content-type']||'application/octet-stream').toLowerCase().split(';')[0].trim();
  if(!Buffer.isBuffer(req.body)||!req.body.length)return json(res,400,{success:false,message:'Video gốc rỗng hoặc không đọc được.'});
  if(req.body.length>80*1024*1024)return json(res,413,{success:false,message:'Video gốc tối đa 80MB trong V2.'});
  const saved=persistRawVideoToPublic(req.body,mime,`${product.sku||product.id}-studio-source-video`);
  if(!saved)return json(res,400,{success:false,message:'Chỉ nhận MP4, WebM hoặc QuickTime tối đa 80MB.'});
  const now=new Date().toISOString();product.originalStudioVideo=saved;product.originalStudioVideoMime=mime;product.originalStudioVideoSize=req.body.length;product.originalStudioVideoAt=now;product.updatedAt=now;writeJson(PRODUCTS_FILE,products);
  auditEvent(req,'content.source-video-save','ok',{productId:product.id,sku:cleanInventoryCode(product.sku),bytes:req.body.length,mime});
  return json(res,200,{success:true,video:saved,product:productForAdmin(product),manifest:productContentManifest(product),message:'Đã gắn video gốc vào Product Manifest.'});
});


