// E7.3.1 VIDEO AUTO-CARD STABILIZE: không giữ HTTP chờ Gemini để tránh reverse-proxy 504.
// Job RUNNING ở đây nghĩa là AI đang quét nền; Worker chỉ claim khi job chuyển sang PENDING sau khi có cues start/end chính xác.
async function kblRunAutoCardScanBackground(scanJob,input,req){
  if(!scanJob||!input)return;
  try{
    const scan=await kblAnalyzeVideoForAutoCards(input.sourceVideo,input.title),created=kblBuildAutoCardRenderJob(input,scan.data,scan.model,{deferPersist:true});
    if(created.error){scanJob.status='failed';scanJob.completedAt=new Date().toISOString();scanJob.message=cleanLabelText(created.error,500);scanJob.scanAnalysis={engine:'gemini-video-card-scan',model:cleanLabelText(scan.model||'',120),summary:cleanContentText(scan.data&&scan.data.summary||'',2000),matches:[],cautions:Array.isArray(scan.data&&scan.data.cautions)?scan.data.cautions.slice(0,10):[]};persistVideoRenderJobs();auditEvent(req,'video-studio.auto-card-scan','soft-fail',{jobId:scanJob.id,message:scanJob.message});return}
    const built=created.job,keepId=scanJob.id,keepCreatedAt=scanJob.createdAt;
    Object.assign(scanJob,built,{id:keepId,createdAt:keepCreatedAt,status:'review',startedAt:'',claimedAt:'',completedAt:'',approvedAt:'',resultVideo:'',autoCardScanOnly:false,ownerTimingReviewRequired:true,message:`AI đã quét xong và đề xuất mốc card theo lời thoại: ${(built.cues||[]).map(c=>`${c.code} ${Number(c.start).toFixed(2)}–${Number(c.end).toFixed(2)}s`).join(' · ')||'đã có timecode'}. CHỜ CHỦ TIỆM kiểm tra/chỉnh mốc; Worker chưa được phép nhận job.`});
    persistVideoRenderJobs();kblScheduleVisualCardAssets(scanJob);auditEvent(req,'video-studio.auto-card-scan','ok',{jobId:scanJob.id,skus:videoRenderPublicJob(scanJob).cardSkus,model:scan.model,cues:scanJob.cues,visualCards:videoRenderPublicJob(scanJob).visualCardCount});
    setImmediate(async()=>{try{const captions=await kblVideoCaptionV2(scanJob,'viral');scanJob.publisherDrafts={...(captions&&captions.drafts||{}),style:'viral',engine:captions&&captions.engine||'caption-v2-local',updatedAt:new Date().toISOString()};persistVideoRenderJobs()}catch(_){}});
  }catch(error){scanJob.status='failed';scanJob.completedAt=new Date().toISOString();scanJob.message=cleanLabelText(error&&error.message||'AI chưa quét được video.',500);persistVideoRenderJobs();auditEvent(req,'video-studio.auto-card-scan','error',{jobId:scanJob.id,message:scanJob.message})}
}
