  if(!requireAdmin(req,res))return;if(!VIDEO_RENDER_WORKER_TOKEN||VIDEO_RENDER_WORKER_TOKEN.length<MIN_SECRET_LENGTH)return json(res,503,{success:false,message:'Chưa cấu hình KBL_VIDEO_WORKER_TOKEN đủ 32 ký tự.'});if(!GEMINI_VIDEO_API_KEY)return json(res,503,{success:false,message:'Chưa cấu hình Gemini API để AI nghe/xem video và nhận diện nội dung.'});
  resetStaleVideoRenderJobs();const sourceVideo=safeStudioVideoSource(req.body&&req.body.sourceVideo),sourceDuration=Math.max(1,Math.min(300,number(req.body&&req.body.sourceDuration,number(req.body&&req.body.durationSeconds,20)))),title=cleanLabelText(req.body&&req.body.title||'Video đã chỉnh sửa',180);if(!sourceVideo)return json(res,400,{success:false,message:'Hãy upload video đã chỉnh sửa lên trước.'});
