  const now=new Date().toISOString(),scanJob={id:'VID-'+crypto.randomBytes(7).toString('hex').toUpperCase(),template:'product-multi',templateLabel:VIDEO_STUDIO_TEMPLATES['product-multi']&&VIDEO_STUDIO_TEMPLATES['product-multi'].label||'AI Auto Card',status:'running',title,productId:'',sku:'',durationSeconds:Number(sourceDuration.toFixed(2)),width:1080,height:1920,fps:0,fpsMode:'preserve-source',qualityProfile:kblVideoMasterQualityProfile(),sourceVideo,script:'',caption:'',cueMode:'ai-video-scan',cues:[],priceSnapshotAt:'',createdAt:now,startedAt:now,claimedAt:'',completedAt:'',approvedAt:'',resultVideo:'',message:'AI đang xem/nghe video ở chế độ nền và tự tính start/end từng card theo đúng lúc nhắc SKU/giá. Trang có thể tiếp tục dùng, không giữ HTTP chờ Gemini.',attempts:0,autoCardFromVideo:true,autoCardScanOnly:true,scanAnalysis:null,data:{products:[]}};
