app.post('/api/admin/video-studio/cancel/:id',rateLimit('video-studio-cancel',60,10*60*1000),(req,res)=>{
  if(!requireAdmin(req,res))return;
  const job=videoRenderJobs.find((row)=>row&&String(row.id)===String(req.params.id||''));
  if(!job)return json(res,404,{success:false,message:'Không tìm thấy job video.'});
  if(job.status==='approved')return json(res,409,{success:false,message:'Video đã duyệt; không hủy bản đã duyệt.'});
  if(job.status==='canceled')return json(res,200,{success:true,alreadyCanceled:true,job:videoRenderPublicJob(job),queue:videoRenderQueueStatus(),message:'Job đã được hủy trước đó.'});
  if(!['review','pending','running','failed'].includes(String(job.status)))return json(res,409,{success:false,message:'Trạng thái job hiện tại không cần hủy.'});
  const fromStatus=String(job.status||'');
  const now=new Date().toISOString();
  job.status='canceled';job.canceledAt=now;job.completedAt=now;job.ownerTimingReviewRequired=false;
  job.cancelReason=cleanLabelText(req.body&&req.body.reason||'Chủ tiệm hủy để chạy job mới.',220);
  job.message=fromStatus==='running'?'ĐÃ YÊU CẦU HỦY. Worker V5.7D sẽ dừng FFmpeg hiện tại; job mới có thể vào hàng chờ ngay.':'ĐÃ HỦY. Job này không còn chặn hàng đợi; RAW/card snapshot vẫn được giữ để xem lại.';
  persistVideoRenderJobs();auditEvent(req,'video-studio.cancel','ok',{jobId:job.id,fromStatus,reason:job.cancelReason});
  return json(res,200,{success:true,job:videoRenderPublicJob(job),queue:videoRenderQueueStatus(),message:job.message});
});

