app.post('/api/admin/local-ai/generate', rateLimit('local-ai-generate', 20, 10 * 60 * 1000), (req,res)=>{
  if(!requireAdmin(req,res))return;
  if(!AI_PHOTO_STUDIO_ENABLED)return json(res,503,{success:false,message:'AI Photo Studio đang tắt.'});
  if(!LOCAL_AI_WORKER_TOKEN||LOCAL_AI_WORKER_TOKEN.length<MIN_SECRET_LENGTH)return json(res,503,{success:false,message:'Chưa cấu hình KBL_LOCAL_AI_WORKER_TOKEN đủ 32 ký tự trên server.'});
  const input=req.body||{}, productId=String(input.productId||'').trim();
  const product=products.find(item=>String(item.id)===productId);
  if(!product)return json(res,404,{success:false,message:'Không tìm thấy sản phẩm.'});
  if(normalizeProductKind(product.kind)!=='current'||String(product.status||'')!=='available'||!cleanInventoryCode(product.sku))return json(res,409,{success:false,message:'Chỉ tạo ảnh local cho hàng POS đang còn và có Mã SP.'});
  const source=safeImageSource(product.originalStudioImage||product.image);
  if(!source)return json(res,409,{success:false,message:'Hãy tải ẢNH GỐC cho SKU trước khi tạo ảnh Local AI.'});
  resetStaleLocalAiJobs();
  const active=localAiJobs.find(job=>job&&String(job.productId)===productId&&['pending','running'].includes(String(job.status)));
  if(active)return json(res,409,{success:false,message:'SKU này đang có một job Local AI chưa xong.',job:localAiPublicJob(active),localAi:localAiQueueStatus()});
  const styleId=normalizeFlowDisplayStyle(input.displayStyle),campaign=cleanLabelText(input.campaign,160);
  const job=createLocalAiJob(product,styleId,campaign);
  if(!job)return json(res,500,{success:false,message:'Không tạo được job Local AI.'});
  auditEvent(req,'local-ai.generate-queue','ok',{jobId:job.id,productId:product.id,sku:cleanInventoryCode(product.sku),style:styleId});
  return json(res,202,{success:true,job:localAiPublicJob(job),localAi:localAiQueueStatus(),message:localAiQueueStatus().online?'Đã gửi job. Máy Local AI đang online.':'Đã xếp job. Hãy mở ComfyUI và KBL Local AI Worker trên máy tiệm.'});
});
