app.post('/api/sync/warranty-sale', rateLimit('sync-warranty-sale',300,10*60*1000),(req,res)=>{
  if(!requireSync(req,res)) return;
  if(!kblCommerceV5 || typeof kblCommerceV5.warrantiesFromPosSale!=='function') {
    return json(res,503,{success:false,message:'Module bảo hành V5 chưa sẵn sàng.'});
  }
  const input=req.body||{};
  if(String(input.eventType||'sale').toLowerCase()==='return') return json(res,200,{success:true,skipped:true,warranties:[]});
  const phone=phoneKey(input.phone);
  const customer=phone ? (customers.find(item=>phoneKey(item&&item.phone)===phone)||null) : null;
  let sync=null;
  try { sync=kblCommerceV5.warrantiesFromPosSale(input,customer); }
  catch(error){ return json(res,500,{success:false,message:'Không tạo được phiếu bảo hành từ giao dịch POS.'}); }
  if(!sync || !sync.success || !Array.isArray(sync.warranties) || !sync.warranties.length) {
    return json(res,400,{success:false,message:'Chưa đủ Mã SP hợp lệ để cấp phiếu bảo hành.'});
  }
  const forwardedProto=String(req.headers['x-forwarded-proto']||'').split(',')[0].trim();
  const proto=forwardedProto||req.protocol||'https';
  const host=String(req.get('host')||'tiemvangkimbaolam.id.vn').replace(/[\r\n]/g,'');
  const warranties=sync.warranties.map(w=>{
    const token=String(w&&w.publicToken||'').trim();
    return {
      id:String(w&&w.id||''),
      sku:String(w&&w.sku||''),
      token,
      url:token?`${proto}://${host}/bao-hanh/${encodeURIComponent(token)}`:''
    };
  }).filter(w=>w.url);
  return json(res,sync.created?201:200,{success:true,invoiceId:String(input.invoiceId||''),created:Number(sync.created||0),reused:Number(sync.reused||0),warranties});
});

app.post('/api/sync/pawn', (req, res) => {
  if (!requireSync(req, res)) return;
  const incoming = Array.isArray(req.body) ? req.body : (Array.isArray(req.body && req.body.records) ? req.body.records : [req.body]);
  if (incoming.length > 500) return json(res, 413, { success: false, message: 'Một lần chỉ đồng bộ tối đa 500 phiếu.' });
  const mode = String(req.body && !Array.isArray(req.body) && req.body.mode || 'delta').trim().toLowerCase();
  let count = 0;

  incoming.filter(Boolean).forEach((record) => {
    const id = String(record.id || '').trim().slice(0, 100);
    if (!id || /[<>"'\\/]/.test(id)) return;

    // Mã phiếu là khóa ổn định chính. Phiếu rất cũ có thể chưa có publicToken;
    // khi đó giữ token server đã cấp trước đó thay vì tạo token mới mỗi lần sync.
    const existingById = pawnRecords.find((item) => String(item.id || '') === id) || null;
    const rawToken = String(record.publicToken || '').trim();
    const validIncomingToken = /^[a-z0-9_-]{20,128}$/i.test(rawToken) ? rawToken : '';
    const preservedToken = existingById && /^[a-z0-9_-]{20,128}$/i.test(String(existingById.publicToken || ''))
      ? String(existingById.publicToken)
      : '';
    const publicToken = validIncomingToken || preservedToken || normalizePublicToken('');

    const safe = {
      id,
      publicToken,
      name: String(record.name || '').trim().slice(0, 100),
      phone: phoneKey(record.phone).slice(0, 15),
      asset: String(record.asset || '').trim().slice(0, 240),
      money: Math.min(1000000000000, Math.max(0, number(record.money))),
      dateStart: String(record.dateStart || '').slice(0, 30),
      dateEnd: String(record.dateEnd || '').slice(0, 30),
      dateStartRaw: String(record.dateStartRaw || '').slice(0, 30),
      dateEndRaw: String(record.dateEndRaw || '').slice(0, 30),
      interestRate: Math.min(100, Math.max(0, number(record.interestRate, 1.5))),
      feeRate: Math.min(100, Math.max(0, number(record.feeRate, 1.5))),
      tienLai: Math.min(1000000000000, Math.max(0, number(record.tienLai))),
      tienPhi: Math.min(1000000000000, Math.max(0, number(record.tienPhi))),
      status: String(record.status || 'Đang cầm').trim().slice(0, 40),
      updatedAt: new Date().toISOString()
    };

    const idx = pawnRecords.findIndex((item) => (
      String(item.id || '') === safe.id
      || (safe.publicToken && String(item.publicToken || '') === safe.publicToken)
    ));
    if (idx >= 0) pawnRecords[idx] = { ...pawnRecords[idx], ...safe };
    else pawnRecords.push(safe);
    count++;
  });

  savePawns();
  saveControlState({ lastPawnAt: new Date().toISOString() });
  const activeRecords = pawnRecords.filter(pawnIsActive).length;
  const activePrincipal = pawnRecords.filter(pawnIsActive).reduce((sum, item) => sum + Math.max(0, number(item.money)), 0);
  auditEvent(req, 'pawn.sync', 'ok', { count, received: incoming.length, mode, activeRecords });
  json(res, 200, {
    success: true,
    count,
    received: incoming.length,
    mode,
    totalRecords: pawnRecords.length,
    activeRecords,
    activePrincipal,
    message: mode === 'snapshot'
      ? `Đã nhận snapshot ${count}/${incoming.length} phiếu cầm từ POS.`
      : `Đã đồng bộ ${count} phiếu cầm.`
  });
});

function kblTransactionSkuList(input) {
  const src=input&&typeof input==='object'?input:{}; const values=[];
  const push=(v)=>{const sku=cleanInventoryCode(v);if(sku&&!values.some(x=>inventoryCodeKey(x)===inventoryCodeKey(sku)))values.push(sku)};
  (Array.isArray(src.skus)?src.skus:[]).forEach(push);
  push(src.productSku||src.sku||src.maSP||src.invCode);
  (Array.isArray(src.invCodes)?src.invCodes:[]).forEach(push);
  (Array.isArray(src.items)?src.items:[]).forEach(item=>push(item&& (item.sku||item.productSku||item.invCode||item.code||item.maSP)));
  return values.slice(0,100);
}
function kblTransactionProductBySku(sku) {
  const key=inventoryCodeKey(sku); if(!key)return null;
  return products.find((product)=>product&&product.source==='pos'&&inventoryCodeKey(product.sku||product.id)===key)||null;
}
function kblApplyProductTransactionEvent(input) {
  const eventType=String(input&&input.eventType||'').toLowerCase();
  const mode=String(input&&input.mode||'ban').toLowerCase();
  const invoiceId=cleanLabelText(input&&input.invoiceId,100);
  const originalTransactionId=cleanLabelText(input&&input.originalTransactionId,100);
  const atRaw=String(input&&input.at||input&&input.soldAt||'').trim(); const d=atRaw?new Date(atRaw):new Date(); const at=Number.isFinite(d.getTime())?d.toISOString():new Date().toISOString();
  const skus=kblTransactionSkuList(input),changed=[];
  for(const sku of skus){const product=kblTransactionProductBySku(sku);if(!product)continue;const before=String(product.status||'available');
    if(eventType==='sale'){
      product.status='sold';product.posStatus='Đã bán';product.posMissing=false;product.soldInvoiceId=invoiceId;product.soldAt=at;product.returnInvoiceId='';product.returnedAt='';
    }else if(eventType==='return'){
      product.status='unavailable';product.posStatus='Đã trả (Chờ XL)';product.posMissing=false;product.returnInvoiceId=invoiceId;product.returnedAt=at;
    }else if(eventType==='void'){
      if(mode==='tra'){
        product.status='sold';product.posStatus='Đã bán';product.posMissing=false;product.returnInvoiceId='';product.returnedAt='';if(originalTransactionId)product.soldInvoiceId=originalTransactionId;
      }else{
        product.status='available';product.posStatus='Đang bán';product.posMissing=false;product.soldInvoiceId='';product.soldAt='';product.returnInvoiceId='';product.returnedAt='';
      }
    }else if(eventType==='inventory'){
      const incomingStatus=inventoryStatus(input&&input.status||'Đang bán');product.status=incomingStatus;product.posStatus=cleanLabelText(input&&input.status||'',80);product.posMissing=false;
    }
    product.updatedAt=at;product.lastTransactionSyncAt=at;if(String(product.status)!==before||eventType)changed.push({sku:cleanInventoryCode(product.sku),before,status:product.status});
  }
  if(changed.length)writeJson(PRODUCTS_FILE,products);
  return {skus,changed};
}
function kblWarrantyTransactionEvent(input) {
  if(!kblCommerceV5||typeof kblCommerceV5.setWarrantyStatusForInvoice!=='function')return {success:true,skipped:true,updated:0};
  const eventType=String(input&&input.eventType||'').toLowerCase(),mode=String(input&&input.mode||'ban').toLowerCase(),invoiceId=cleanLabelText(input&&input.invoiceId,120),original=cleanLabelText(input&&input.originalTransactionId,120),skus=kblTransactionSkuList(input);
  if(eventType==='return'&&original)return kblCommerceV5.setWarrantyStatusForInvoice(original,'Đã thu hồi do trả hàng',{skus,reason:`Phiếu trả ${invoiceId||''}`});
  if(eventType==='void'&&mode==='tra'&&original)return kblCommerceV5.setWarrantyStatusForInvoice(original,'Đang hiệu lực',{skus,reason:`Đã hủy phiếu trả ${invoiceId||''}`,restore:true});
  if(eventType==='void'&&invoiceId)return kblCommerceV5.setWarrantyStatusForInvoice(invoiceId,'Đã hủy',{skus,reason:'POS đã hủy hóa đơn sai'});
  return {success:true,skipped:true,updated:0};
}
function kblTransactionReconcilePreview(input) {
  const sales=Array.isArray(input&&input.sales)?input.sales.slice(0,20000):[],inventory=Array.isArray(input&&input.inventory)?input.inventory.slice(0,5000):[];
  const saleIds=new Set(sales.map(x=>cleanLabelText(x&&x.id,100)).filter(Boolean));
  const inventoryMap=new Map(); for(const row of inventory){const sku=cleanInventoryCode(row&& (row.code||row.sku||row.id));if(sku)inventoryMap.set(inventoryCodeKey(sku),row)}
  const loyaltyOrphans=[];for(const row of loyaltyLedger){if(!row||!String(row.source||'').startsWith('pos-sync')||row.eventType==='void'||row.reversedBy)continue;const id=cleanLabelText(row.invoiceId,100);if(id&&!saleIds.has(id))loyaltyOrphans.push({invoiceId:id,customerId:String(row.customerId||''),pointsAdded:Math.trunc(number(row.pointsAdded)),realizedProfit:number(row.realizedProfit)})}
  const warrantyOrphans=[];if(kblCommerceV5&&typeof kblCommerceV5.listPosWarrantyOrphans==='function'){try{warrantyOrphans.push(...kblCommerceV5.listPosWarrantyOrphans([...saleIds]));}catch(_){}}
  const productMismatches=[];for(const product of products){if(!product||product.source!=='pos')continue;const key=inventoryCodeKey(product.sku||product.id),row=inventoryMap.get(key);if(!row)continue;const expected=inventoryStatus(row.status||row.trangThai||'Đang bán');if(String(product.status||'available')!==expected)productMismatches.push({sku:cleanInventoryCode(product.sku),website:String(product.status||''),pos:cleanLabelText(row.status||'',80),expected});}
  return {salesCount:saleIds.size,inventoryCount:inventoryMap.size,loyaltyOrphans:loyaltyOrphans.slice(0,200),warrantyOrphans:warrantyOrphans.slice(0,200),productMismatches:productMismatches.slice(0,500),counts:{loyaltyOrphans:loyaltyOrphans.length,warrantyOrphans:warrantyOrphans.length,productMismatches:productMismatches.length}};
}
function kblApplyTransactionReconcile(input, req) {
  const preview=kblTransactionReconcilePreview(input);const loyaltyResults=[];
  for(const row of preview.loyaltyOrphans){const r=reversePosLoyaltyInvoice(row.invoiceId,req,'Đối soát POS: hóa đơn không còn trong sales_db.json');if(r&&r.success)loyaltyResults.push({invoiceId:row.invoiceId,success:true,skipped:Boolean(r.skipped||r.duplicate)});}
  let warrantiesUpdated=0;if(kblCommerceV5&&typeof kblCommerceV5.voidMissingPosWarranties==='function'){try{const ids=(Array.isArray(input&&input.sales)?input.sales:[]).map(x=>cleanLabelText(x&&x.id,100)).filter(Boolean);const r=kblCommerceV5.voidMissingPosWarranties(ids,'Đối soát POS: hóa đơn không còn trong sales_db.json');warrantiesUpdated=number(r&&r.updated);}catch(_){}}
  let productsUpdated=0;const inventory=Array.isArray(input&&input.inventory)?input.inventory:[];for(const row of inventory){const sku=cleanInventoryCode(row&& (row.code||row.sku||row.id));const product=kblTransactionProductBySku(sku);if(!product)continue;const expected=inventoryStatus(row.status||row.trangThai||'Đang bán');if(String(product.status||'available')!==expected){product.status=expected;product.posStatus=cleanLabelText(row.status||'',80);product.posMissing=false;product.updatedAt=new Date().toISOString();product.lastTransactionSyncAt=product.updatedAt;productsUpdated++;}}
  if(productsUpdated)writeJson(PRODUCTS_FILE,products);
  auditEvent(req,'transaction.reconcile','ok',{loyaltyReversed:loyaltyResults.length,warrantiesUpdated,productsUpdated});
  return {preview,applied:{loyaltyReversed:loyaltyResults.length,warrantiesUpdated,productsUpdated},loyaltyResults};
}

