app.post('/api/sync/inventory', (req, res) => {
  if (!requireSync(req, res)) return;
  const incoming = Array.isArray(req.body) ? req.body : (Array.isArray(req.body && req.body.inventory) ? req.body.inventory : []);
  if (incoming.length > 5000) return json(res, 413, { success: false, message: 'Một lần chỉ đồng bộ tối đa 5.000 sản phẩm.' });
  const isSnapshot = Boolean(req.body && !Array.isArray(req.body) && req.body.mode === 'snapshot');
  const syncedAt = new Date().toISOString();
  const seenCodes = new Set();
  let count = 0;
  let created = 0;
  let updated = 0;
  incoming.forEach((item) => {
    if (!item || typeof item !== 'object') return;
    const sku = cleanInventoryCode(item.code || item.maSP || item.maSp || item.productCode || item.maHang || item.id || '');
    const codeKey = inventoryCodeKey(sku);
    if (!codeKey || /[<>"'\\/]/.test(sku)) return;
    seenCodes.add(codeKey);
    const existingIndex = products.findIndex((product) => {
      const existingCode = cleanInventoryCode(product.sku || (product.source === 'pos' ? product.id : ''));
      return inventoryCodeKey(existingCode) === codeKey || String(product.id || '') === sku;
    });
    const existing = existingIndex >= 0 ? products[existingIndex] : null;
    const incomingImage = safeImageSource(item.image || '');
    const image = safeImageSource(existing && existing.image) || incomingImage;
    const name = String(item.name || item.tenHang || existing && existing.name || 'Sản phẩm kho').trim().slice(0, 160);
    const status = inventoryStatus(item.status || item.trangThai || 'Đang bán');
    const supplier = inventorySupplierData(item, existing);
    const product = {
      ...(existing || {}),
      id: existing && existing.id || inventoryProductId(sku),
      sku,
      name,
      category: String(item.category || item.nhom || existing && existing.category || inferProductCategory(name)).trim().slice(0, 80),
      displayCategory: existing && existing.displayCategory
        ? normalizeDisplayCategory(existing.displayCategory, inferProductCategory(name))
        : normalizeDisplayCategory(item.category || item.nhom || inferProductCategory(name), inferProductCategory(name)),
      goldCode: normalizeGoldCode(item.goldCode || item.type || existing && existing.goldCode || '9999'),
      weightChi: inventoryWeightChi(item),
      workmanship: inventoryWorkmanship(item),
      goldCostPrice: Math.max(0, firstFinite(item.goldCostPrice, item.costGoldPrice, existing && existing.goldCostPrice)),
      goldCostTotal: Math.max(0, firstFinite(item.goldCostTotal, item.costGoldTotal, item.costBase, existing && existing.goldCostTotal)),
      originalWage: Math.max(0, firstFinite(item.originalWage, item.costWage, item.workmanshipCost, existing && existing.originalWage)),
      processCost: Math.max(0, firstFinite(item.processCost, existing && existing.processCost)),
      totalCost: Math.max(0, firstFinite(item.totalCost, item.costTotal, existing && existing.totalCost)),
      supplierPurity: Math.min(100, Math.max(0, firstFinite(item.supplierPurity, item.settlementPurity, existing && existing.supplierPurity))),
      sizeLabel: cleanLabelText(item.sizeLabel || item.size || item.ni || item.ringSize || existing && existing.sizeLabel, 80),
      productSymbol: sku,
      attachedWeightChi: inventoryChiField(item, ['attachedWeightChi', 'stoneWeightChi', 'gemWeightChi'], ['gemLy', 'stoneWeightLy'], existing && existing.attachedWeightChi),
      totalWeightChi: inventoryChiField(item, ['totalWeightChi', 'grossWeightChi'], ['grossLy', 'totalWeightLy'], existing && existing.totalWeightChi),
      origin: 'Việt Nam',
      producerName: supplier.name,
      producerCode: supplier.code,
      producerAddress: supplier.address,
      supplierName: supplier.name,
      supplierAddress: supplier.address,
      applicableStandard: supplier.applicableStandard,
      specialMark: cleanLabelText(item.specialMark || item.productFeature || item.symbol || existing && existing.specialMark, 160),
      kind: 'current',
      source: 'pos',
      status,
      posStatus: String(item.status || item.trangThai || 'Đang bán').trim().slice(0, 80),
      publicationStatus: existing ? publicationStatusFor(existing) : 'draft',
      image,
      posMissing: false,
      createdAt: existing && existing.createdAt || syncedAt,
      updatedAt: syncedAt,
      lastSyncedAt: syncedAt
    };
    if (existingIndex >= 0) {
      products[existingIndex] = product;
      updated++;
    } else {
      products.push(product);
      created++;
    }
    count++;
  });
  let markedUnavailable = 0;
  if (isSnapshot) {
    products.forEach((product) => {
      if (product.source !== 'pos') return;
      const key = inventoryCodeKey(product.sku || product.id);
      if (!key || seenCodes.has(key)) return;
      product.status = 'unavailable';
      product.posMissing = true;
      product.posStatus = 'Không còn trong kho POS';
      product.updatedAt = syncedAt;
      markedUnavailable++;
    });
  }
  writeJson(PRODUCTS_FILE, products);
  saveControlState({ lastInventoryAt: syncedAt });
  auditEvent(req, 'inventory.sync', 'ok', { count, created, updated, markedUnavailable, mode: isSnapshot ? 'snapshot' : 'upsert' });
  if(count||markedUnavailable)kblDiscoveryQueueProductSkus([...seenCodes].map(k=>{const p=products.find(x=>inventoryCodeKey(x&&x.sku||x&&x.id)===k);return p&&p.sku||''}).filter(Boolean),'inventory-sync');
  json(res, 200, { success: true, count, created, updated, markedUnavailable, mode: isSnapshot ? 'snapshot' : 'upsert' });
});

app.post('/upload', (req, res) => json(res, 410, { success: false, message: 'Chức năng chụp CCCD chỉ hoạt động trong mạng LAN của phần mềm tiệm.' }));

const blockedWebPaths = ['/data', '/backups', '/audit', '/views', '/node_modules', '/.env', '/app.js', '/package.json', '/package-lock.json'];
app.use((req, res, next) => {
  const requested = String(req.path || '').toLowerCase();
  const blocked = blockedWebPaths.some((base) => requested === base || requested.startsWith(base + '/'));
  if (!blocked) return next();
  return res.status(404).type('text/plain; charset=utf-8').send('Không tìm thấy.');
});






