app.post('/api/admin/international/test-fedex',rateLimit('admin-intl-fedex-test',12,10*60*1000),async(req,res)=>{
  if(!requireAdmin(req,res))return;
  if(!kblIntlFedexConfigured())return json(res,400,{success:false,message:'Chưa có đủ FEDEX_CLIENT_ID / FEDEX_CLIENT_SECRET / FEDEX_ACCOUNT_NUMBER.'});

  try{
    await kblIntlFedexAccessToken();

    if(KBL_INTL_FEDEX_SANDBOX){
      const probe=await kblIntlFedexOfficialVirtualSandboxProbe();
      if(probe&&probe.success){
        const best=probe.rates&&probe.rates[0]||{};
        return json(res,200,{
          success:true,
          provider:'FedEx',
          sandbox:true,
          oauth:true,
          rateApi:true,
          virtualized:true,
          testCase:probe.testCase,
          message:`FedEx OAuth + OFFICIAL VIRTUAL SANDBOX RATE PASS · ${cleanLabelText(best.serviceName||best.serviceType||'Rate API',80)}${best.amount?` · ${number(best.amount).toFixed(2)} ${cleanLabelText(best.currency||'',8)}`:''}. Sandbox FedEx uses canned virtual test cases; this PASS validates API access, not a real Vietnam→Japan price.`
        });
      }

      return json(res,502,{
        success:false,
        provider:'FedEx',
        sandbox:true,
        oauth:true,
        rateApi:false,
        virtualized:true,
        status:probe&&probe.status||0,
        errorCode:probe&&probe.errorCode||'',
        message:`FedEx OAuth OK nhưng OFFICIAL VIRTUAL SANDBOX RATE FAIL${probe&&probe.status?' · HTTP '+probe.status:''}${probe&&probe.errorCode?' · Code '+probe.errorCode:''} · ${cleanLabelText(probe&&probe.message||'FedEx virtualized Rate sample failed',260)}`
      });
    }

    return json(res,200,{
      success:true,
      provider:'FedEx',
      sandbox:false,
      oauth:true,
      rateApi:false,
      message:'FedEx LIVE OAuth OK. Chưa chạy Rate probe tự động trên tài khoản LIVE để tránh tạo giao dịch kiểm tra ngoài ý muốn.'
    });
  }catch(e){
    return json(res,502,{
      success:false,
      provider:'FedEx',
      sandbox:KBL_INTL_FEDEX_SANDBOX,
      oauth:false,
      stage:'oauth',
      message:'FedEx OAuth FAIL · '+cleanLabelText(e.message,220)
    });
  }
});
