async function kblIntlServerTranslateHtml(html,scope='ssr-page'){const parts=String(html||'').split(/(<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>|<noscript\b[\s\S]*?<\/noscript>|<pre\b[\s\S]*?<\/pre>|<code\b[\s\S]*?<\/code>|<[^>]+>)/gi),targets=[],refs=[];for(let i=0;i<parts.length;i++){const part=parts[i];if(!part||part[0]==='<')continue;const m=part.match(/^(\s*)([\s\S]*?)(\s*)$/),core=m&&m[2]||'';if(core.length<2||core.length>1200||!/([A-Za-zÀ-ỹĐđ])/.test(core)||/^(?:KIM BẢO LÂM|Kim Bảo Lâm|KBL|PayPal|FedEx|WhatsApp)$/i.test(core.trim()))continue;targets.push(core);refs.push({i,lead:m[1],tail:m[3]})}let changed=0;for(let start=0;start<targets.length;start+=60){const batch=targets.slice(start,start+60),rows=await kblIntlTranslateBatchCore(batch,'vi','en',scope),map=new Map(rows.map(x=>[x.source,x.text]));for(let j=0;j<batch.length;j++){const ref=refs[start+j],translated=map.get(batch[j])||batch[j];if(translated&&translated!==batch[j])changed++;parts[ref.i]=ref.lead+translated+ref.tail}}return{html:parts.join(''),changed}}
const kblIntlSsrHtmlCache=new Map(),kblIntlSsrHtmlInflight=new Map();
async function kblIntlServerTranslateHtmlCached(cacheKey,filePath,html,scope='ssr-page'){let stat=null;try{stat=fs.statSync(filePath)}catch(_){}const sig=stat?`${stat.size}:${Math.round(stat.mtimeMs)}`:crypto.createHash('sha1').update(String(html||'')).digest('hex'),hit=kblIntlSsrHtmlCache.get(cacheKey);if(hit&&hit.sig===sig)return{...hit.value,cacheHit:true};if(kblIntlSsrHtmlInflight.has(cacheKey)){const x=await kblIntlSsrHtmlInflight.get(cacheKey);return{...x,cacheHit:true}}const job=kblIntlServerTranslateHtml(html,scope).then(value=>{kblIntlSsrHtmlCache.set(cacheKey,{sig,value,at:Date.now()});return value}).finally(()=>kblIntlSsrHtmlInflight.delete(cacheKey));kblIntlSsrHtmlInflight.set(cacheKey,job);const value=await job;return{...value,cacheHit:false}}
