function kblPromaxIsoMs(value){const ms=Date.parse(String(value||''));return Number.isFinite(ms)?ms:0}
function kblPromaxFreshness(updatedAt,maxAgeMinutes){const ms=kblPromaxIsoMs(updatedAt),now=Date.now(),ageMinutes=ms?Math.max(0,Math.round((now-ms)/60000)):null;return{updatedAt:String(updatedAt||''),ageMinutes,maxAgeMinutes:Number(maxAgeMinutes)||0,fresh:Boolean(ms&&ageMinutes<=maxAgeMinutes),status:!ms?'unknown':ageMinutes<=maxAgeMinutes?'fresh':'stale'}}
