function kblPromaxEnsurePolicyHistory(){const current=kblPromaxPolicyVersion();let rows=readJson(KBL_PROMAX_POLICY_HISTORY_FILE,[]);if(!Array.isArray(rows))rows=[];if(!rows.some(x=>x&&x.signature===current.signature)){rows.push({...current,recordedAt:new Date().toISOString()});try{writeJson(KBL_PROMAX_POLICY_HISTORY_FILE,rows)}catch(e){console.warn('[KBL PROMAX] policy history:',e&&e.message)}}return{current,historyCount:rows.length,history:rows.slice().reverse().slice(0,50)}}
function kblPromaxClaimRegistry(){
  const n=kblCanonicalNap(),priceAt=controlState.lastPriceAt||fileUpdatedAt(PRICE_FILE)||'',productAt=kblPromaxLatestProductAt(),policy=kblPromaxPolicyVersion(),exchange=kblPublicExchangeRateSnapshot();
  const claims=[
    {id:'identity.name',type:'locked',value:n.displayName,source:'owner-confirmed canonical KBL identity',expires:false,status:'current'},
    {id:'identity.legal_address',type:'locked',value:n.address,source:'owner-confirmed legal/government address',expires:false,status:'current'},
    {id:'identity.geo',type:'locked',value:n.geo,source:'owner-verified coordinates',expires:false,status:'current'},
    {id:'identity.map_alias',type:'owner-reported',value:n.mapAddressAlias,source:'Google Maps display alias reported by owner',expires:false,status:'current'},
    {id:'identity.phone',type:'locked',value:n.phone,source:'owner-confirmed public phone',expires:false,status:'current'},
    {id:'gold.pos_price_board',type:'dynamic',value:'current KBL POS buy/sell prices',source:'KBL POS prices.json',expires:true,...kblPromaxFreshness(priceAt,180)},
    {id:'exchange.current_adjustments',type:'dynamic',value:{fee610To610PerChi:exchange.fee610To610PerChi,fee980To980PerChi:exchange.fee980To980PerChi,adjustment9999To610PerChi:exchange.adjustment9999To610PerChi},source:exchange.source,expires:true,...kblPromaxFreshness(exchange.updatedAt,1440)},
    {id:'catalog.public_inventory',type:'dynamic',value:'published products and availability',source:'KBL POS/Admin products',expires:true,...kblPromaxFreshness(productAt,1440)},
    {id:'policy.warranty_exchange',type:'versioned',value:policy.version,source:policy.source,expires:false,status:policy.policyFileHash?'current':'unknown',updatedAt:policy.effectiveAt}
  ];
  const summary={current:claims.filter(x=>x.status==='current'||x.status==='fresh').length,stale:claims.filter(x=>x.status==='stale').length,unknown:claims.filter(x=>x.status==='unknown').length,total:claims.length};
  return{version:'KBL-CLAIM-REGISTRY-V1',updatedAt:new Date().toISOString(),summary,claims,guardRule:'Dynamic claims marked stale/unknown must not be presented as a permanent current fact. Re-read the source of truth before quoting a current number.'}
}
function kblPromaxRecommendationQueries(locale='vi'){const rows=kblPromaxVoiceIntentRows(locale);return rows.map(r=>({id:r.id,group:r.group,query:r.query,evidenceUrl:r.evidenceUrl}))}
function kblPromaxRecommendationTests(){let rows=readJson(KBL_PROMAX_RECOMMENDATION_TESTS_FILE,[]);if(!Array.isArray(rows))rows=[];const counts={total:rows.length,foundCorrect:0,foundWrongNap:0,notFound:0,confused:0,cited:0},byPlatform={};for(const r of rows){if(r.outcome==='found_correct')counts.foundCorrect++;if(r.outcome==='found_wrong_nap')counts.foundWrongNap++;if(r.outcome==='not_found')counts.notFound++;if(r.outcome==='confused')counts.confused++;if(r.outcome==='cited')counts.cited++;const p=String(r.platform||'Unknown');if(!byPlatform[p])byPlatform[p]={platform:p,total:0,foundCorrect:0,cited:0,notFound:0,confused:0,foundWrongNap:0,lastTestAt:''};const x=byPlatform[p];x.total++;if(r.outcome==='found_correct')x.foundCorrect++;if(r.outcome==='cited')x.cited++;if(r.outcome==='not_found')x.notFound++;if(r.outcome==='confused')x.confused++;if(r.outcome==='found_wrong_nap')x.foundWrongNap++;if(kblPromaxIsoMs(r.testedAt)>kblPromaxIsoMs(x.lastTestAt))x.lastTestAt=r.testedAt}return{version:'KBL-REAL-AI-RECOMMENDATION-TEST-V1',counts,byPlatform:Object.values(byPlatform),recent:rows.slice().reverse().slice(0,50),truth:'Only manually recorded real external results count here. SAFE PROBE and website readiness never count as an external recommendation.'}}
function kblPromaxRecordRecommendationTest(input){const platform=cleanLabelText(input&&input.platform,40),outcome=String(input&&input.outcome||'').trim(),query=cleanLabelText(input&&input.query,180),queryId=cleanLabelText(input&&input.queryId,40),note=cleanLabelText(input&&input.note,500),sourceUrl=safeHttpsUrl(input&&input.sourceUrl)||'';if(!KBL_PROMAX_RECOMMENDATION_PLATFORMS.has(platform))throw new Error('Nền tảng test không hợp lệ.');if(!KBL_PROMAX_RECOMMENDATION_OUTCOMES.has(outcome))throw new Error('Kết quả test không hợp lệ.');if(!query)throw new Error('Thiếu câu hỏi đã test.');let rows=readJson(KBL_PROMAX_RECOMMENDATION_TESTS_FILE,[]);if(!Array.isArray(rows))rows=[];const row={id:'AIT-'+Date.now().toString(36).toUpperCase()+'-'+crypto.randomBytes(2).toString('hex').toUpperCase(),platform,outcome,queryId,query,note,sourceUrl,testedAt:new Date().toISOString()};rows.push(row);writeJson(KBL_PROMAX_RECOMMENDATION_TESTS_FILE,rows);return row}
function kblPromaxAttribution(){const rows=kblDiscoveryAiReferralSummary();const totalViews=rows.reduce((s,r)=>s+Number(r.pageViews30||0),0),totalLeads=rows.reduce((s,r)=>s+Number(r.leads30||0),0),totalWon=rows.reduce((s,r)=>s+Number(r.won30||0),0),totalRevenue=rows.reduce((s,r)=>s+Number(r.wonRevenue30||0),0);return{version:'KBL-AI-ATTRIBUTION-V2',windowDays:30,summary:{pageViews:totalViews,leads:totalLeads,won:totalWon,wonRevenue:totalRevenue,viewToLeadPct:totalViews?Math.round(totalLeads*10000/totalViews)/100:0,leadToWonPct:totalLeads?Math.round(totalWon*10000/totalLeads)/100:0},sources:rows.map(r=>({...r,trafficSharePct:totalViews?Math.round(Number(r.pageViews30||0)*10000/totalViews)/100:0,viewToLeadPct:Number(r.pageViews30||0)?Math.round(Number(r.leads30||0)*10000/Number(r.pageViews30||0))/100:0,leadToWonPct:Number(r.leads30||0)?Math.round(Number(r.won30||0)*10000/Number(r.leads30||0))/100:0,revenuePerLead:Number(r.leads30||0)?Math.round(Number(r.wonRevenue30||0)/Number(r.leads30||0)):0})),note:'Attribution uses existing KBL referral/UTM traffic and lead/order source data. It does not infer a source when evidence is missing.'}}
function kblPromaxEvidenceHub(){const entity=kblEntityAuthorityStatus(),claims=kblPromaxClaimRegistry(),policy=kblPromaxPolicyVersion(),shield=kblPromaxDisambiguationShield(),voice=kblPromaxVoiceIntentRows('vi'),tests=kblPromaxRecommendationTests();return{success:true,version:'KBL-EVIDENCE-HUB-V1',updatedAt:new Date().toISOString(),canonical:KBL_INTL_PUBLIC_BASE,entity:entity.identity,disambiguation:shield,shortIntents:kblShortIntentSummary('vi'),voiceIntents:{version:'KBL-VOICE-INTENT-V1',count:voice.length,rows:voice},claims,policyVersion:policy,recommendation:{internalReadiness:kblRecommendationReadiness(),realExternalTests:{counts:tests.counts,byPlatform:tests.byPlatform},guaranteed:false},sources:[{key:'entity',label:'Canonical KBL entity',url:KBL_INTL_PUBLIC_BASE+'/api/public/kbl-entity'},{key:'exchange',label:'Published exchange rules',url:KBL_INTL_PUBLIC_BASE+'/vi/doi-vang-doi-ngang-doi-bu'},{key:'prices',label:'Current KBL POS price board',url:KBL_INTL_PUBLIC_BASE+'/vi/gia-vang-hom-nay'},{key:'policy',label:'Published warranty/exchange policy',url:KBL_INTL_PUBLIC_BASE+'/vi/chinh-sach-bao-hanh-doi-tra'},{key:'intents',label:'Short intent evidence',url:KBL_INTL_PUBLIC_BASE+'/vi/hoi-nhanh-tiem-vang'}],truth:'Evidence eligibility is not the same as external ranking. ChatGPT/Gemini/Claude/Perplexity/Bing/Google decide crawling, ranking, citation and recommendation independently.'}}
function kblPromaxHealthStatus(){const nap=kblNapAudit(),claims=kblPromaxClaimRegistry(),policy=kblPromaxPolicyVersion(),tests=kblPromaxRecommendationTests(),voice=kblPromaxVoiceIntentRows('vi'),checks={canonicalNap:Boolean(nap.identityReady),shortIntent:kblShortIntentRows('vi').length>=30,voiceIntent:voice.length>=20,entityDisambiguation:Boolean(kblPromaxDisambiguationShield().canonicalEntity.domain),evidenceHub:true,claimRegistry:claims.summary.unknown===0,policyVersion:Boolean(policy.policyFileHash),referralAnalytics:true,recommendationTestCenter:true,crawlerObservedSeparation:true};const score=Math.round(Object.values(checks).filter(Boolean).length*100/Object.keys(checks).length),warnings=[];for(const c of claims.claims){if(c.status==='stale')warnings.push(`${c.id} stale · ${c.ageMinutes} phút`);if(c.status==='unknown')warnings.push(`${c.id} chưa có timestamp/source`) }if(!tests.counts.total)warnings.push('Chưa ghi nhận bài test AI bên ngoài thật; trạng thái readiness không được tính là recommendation.');return{version:'KBL-AI-PRESENCE-HEALTH-V1',score,checks,warnings,claims:claims.summary,policyVersion:policy.version,recommendationTests:tests.counts,nap:{ready:nap.identityReady,legalAddress:nap.canonical&&nap.canonical.address,mapAlias:nap.canonical&&nap.canonical.mapAddressAlias,geo:nap.canonical&&nap.canonical.geo},note:'Health Monitor chỉ kiểm dữ liệu/hạ tầng KBL. Không tự biến crawler probe thành index/ranking/recommendation.'}}

function kblExchangeServiceSchema(locale='vi'){
  const en=locale==='en',url=KBL_INTL_PUBLIC_BASE+(en?'/en/gold-exchange-trade-in':'/vi/doi-vang-doi-ngang-doi-bu'),n=kblCanonicalNap();
  return{'@context':'https://schema.org','@type':'Service','@id':url+'#service',name:en?'Kim Bao Lam gold exchange and trade-in':'Thu đổi vàng · Đổi Ngang KBL · Đổi Vàng Bù',serviceType:en?'Gold jewelry exchange and trade-in':'Thu đổi trang sức vàng',provider:{'@id':KBL_INTL_PUBLIC_BASE+'/#store'},areaServed:[{'@type':'Place',name:'Tân Đông Hiệp'},{'@type':'Place',name:'Dĩ An'},{'@type':'Place',name:'Bình Dương'}],url,description:en?'KBL gold exchange rules distinguish KBL-origin 610 jewelry from external gold and use current POS prices/configuration.':'KBL phân biệt vàng 610 mua tại KBL với vàng ngoài; số đổi/bù dùng bảng giá và cấu hình POS hiện tại, chốt sau khi cân thực tế.'};
}
function kblSeoProductSchema(p,canonical,locale='vi'){const price=Math.max(0,priceForProduct(p)),img=kblGlobalAiPublicImage(p),grams=Math.round(Math.max(0,number(p.weightChi))*3.75*1000)/1000,en=locale==='en'?kblIntlProductEnglishCached(p):null,name=cleanLabelText(en&&en.name||productDisplayName(p,180),180),category=cleanLabelText(en&&en.category||effectiveProductCategory(p),100),description=cleanLabelText(en&&en.description||p.description||p.detail||'',1200),inStock=String(p.status||'available')==='available'&&publicationStatusFor(p)==='published';return{'@context':'https://schema.org','@type':'Product','@id':canonical+'#product',url:canonical,name,description:description||undefined,sku:cleanInventoryCode(p.sku||p.id),category,brand:{'@type':'Brand',name:'Kim Bảo Lâm'},material:`Gold ${normalizeGoldCode(p.goldCode)}`,image:img||undefined,weight:grams>0?{'@type':'QuantitativeValue',value:grams,unitCode:'GRM'}:undefined,additionalProperty:[{'@type':'PropertyValue',name:'Gold purity code',value:normalizeGoldCode(p.goldCode)},{'@type':'PropertyValue',name:'Weight',value:`${grams} g`},{'@type':'PropertyValue',name:'Decorative stone disclosure',value:'Ordinary glass unless this product has separately verified gemstone/certification data.'}],offers:{'@type':'Offer',url:canonical,priceCurrency:'VND',price:String(Math.round(price)),itemCondition:'https://schema.org/NewCondition',availability:inStock?'https://schema.org/InStock':'https://schema.org/OutOfStock',seller:{'@id':KBL_INTL_PUBLIC_BASE+'/#store'}}}}

app.get(['/vi/gia-vang-hom-nay','/en/gold-price-today'],async(req,res)=>{
  const en=req.path.startsWith('/en/'),locale=en?'en':'vi',pathName=en?'/en/gold-price-today':'/vi/gia-vang-hom-nay';
  let fx={rate:0},world={};try{[fx,world]=await Promise.all([kblIntlFxRate('USD','VND'),kblWorldGoldReference()])}catch(_){}
  const updated=controlState.lastPriceAt||fileUpdatedAt(PRICE_FILE)||new Date().toISOString(),title=en?'Gold prices today | Kim Bao Lam':'Giá vàng hôm nay | Kim Bảo Lâm',desc=en?'Current KBL POS gold prices, XAU/USD reference and Vietcombank USD sell-rate reference.':'Bảng giá vàng KBL từ POS, tham khảo XAU/USD và tỷ giá USD bán ra Vietcombank.';
  const rows=GOLD_RULES.map(r=>`<tr><td>${kblSeoEsc(r.name)}</td><td>${Math.round(number(prices['price_buy_'+r.code])).toLocaleString('vi-VN')} VND/chỉ</td><td>${Math.round(number(prices['price_sell_'+r.code])).toLocaleString('vi-VN')} VND/chỉ</td><td>${kblSeoEsc(r.purity)}</td></tr>`).join('');
  const body=`<h1>${title}</h1><p class="note">${en?'Source of truth: current Kim Bao Lam POS prices. World gold and FX are references only.':'Nguồn chính: giá POS Kim Bảo Lâm hiện tại. Giá thế giới và tỷ giá chỉ để tham khảo.'}</p><p><strong>${en?'Updated':'Cập nhật'}:</strong> ${kblSeoEsc(updated)}</p><table><thead><tr><th>${en?'Gold type':'Loại vàng'}</th><th>${en?'Buy':'Mua vào'}</th><th>${en?'Sell':'Bán ra'}</th><th>${en?'Purity':'Hàm lượng'}</th></tr></thead><tbody>${rows}</tbody></table><h2>XAU/USD & USD/VND</h2><div class="grid"><div class="card">XAU/USD<br><strong>${number(world&&world.xauUsd)>0?number(world.xauUsd).toLocaleString('en-US',{maximumFractionDigits:2})+' USD':'—'}</strong></div><div class="card">Vietcombank USD ${en?'SELL':'BÁN RA'}<br><strong>${kblIntlPricingVndPerUsd(fx)>0?Math.round(kblIntlPricingVndPerUsd(fx)).toLocaleString('vi-VN')+' VND/USD':'—'}</strong></div></div><p><small>${en?'Customer-facing USD display and electronic international checkout use the Vietcombank USD SELL rate.':'Hiển thị USD và thanh toán quốc tế điện tử cho khách dùng tỷ giá USD BÁN RA của Vietcombank.'}</small></p>`;
  const schema={'@context':'https://schema.org','@type':'WebPage',name:title,url:KBL_INTL_PUBLIC_BASE+pathName,dateModified:kblSeoIso(updated)||undefined,about:['gold prices','XAU/USD','USD/VND','Kim Bảo Lâm']};
  res.set('Cache-Control','public, max-age=60, stale-while-revalidate=180');res.type('html').send(kblSeoShell(locale,title,desc,pathName,body,[schema]));
});
