function kblGlobalAiLiveProducts(){return products.filter(p=>p&&publicationStatusFor(p)==='published'&&String(p.status||'available')==='available'&&cleanInventoryCode(p.sku||p.id)&&priceForProduct(p)>0)}
function kblGlobalAiDiscoveryImageDir(){const dir=path.join(PUBLIC_DIR,'uploads','discovery');try{fs.mkdirSync(dir,{recursive:true,mode:0o755})}catch(_){}return dir}
function kblGlobalAiPublicImage(p){
  if(!p)return'';const candidates=[p.displayImage,p.image].map(v=>String(v||'').trim()).filter(Boolean);
  for(const raw of candidates){
    const safe=safeImageSource(raw);
    if(safe&&!/^data:/i.test(safe))return kblSeoAbsolute(safe);
    if(/^data:image\//i.test(raw)){
      const parsed=parseDataImage(raw,8*1024*1024);if(!parsed)continue;
      try{
        const hash=crypto.createHash('sha256').update(parsed.bytes).digest('hex').slice(0,18),sku=(cleanInventoryCode(p.sku||p.id)||'kbl-product').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'').toLowerCase(),ext=extensionForMime(parsed.mimeType),file=`${sku}-${hash}.${ext}`,dir=kblGlobalAiDiscoveryImageDir(),full=path.join(dir,file);
        if(!fs.existsSync(full)||fs.statSync(full).size!==parsed.bytes.length){const tmp=full+'.new';try{fs.writeFileSync(tmp,parsed.bytes,{mode:0o644});if(fs.existsSync(full)){try{fs.unlinkSync(full)}catch(_){}}fs.renameSync(tmp,full);kblHouse2QueueRuntimeFile(full)}catch(e){try{fs.unlinkSync(tmp)}catch(_){}if(!fs.existsSync(full)||fs.statSync(full).size!==parsed.bytes.length)throw e}}
        return KBL_INTL_PUBLIC_BASE+'/uploads/discovery/'+encodeURIComponent(file);
      }catch(e){console.warn('[KBL DISCOVERY IMAGE]',cleanInventoryCode(p.sku||p.id),cleanLabelText(e&&e.message,180));}
    }
  }
  return'';
}
function kblGlobalAiImageAudit(){
  const live=kblGlobalAiLiveProducts(),missing=[],bridged=[];let ready=0;
  for(const p of live){const raw=String(p.displayImage||p.image||''),wasInline=/^data:image\//i.test(raw),url=kblGlobalAiPublicImage(p);if(url){ready++;if(wasInline)bridged.push(cleanInventoryCode(p.sku||p.id))}else if(missing.length<30)missing.push({sku:cleanInventoryCode(p.sku||p.id),name:cleanLabelText(productDisplayName(p,100),100),reason:raw?'Ảnh không chuyển thành URL public hợp lệ':'Chưa có ảnh đã duyệt'})}
  return{published:live.length,ready,missing:Math.max(0,live.length-ready),bridgedInline:bridged.length,sampleBridged:bridged.slice(0,12),sampleMissing:missing};
}
