  products.filter(p=>publicationStatusFor(p)==='published'&&String(p.status||'available')==='available'&&priceForProduct(p)>0).forEach(p=>{const sku=cleanInventoryCode(p.sku||p.id);if(!sku)return;add('/vi/san-pham/'+encodeURIComponent(sku),p.updatedAt||p.lastSyncedAt);add('/en/product/'+encodeURIComponent(sku),p.updatedAt||p.lastSyncedAt)});
  const body='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+[...rows.entries()].map(([u,m])=>`<url><loc>${kblSeoEsc(KBL_INTL_PUBLIC_BASE+u)}</loc>${m?`<lastmod>${m}</lastmod>`:''}</url>`).join('')+'</urlset>';res.set('Cache-Control','public, max-age=300');res.type('application/xml').send(body);
