// ============================================================================
// KBL V5.2 · THAM KHẢO THỊ TRƯỜNG
// TradingView chỉ hiển thị biểu đồ. Server lấy XAU/USD tham khảo từ giavang.org
// và tỷ giá USD/VND từ XML công khai Vietcombank. Mọi quy đổi công khai/khách dùng SELL; BUY chỉ dành cho tính lợi nhuận nội bộ.
// KHÔNG so chênh lệch với giá KBL, không tính/lộ biên lợi nhuận.
// ============================================================================
const KBL_WORLD_GOLD_CACHE_MS = 45 * 1000;
let kblWorldGoldCache = { at:0, value:null };
const KBL_VCB_USD_CACHE_MS = 60 * 1000;
const KBL_VCB_USD_STALE_MAX_MS = 6 * 60 * 60 * 1000;
let kblVcbUsdCache = { at:0, value:null };
async function kblFetchTextUrl(url, timeoutMs=7500){
  if(typeof fetch!=='function')throw new Error('fetch-unavailable');
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);
  try{
    const r=await fetch(url,{signal:controller.signal,headers:{'User-Agent':'Mozilla/5.0 KBL-Market-Reference/5.2','Accept':'text/html,application/xml,text/xml;q=0.9,*/*;q=0.8'},redirect:'follow'});
    if(!r.ok)throw new Error('HTTP '+r.status);
    return await r.text();
  }finally{clearTimeout(timer)}
}
function kblMarketNum(value){
  let s=String(value??'').trim().replace(/\s+/g,'');
  if(!s)return 0;
  if(s.includes(',')&&s.includes('.'))s=s.replace(/,/g,'');
  else if((s.match(/,/g)||[]).length===1&&!s.includes('.')){
    const parts=s.split(',');s=parts[1]&&parts[1].length<=3?parts.join('.'):parts.join('');
  }else s=s.replace(/,/g,'');
  return Number(s.replace(/[^0-9.+-]/g,''))||0;
}
function kblStripHtml(value){return String(value||'').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim()}
function kblVcbRateNum(value){
  const s=String(value??'').trim().replace(/\s+/g,'');if(!s)return 0;
  if(/^\d{1,3}(?:,\d{3})+(?:\.\d+)?$/.test(s))return Number(s.replace(/,/g,''))||0;
  if(/^\d{1,3}(?:\.\d{3})+(?:,\d+)?$/.test(s))return Number(s.replace(/\./g,'').replace(',','.'))||0;
  return kblMarketNum(s);
}
async function kblWorldXauReference(){
  const html=await kblFetchTextUrl('https://giavang.org/the-gioi/',7500),plain=kblStripHtml(html).replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();

  const priceMatch=
    plain.match(/Giá vàng quốc tế\s*\(XAU\)\s*hôm nay là\s*([0-9.,]+)\s*USD/i)
    ||plain.match(/Giá vàng thế giới\s*-?\s*XAU\/USD[^0-9]*([0-9.,]+)\s*USD/i);

  // Primary 24h source: the explicit Vietnamese sentence published by giavang.org.
  const movementMatch=plain.match(
    /Giá vàng thế giới nhìn chung có\s*(tăng|giảm)\s*([0-9.,]+)%\s*trong\s*24\s*giờ(?:\s*qua)?\s*,?\s*tương ứng với\s*(?:tăng|giảm)\s*([0-9.,]+)\s*USD\/Ounce/i
  );

  // Fallback: some page variants expose percentage and USD change separately.
  const directionMatch=plain.match(/Giá vàng thế giới nhìn chung có\s*(tăng|giảm)/i);
  const pctMatch=plain.match(/(?:tăng|giảm)\s*([0-9.,]+)%\s*trong\s*24\s*giờ/i);
  const deltaMatch=plain.match(/tương ứng với\s*(?:tăng|giảm)\s*([0-9.,]+)\s*USD\/Ounce/i);

  // Headline fallback for the magnitudes only, e.g.:
  // 4,476.92 USD 107.65 USD(2.46%)
  const headlineMatch=plain.match(/([0-9.,]+)\s*USD\s+([0-9.,]+)\s*USD\s*\(\s*([0-9.,]+)%\s*\)/i);

  const updateMatch=plain.match(/cập nhật lúc\s*([0-9:]+\s+[0-9/]+)/i);
  const price=kblMarketNum(priceMatch&&priceMatch[1]);

  let directionText='',pct=0,delta=0,changeAvailable=false;
  if(movementMatch){
    directionText=String(movementMatch[1]||'').toLowerCase();
    pct=kblMarketNum(movementMatch[2]);
    delta=kblMarketNum(movementMatch[3]);
    changeAvailable=(pct>0||delta>0);
  }else{
    directionText=String(directionMatch&&directionMatch[1]||'').toLowerCase();
    pct=kblMarketNum(pctMatch&&pctMatch[1]);
    delta=kblMarketNum(deltaMatch&&deltaMatch[1]);
    if(!pct&&headlineMatch)pct=kblMarketNum(headlineMatch[3]);
    if(!delta&&headlineMatch)delta=kblMarketNum(headlineMatch[2]);
    changeAvailable=Boolean(directionText&&(pct>0||delta>0));
  }

  const sign=directionText==='giảm'?-1:directionText==='tăng'?1:0;
  return{
    available:price>0,
    priceUsd:price,
    changeAvailable:Boolean(changeAvailable&&sign),
    direction:sign<0?'down':sign>0?'up':'',
    changePercent:sign?pct*sign:0,
    changeUsd:sign?delta*sign:0,
    updatedAtText:cleanLabelText(updateMatch&&updateMatch[1]||'',48),
    source:'giavang.org'
  };
}
async function kblVietcombankUsdReference(force=false){
  const now=Date.now();
  if(!force&&kblVcbUsdCache.value&&now-kblVcbUsdCache.at<KBL_VCB_USD_CACHE_MS)return kblVcbUsdCache.value;
  try{
    const xml=await kblFetchTextUrl('https://portal.vietcombank.com.vn/Usercontrols/TVPortal.TyGia/pXML.aspx',7500);
    const usd=(xml.match(/<Exrate\b[^>]*\bCurrencyCode=["']USD["'][^>]*>/i)||[])[0]||'';
    const dt=(xml.match(/<DateTime>([^<]+)<\/DateTime>/i)||[])[1]||'';
    const attr=(name)=>{const m=usd.match(new RegExp("\\b"+name+"=[\\\"']([^\\\"']+)[\\\"']","i"));return m?m[1]:''};
    const sell=kblVcbRateNum(attr('Sell')),transfer=kblVcbRateNum(attr('Transfer')),buy=kblVcbRateNum(attr('Buy')),selected=sell,selectedType='USD_SELL';
    const value={available:selected>0,sell,buy,transfer,selectedRate:selected,selectedRateType:selectedType,updatedAtText:cleanLabelText(dt,64),source:'Vietcombank'};
    if(value.available){kblVcbUsdCache={at:now,value};return value}
    if(kblVcbUsdCache.value&&now-kblVcbUsdCache.at<=KBL_VCB_USD_STALE_MAX_MS)return {...kblVcbUsdCache.value,stale:true};
    return value;
  }catch(error){
    if(kblVcbUsdCache.value&&now-kblVcbUsdCache.at<=KBL_VCB_USD_STALE_MAX_MS)return {...kblVcbUsdCache.value,stale:true};
    return {available:false,sell:0,buy:0,transfer:0,selectedRate:0,selectedRateType:'USD_SELL',updatedAtText:'',source:'Vietcombank',error:cleanLabelText(error&&error.message,120)};
  }
}
async function kblWorldGoldReference(force=false){
  const now=Date.now();if(!force&&kblWorldGoldCache.value&&now-kblWorldGoldCache.at<KBL_WORLD_GOLD_CACHE_MS)return kblWorldGoldCache.value;
  const [goldR,fxR]=await Promise.allSettled([kblWorldXauReference(),kblVietcombankUsdReference()]);
  const gold=goldR.status==='fulfilled'?goldR.value:{available:false},fx=fxR.status==='fulfilled'?fxR.value:{available:false};
  const xau=number(gold.priceUsd),sellRate=number(fx.sell),worldRate=sellRate,worldRateType='USD_SELL',vndPerOunce=xau>0&&worldRate>0?xau*worldRate:0,ozGram=31.1034768;
  const value={
    available:xau>0,
    xauUsd:xau,
    changeAvailable:Boolean(gold.changeAvailable),
    direction:cleanLabelText(gold.direction||'',8),
    changeUsd:number(gold.changeUsd),
    changePercent:number(gold.changePercent),
    goldUpdatedAt:gold.updatedAtText||'',
    vcb:{available:worldRate>0,usdSell:sellRate,selectedRate:worldRate,selectedRateType:worldRateType,updatedAt:fx.updatedAtText||'',stale:Boolean(fx.stale)},
    conversion:{ounceVnd:Math.round(vndPerOunce),luong24kVnd:Math.round(vndPerOunce*37.5/ozGram),chi24kVnd:Math.round(vndPerOunce*3.75/ozGram)},
    chart:{provider:'TradingView',symbol:'OANDA:XAUUSD'},
    sources:{gold:'https://giavang.org/the-gioi/',fx:'https://www.vietcombank.com.vn/KHCN/Cong-cu-tien-ich/Ty-gia?devicechannel=default'},
    fetchedAt:new Date().toISOString(),
    disclaimer:'Giá quy đổi công khai cho khách dùng tỷ giá USD BÁN RA (Sell) của Vietcombank. Tỷ giá mua vào chỉ dùng nội bộ để tính lợi nhuận và không phải tỷ giá giao dịch ngoại tệ của Kim Bảo Lâm.'
  };
  if(value.available||value.vcb.available){kblWorldGoldCache={at:now,value};return value}
  if(kblWorldGoldCache.value)return {...kblWorldGoldCache.value,stale:true};
  return value;
}
app.get('/api/market/world-gold',rateLimit('market-world-gold',180,10*60*1000),async(req,res)=>{
  try{const market=await kblWorldGoldReference(String(req.query&&req.query.refresh||'')==='1');return json(res,200,{success:true,market})}
  catch(error){return json(res,503,{success:false,message:'Nguồn tham khảo thị trường tạm thời chưa phản hồi.'})}
});


// Không sửa file home.html đang chạy tốt: chỉ chèn 1 script V5.2 khi phục vụ trang chủ.
async function kblSendHomeV52(_req,res,next){
  try{
    const file=path.join(VIEWS_DIR,'home.html'),html=await fs.promises.readFile(file,'utf8');
    const tags=[
      '<script src="/kbl-market-world-v1.js?v=20260903"></script>',
      '<link rel="stylesheet" href="/kbl-home-polish-v1.css?v=20260903-2">',
      '<script src="/kbl-home-polish-v1.js?v=20260903-2"></script>'
    ];
    let out=html;
    for(const tag of tags){
      const key=(tag.match(/(?:src|href)=\"([^\"]+)/)||[])[1]||tag;
      if(out.includes(key))continue;
      out=/<\/body>/i.test(out)?out.replace(/<\/body>/i,tag+'\n</body>'):out+tag;
    }
    res.set('Cache-Control','no-cache, no-store, must-revalidate');return res.type('html').send(out);
  }catch(e){return next()}
}

