app.use((error, req, res, _next) => {
  const tooLarge = error && (error.type === 'entity.too.large' || error.status === 413);
  const badJson = error && (error.type === 'entity.parse.failed' || error instanceof SyntaxError);
  const errorId='KBL-'+Date.now().toString(36).toUpperCase()+'-'+crypto.randomBytes(2).toString('hex').toUpperCase();
  const detail=cleanLabelText(error&&error.message||'server-error',300);
  try{auditEvent(req, 'request.error', tooLarge ? 'too-large' : badJson ? 'bad-json' : 'server-error',{errorId,path:req&&req.path||'',detail})}catch(_){}
  console.error('KBL REQUEST ERROR',errorId,req&&req.method,req&&req.path,detail);
  if (tooLarge) return json(res, 413, { success: false, message: 'Dữ liệu gửi lên quá lớn.', errorId });
  if (badJson) return json(res, 400, { success: false, message: 'Dữ liệu JSON không hợp lệ.', errorId });
  return json(res, 500, { success: false, message: 'Máy chủ gặp lỗi. Vui lòng thử lại.', errorId });
});

