async function publisherThreadsPublish(req,payload){
  const {token,connector}=await publisherEnsureFreshToken('threads');
  if(!token)throw new Error('Threads chưa liên kết OAuth.');
  if(!publisherHasRequiredScopes('threads',connector))throw new Error('Threads chưa xác minh đủ quyền đăng. Bấm KIỂM TRA TOKEN/QUYỀN.');
  const caption=String(payload.caption||'').slice(0,500),images=publisherPayloadImageUrls(payload,'Threads',20),video=payload.media&&payload.media.video;
  if(!video&&images.length>1){
    const children=[];
    for(const url of images.slice(0,20)){
      const child=await publisherFetchJson('https://graph.threads.net/v1.0/me/threads',{
        method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:publisherFormBody({media_type:'IMAGE',image_url:url,is_carousel_item:'true',access_token:token})
      },'Threads create carousel image');
      const id=String(child.data.id||'');if(!id)throw new Error('Threads không trả child container cho carousel.');children.push(id);
    }
    for(const id of children){
      let ready=false;
      for(let i=0;i<10;i++){
        const status=await publisherFetchJson(`https://graph.threads.net/v1.0/${encodeURIComponent(id)}?`+new URLSearchParams({fields:'id,status,error_message',access_token:token}).toString(),{},'Threads carousel child status');
        const code=String(status.data&&status.data.status||'').toUpperCase();
        if(code==='FINISHED'||code==='PUBLISHED'){ready=true;break}
        if(code==='ERROR'||code==='EXPIRED')throw new Error('Threads báo lỗi xử lý một ảnh trong carousel: '+cleanLabelText(status.data&&status.data.error_message||code,260));
        await new Promise(r=>setTimeout(r,1000));
      }
      if(!ready)throw new Error('Threads chưa xử lý xong ảnh carousel trong thời gian chờ; giữ bài để thử lại sau.');
    }
    const parent=await publisherFetchJson('https://graph.threads.net/v1.0/me/threads',{
      method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:publisherFormBody({media_type:'CAROUSEL',children:children.join(','),text:caption,access_token:token})
    },'Threads create carousel');
    const containerId=String(parent.data.id||'');if(!containerId)throw new Error('Threads không trả parent container cho carousel.');
    const now=new Date().toISOString();
    return {status:'processing',stage:'container',externalId:containerId,containerId,acceptedAt:now,lastCheckedAt:now,checkCount:0,message:`Threads đã nhận carousel ${children.length} ảnh; máy chủ KBL sẽ tự hoàn tất publish.`};
  }
  const params={text:caption,access_token:token};
  const hasMedia=Boolean(video||(payload.media&&payload.media.image));
  if(hasMedia){
    await publisherRequireMetaMedia(payload,'threads');
    if(video){params.media_type='VIDEO';params.video_url=publisherPublicMediaUrl(video,'Threads')}
    else{params.media_type='IMAGE';params.image_url=publisherPublicMediaUrl(payload.media.image,'Threads')}
  }else{params.media_type='TEXT';params.auto_publish_text='true'}
  const create=await publisherFetchJson('https://graph.threads.net/v1.0/me/threads',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:publisherFormBody(params)},'Threads create');
  const containerId=String(create.data.id||'');if(!containerId)throw new Error('Threads không trả ID.');
  if(!hasMedia)return {status:'published',stage:'published',externalId:containerId,url:await publisherPostPermalink('threads',containerId,token),message:'Threads xác nhận auto-publish bài text.'};
  const now=new Date().toISOString();
  return {status:'processing',stage:'container',externalId:containerId,containerId,acceptedAt:now,lastCheckedAt:now,checkCount:0,message:'Threads đã nhận container; máy chủ KBL sẽ kiểm tra và hoàn tất đăng.'};
}

