function kblGrowthFactsStamp(bundle){return JSON.stringify({products:(bundle||[]).map(kblGrowthProductCardFacts),store:kblGrowthStorePosterFacts()})}
function kblGrowthIsReady(prep){return Boolean(prep&&prep.ready&&prep.brandedReady&&prep.mode==='branded'&&prep.designQa?.approved&&prep.factQa?.approved&&prep.qrQa?.approved&&prep.mediaQa?.approved&&prep.posterUrls?.length===3&&prep.posterUrls.every(u=>safeHttpsUrl(u))&&prep.posterResults?.length===3&&prep.posterResults.every(x=>x?.deterministicOverlay&&x?.qrQa?.approved&&Boolean(x?.originalPhoto)===(KBL_GROWTH_POSTER_SOURCE==='original')))}
